// Helper for Tooltip in Recharts (declared at module scope)
const CustomTooltip = ({ active, payload, label }) => {
  if (active && payload && payload.length) {
    const val = payload[0].value
    return (
      <div className="p-2 bg-bg-primary/95 border border-border-color rounded shadow-xl backdrop-blur-md font-mono text-[10px] pointer-events-none">
        <p className="text-muted text-[9px] mb-0.5">{label}</p>
        <p className="font-bold" style={{ color: val >= 0 ? 'var(--success)' : 'var(--danger)' }}>
          {val >= 0 ? `+${val}` : val} XP
        </p>
      </div>
    )
  }
  return null
}

export default function MissionControl() {
  const os = useOS() || {}
  const user = os.auth?.user || null
  const profileHook = os.profile || {}
  const profile = profileHook.profile || null
  const goalsObj = os.goals || {}
  const mainQuest = goalsObj.mainQuest || null
  const sideQuests = goalsObj.sideQuests || []
  const longTermGoals = goalsObj.longTermGoals || []
  const habitsObj = os.habits || {}
  const todayLogs = habitsObj.todayLogs || []
  const habits = habitsObj.habits || []
  const tasksObj = os.tasks || {}
  const tasks = tasksObj.tasks || []
  const addTask = tasksObj.addTask
  const completeTask = tasksObj.completeTask
  const undoCompleteTask = tasksObj.undoCompleteTask
  const fetchTasks = tasksObj.fetchTasks
  const journalObj = os.journal || {}
  const entries = journalObj.entries || []
  const calendarObj = os.calendar || {}
  const events = calendarObj.events || []
  const xpObj = os.xp || {}
  const dailyMomentum = xpObj.dailyMomentum || null
  const completeOperation = os.completeOperation
  const failOperation = os.failOperation
  const undoFailOperation = os.undoFailOperation

  const todayStr = getLocalDateStr()
  const totalXp = profile?.total_xp || 0
  const currentRank = getRankForXp(totalXp)
  const currentArc = ARC_CONFIG.find(a => a.rank === currentRank.code) || ARC_CONFIG[0]
  const currentArcIndex = ARC_CONFIG.findIndex(a => a.rank === currentRank.code)

  // ── Top Level States ──
  const [currentTime, setCurrentTime] = useState(new Date())
  const [xpToday, setXpToday]         = useState(0)
  const [xpThisWeek, setXpThisWeek]   = useState(0)
  const [weeklyWinRate, setWeeklyWinRate] = useState(0)
  const [arcExpanded, setArcExpanded] = useState(false)
  const [sagaRosterOpen, setSagaRosterOpen] = useState(false)
  const [momentumExpanded, setMomentumExpanded] = useState(false)
  const [priorityStatusMap, setPriorityStatusMap] = useState({})
  const [completedEventIds, setCompletedEventIds] = useState(new Set())
  const [activeArtworkIndex, setActiveArtworkIndex] = useState(null)
  const [isAutoCycling, setIsAutoCycling] = useState(true)
  const [quoteIndex, setQuoteIndex] = useState(0)

  const [xpTrajectory, setXpTrajectory] = useState([])
  const [latestDebrief, setLatestDebrief] = useState(null)
  const latestDebriefRef = useRef(null)
  const [todayScreenTime, setTodayScreenTime] = useState(null)
  const [addictionData, setAddictionData] = useState(null)
  const [expandedWidget, setExpandedWidget] = useState(null)

  const [eodWorkData, setEodWorkData] = useState({ logged: false, hours: 0 })
  const [eodSpeakingData, setEodSpeakingData] = useState({ logged: false, detail: '' })
  const [eodQuickLogModal, setEodQuickLogModal] = useState(null)
  const [eodJournalLogged, setEodJournalLogged] = useState(false)

  const [eodScreenForm, setEodScreenForm] = useState({ total_hours: '4', doomscroll_minutes: '30', streaming_hours: '0.5' })
  const [eodJournalForm, setEodJournalForm] = useState({ mood: 'good', content: '' })
  const [eodWorkForm, setEodWorkForm] = useState({ hours: '2', work_type: 'deep_work', notes: '' })
  const [eodSpeakingForm, setEodSpeakingForm] = useState({ topic: '', drive_link: '', notes: '' })

  // ── Top Level Memoized Computations ──
  const todayCalendarEvents = useMemo(() => {
    return (events || []).filter(e => {
      const eDate = e.event_date || e.date || (e.start_time ? e.start_time.split('T')[0] : '')
      return eDate === todayStr
    })
  }, [events, todayStr])

  const todayTasksScheduled = useMemo(() => {
    return (tasks || []).filter(t => t.due_date === todayStr && t.status !== 'cancelled')
  }, [tasks, todayStr])

  const displayedSagaIndex = activeArtworkIndex !== null ? activeArtworkIndex : (currentArcIndex >= 0 ? currentArcIndex : 0)
  const displayedArc = ARC_CONFIG[displayedSagaIndex] || currentArc

  const splitTitle = useMemo(() => {
    const rawName = displayedArc?.name || 'The Spark'
    if (rawName === 'The Discipline Rebuild') return { primary: 'THE DISCIPLINE', secondary: 'REBUILD' }
    const parts = rawName.split(' ')
    if (parts.length === 1) return { primary: 'SAGA', secondary: parts[0].toUpperCase() }
    return { primary: parts.slice(0, -1).join(' ').toUpperCase(), secondary: parts[parts.length - 1].toUpperCase() }
  }, [displayedArc?.name])

  const SAGA_DISCIPLINE_QUOTES = useMemo(() => [
    displayedArc?.flavor || "I rebuilt my mind, habits, and identity one day at a time.",
    "Discipline is choosing between what you want now and what you want most.",
    "Small actions compounded daily become unstoppable momentum.",
    "Stop chasing motivation. Build ironclad routines and relentless consistency.",
    "You do not rise to the level of your goals. You fall to the level of your systems.",
    "The pain of discipline is far less than the pain of regret.",
    "Master self-command before seeking command over anything else.",
    "Every day you don't execute is a day you concede ground."
  ], [displayedArc?.flavor])

  const timeAtmosphere = useMemo(() => {
    const h = currentTime.getHours()
    if (h >= 5 && h < 11) {
      return {
        label: 'Dawn Protocol',
        timeDesc: 'Morning clarity & disciplined momentum',
        accent: '#f59e0b',
        glow: 'rgba(245, 158, 11, 0.22)',
        icon: Sun
      }
    } else if (h >= 11 && h < 17) {
      return {
        label: 'Peak Focus',
        timeDesc: 'Deep work execution & relentless progress',
        accent: '#22d3ee',
        glow: 'rgba(34, 211, 238, 0.22)',
        icon: Zap
      }
    } else if (h >= 17 && h < 21) {
      return {
        label: 'Twilight Consolidation',
        timeDesc: 'Close active loops & review debriefs',
        accent: '#a855f7',
        glow: 'rgba(168, 85, 247, 0.22)',
        icon: Sparkles
      }
    } else {
      return {
        label: 'Night Protocol',
        timeDesc: 'Reflect, recharge & prepare tomorrow',
        accent: '#818cf8',
        glow: 'rgba(129, 140, 248, 0.22)',
        icon: Moon
      }
    }
  }, [currentTime])

  const isDebriefDoneThisWeek = useMemo(() => {
    if (!latestDebrief) return false
    const now = new Date()
    const sortTime = getDebriefSortTime(latestDebrief)
    const titleDateStr = sortTime ? getLocalDateStr(new Date(sortTime)) : ''
    const debriefDateStr = latestDebrief.date || (latestDebrief.created_at ? getLocalDateStr(new Date(latestDebrief.created_at)) : '')
    const effectiveDateStr = titleDateStr || debriefDateStr
    if (!effectiveDateStr) return false

    const dayOfWeek = now.getDay()
    const sunday = new Date(now)
    sunday.setDate(now.getDate() - dayOfWeek)
    sunday.setHours(0, 0, 0, 0)
    const currentCycleStartStr = getLocalDateStr(sunday)

    const sevenDaysAgo = new Date(now)
    sevenDaysAgo.setDate(now.getDate() - 7)
    sevenDaysAgo.setHours(0, 0, 0, 0)
    const sevenDaysAgoStr = getLocalDateStr(sevenDaysAgo)

    return effectiveDateStr >= currentCycleStartStr || effectiveDateStr >= sevenDaysAgoStr
  }, [latestDebrief])

  const nextWeekPriorities = useMemo(() => {
    if (!latestDebrief?.description) return null
    const text = latestDebrief.description
    const marker = '### Priorities for Next Week'
    const idx = text.indexOf(marker)
    if (idx !== -1) {
      let section = text.substring(idx + marker.length).trim()
      const nextHeaderIdx = section.indexOf('### ')
      if (nextHeaderIdx !== -1) section = section.substring(0, nextHeaderIdx).trim()
      if (section) return section
    }

    const lower = text.toLowerCase()
    const fallbackMarkers = [
      'priorities for next week',
      'next week priorities',
      'weekly priorities',
      'priorities'
    ]
    for (const m of fallbackMarkers) {
      const fIdx = lower.indexOf(m)
      if (fIdx !== -1) {
        let section = text.substring(fIdx + m.length).replace(/^[:#\s\n]+/, '').trim()
        const nextH = section.indexOf('### ')
        if (nextH !== -1) section = section.substring(0, nextH).trim()
        if (section) return section
      }
    }
    return null
  }, [latestDebrief])

  const parsedPriorities = useMemo(() => {
    if (!nextWeekPriorities) return []
    const rawItems = nextWeekPriorities
      .split(/(?=\b\d+[\.\)])|\n+/)
      .map(s => s.replace(/^\d+[\.\)]\s*/, '').trim())
      .filter(Boolean)
    if (rawItems.length === 0 && nextWeekPriorities.trim()) {
      return [{ id: 'p1', title: nextWeekPriorities.trim().replace(/^[-*•]\s*(\[[ xXvV✓✕]\])?\s*/, '').replace(/^[xXvV✓✕]\s+/, '').trim(), status: 'pending' }]
    }
    return rawItems.slice(0, 3).map((rawTitle, idx) => {
      let status = 'pending'
      let title = rawTitle
      if (rawTitle.includes('[DONE]')) {
        status = 'completed'
        title = rawTitle.replace('[DONE]', '').trim()
      } else if (rawTitle.includes('[FAILED]')) {
        status = 'failed'
        title = rawTitle.replace('[FAILED]', '').trim()
      }
      title = title
        .replace(/^[-*•]\s*(\[[ xXvV✓✕]\])?\s*/, '')
        .replace(/^[xXvV✓✕]\s+/, '')
        .replace(/^[-*•]\s*/, '')
        .trim()
      return {
        id: `p-${idx + 1}`,
        title,
        status
      }
    })
  }, [nextWeekPriorities])

  const debriefPriorityList = useMemo(() => {
    let sourceList = []

    if (parsedPriorities && parsedPriorities.length > 0) {
      sourceList = parsedPriorities
    } else {
      const fourteenDaysAgo = new Date()
      fourteenDaysAgo.setDate(fourteenDaysAgo.getDate() - 14)
      const fourteenDaysAgoStr = getLocalDateStr(fourteenDaysAgo)

      sourceList = tasks.filter(t => 
        t.category === 'weekly_goal' && 
        t.status !== 'cancelled' &&
        (!t.due_date || t.due_date >= fourteenDaysAgoStr || !t.created_at || t.created_at >= fourteenDaysAgoStr)
      ).slice(0, 3)
    }

    return sourceList.map((item, idx) => {
      let itemTitle = ''
      if (typeof item === 'string') {
        itemTitle = item.trim()
      } else if (item && typeof item === 'object') {
        if (typeof item.title === 'string') itemTitle = item.title.trim()
        else if (item.title && typeof item.title === 'object' && typeof item.title.title === 'string') itemTitle = item.title.title.trim()
        else if (typeof item.name === 'string') itemTitle = item.name.trim()
      }
      if (!itemTitle || itemTitle === '[object Object]') {
        itemTitle = `Priority Goal #${idx + 1}`
      }

      itemTitle = itemTitle
        .replace(/^[-*•]\s*(\[[ xXvV✓✕]\])?\s*/, '')
        .replace(/^[xXvV✓✕]\s+/, '')
        .replace(/^[-*•]\s*/, '')
        .trim()

      const matchingTasks = tasks.filter(t => 
        (item.id && t.id === item.id) ||
        (t.category === 'weekly_goal' && t.title && t.title.trim().toLowerCase() === itemTitle.toLowerCase()) ||
        (t.description && t.description.includes('[Weekly Goal]') && t.title && t.title.trim().toLowerCase() === itemTitle.toLowerCase())
      )

      const completedTask = matchingTasks.find(t => t.status === 'completed')
      const failedTask = matchingTasks.find(t => t.status === 'failed' || t.status === 'cancelled')
      const activeTask = completedTask || failedTask || matchingTasks[0]

      const keyId = activeTask ? activeTask.id : `debrief_p_${idx}_${itemTitle.slice(0, 8)}`
      const stableSourceId = `debrief_p_${itemTitle.trim().toLowerCase().replace(/\s+/g, '_')}`
      const localOverride = priorityStatusMap[keyId] || priorityStatusMap[itemTitle] || priorityStatusMap[stableSourceId]
      const effectiveStatus = localOverride || (item.status !== 'pending' ? item.status : (activeTask ? activeTask.status : 'pending'))

      return {
        id: keyId,
        taskId: activeTask ? activeTask.id : null,
        matchingTaskIds: matchingTasks.map(t => t.id),
        title: itemTitle,
        status: effectiveStatus,
        category: 'weekly_goal'
      }
    })
  }, [parsedPriorities, tasks, priorityStatusMap])

  // ── Top Level Effects ──
  useEffect(() => {
    if (typeof window === 'undefined' || !user) return
    try {
      const saved = localStorage.getItem(`lokios_priority_status_${user.id}`)
      if (saved) {
        const parsed = JSON.parse(saved)
        if (parsed && typeof parsed === 'object') {
          setPriorityStatusMap(parsed)
        }
      }
    } catch (e) {}
  }, [user])

  useEffect(() => {
    latestDebriefRef.current = latestDebrief
  }, [latestDebrief])

  useEffect(() => {
    const t = setInterval(() => setCurrentTime(new Date()), 60000)
    return () => clearInterval(t)
  }, [])

  useEffect(() => {
    if (!isAutoCycling) return
    const interval = setInterval(() => {
      setActiveArtworkIndex(prev => {
        const base = prev === null ? (currentArcIndex >= 0 ? currentArcIndex : 0) : prev
        return (base + 1) % ARC_CONFIG.length
      })
    }, 10000)
    return () => clearInterval(interval)
  }, [isAutoCycling, currentArcIndex])

  useEffect(() => {
    const quoteInterval = setInterval(() => {
      setQuoteIndex(prev => (prev + 1) % SAGA_DISCIPLINE_QUOTES.length)
    }, 10000)
    return () => clearInterval(quoteInterval)
  }, [SAGA_DISCIPLINE_QUOTES.length])

  // Instant cache loader from localStorage for zero-delay initial widget status
  useEffect(() => {
    if (typeof window === 'undefined' || !user) return
    const todayStr = getLocalDateStr(new Date())
    const cacheKey = `lokios_dashboard_recon_${user.id}_${todayStr}`
    try {
      const cached = localStorage.getItem(cacheKey)
      if (cached) {
        const parsed = JSON.parse(cached)
        if (parsed.eodWorkData) setEodWorkData(parsed.eodWorkData)
        if (parsed.eodSpeakingData) setEodSpeakingData(parsed.eodSpeakingData)
        if (parsed.todayScreenTime) setTodayScreenTime(parsed.todayScreenTime)
        if (parsed.latestDebrief) setLatestDebrief(parsed.latestDebrief)
        if (parsed.eodJournalLogged !== undefined) setEodJournalLogged(parsed.eodJournalLogged)
      }
      const rawHist = localStorage.getItem(`lokios_debrief_history_${user.id}`)
      if (rawHist) {
        const parsedHist = JSON.parse(rawHist)
        if (Array.isArray(parsedHist) && parsedHist.length > 0) {
          parsedHist.sort((a, b) => {
            const timeA = getDebriefSortTime(a)
            const timeB = getDebriefSortTime(b)
            if (timeA !== timeB) return timeB - timeA
            return (b.updated_at || b.created_at || '').localeCompare(a.updated_at || a.created_at || '')
          })
          setLatestDebrief(parsedHist[0])
        }
      }
    } catch (e) {
      console.warn('Recon cache read error:', e)
    }
  }, [user])

  useEffect(() => {
    if (!user) return
    async function fetchMetrics() {
      if (!user) return
      const sb = createClient()
      
      const todayStr = getLocalDateStr(new Date())
      
      const currentMonday = new Date()
      const day = currentMonday.getDay()
      const diff = currentMonday.getDate() - day + (day === 0 ? -6 : 1)
      currentMonday.setDate(diff)
      const currentMondayStr = getLocalDateStr(currentMonday)
      
      const thirtyDaysAgo = new Date()
      thirtyDaysAgo.setDate(thirtyDaysAgo.getDate() - 29)
      const thirtyDaysAgoStr = getLocalDateStr(thirtyDaysAgo)

      // 1. Fetch XP Data (Last 30 Days)
      const { data: xpData } = await sb
        .from('xp_history')
        .select('amount, created_at')
        .eq('user_id', user.id)
        .gte('created_at', `${thirtyDaysAgoStr}T00:00:00.000Z`)
        .order('created_at', { ascending: false })
        .limit(5000)

      // Fetch today's screen time log
      const { data: stLogs } = await sb
        .from('screen_time_logs')
        .select('*')
        .eq('user_id', user.id)
        .eq('date', todayStr)
        .limit(1)

      if (stLogs && stLogs.length > 0) {
        setTodayScreenTime(stLogs[0])
      }

      // 1c. Fetch Latest Weekly Debrief (Work Log) from Supabase
      const { data: debriefLogs } = await sb
        .from('work_logs')
        .select('*')
        .eq('user_id', user.id)
        .ilike('title', 'Weekly Debrief%')
        .order('created_at', { ascending: false })
        .limit(30)

      if (debriefLogs && debriefLogs.length > 0) {
        // Group by title / cycle to deduplicate any duplicate entries across devices
        const debriefMap = new Map()
        debriefLogs.forEach(d => {
          const key = d.title ? d.title.trim().toLowerCase() : (d.date || d.id)
          const existing = debriefMap.get(key)
          if (!existing) {
            debriefMap.set(key, d)
          } else {
            const timeExisting = new Date(existing.updated_at || existing.created_at || 0).getTime()
            const timeNew = new Date(d.updated_at || d.created_at || 0).getTime()
            if (timeNew > timeExisting) {
              debriefMap.set(key, d)
            }
          }
        })

        const sortedDebriefs = Array.from(debriefMap.values()).sort((a, b) => {
          const timeA = getDebriefSortTime(a)
          const timeB = getDebriefSortTime(b)
          if (timeA !== timeB) return timeB - timeA
          return (b.updated_at || b.created_at || '').localeCompare(a.updated_at || a.created_at || '')
        })

        if (sortedDebriefs.length > 0) {
          setLatestDebrief(sortedDebriefs[0])
          if (typeof window !== 'undefined') {
            try {
              localStorage.setItem(`lokios_debrief_history_${user.id}`, JSON.stringify(sortedDebriefs))
              const cacheKey = `lokios_dashboard_recon_${user.id}_${todayStr}`
              const existingCache = localStorage.getItem(cacheKey)
              const parsed = existingCache ? JSON.parse(existingCache) : {}
              parsed.latestDebrief = sortedDebriefs[0]
              localStorage.setItem(cacheKey, JSON.stringify(parsed))
            } catch (errCache) {}
          }
        }
      } else if (typeof window !== 'undefined') {
        try {
          const rawHist = localStorage.getItem(`lokios_debrief_history_${user.id}`)
          if (rawHist) {
            const parsed = JSON.parse(rawHist)
            if (Array.isArray(parsed) && parsed.length > 0) {
              parsed.sort((a, b) => {
                const timeA = getDebriefSortTime(a)
                const timeB = getDebriefSortTime(b)
                if (timeA !== timeB) return timeB - timeA
                return (b.created_at || '').localeCompare(a.created_at || '')
              })
              setLatestDebrief(parsed[0])
            }
          }
        } catch (err) {}
      }
        
      if (xpData) {
        // Today & This Week (NET XP including penalties)
        setXpThisWeek(xpData.filter(r => {
          const rDateStr = getLocalDateStr(new Date(r.created_at))
          return rDateStr >= currentMondayStr
        }).reduce((s, r) => s + r.amount, 0))

        setXpToday(xpData.filter(r => {
          const rDateStr = getLocalDateStr(new Date(r.created_at))
          return rDateStr === todayStr
        }).reduce((s, r) => s + r.amount, 0))
        
        // 30-Day Trajectory Graph (includes both gains and penalties mapped to local dates)
        const xpByDate = {}
        xpData.forEach(r => {
          const dateStr = getLocalDateStr(new Date(r.created_at))
          xpByDate[dateStr] = (xpByDate[dateStr] || 0) + r.amount
        })

        const graphData = []
        for (let i = 29; i >= 0; i--) {
          const d = new Date()
          d.setDate(d.getDate() - i)
          const dStr = getLocalDateStr(d)
          graphData.push({
            date: d.toLocaleDateString('en-US', { month: 'short', day: 'numeric' }),
            xp: xpByDate[dStr] || 0
          })
        }
        setXpTrajectory(graphData)
      }

      // 2. Fetch ALL Habit Logs (for Ghost Score, Win Rate, Graveyard)
      const { data: allHabitLogs } = await sb
        .from('habit_logs')
        .select('date, status, habit_id')
        .eq('user_id', user.id)
        .order('date', { ascending: false })
        .limit(5000)

      const { data: allHabitsData } = await sb
        .from('habits')
        .select('id, title')
        .eq('user_id', user.id)

      if (allHabitLogs) {
        // Weekly Win Rate (This week from Monday)
        const recentLogs = allHabitLogs.filter(l => l.date >= currentMondayStr)
        const uniqueDaysWithCompletion = new Set(
          recentLogs.filter(log => log.status === 'completed').map(log => log.date)
        ).size
        
        // Calculate days elapsed in the current week so far (Monday = 1 day elapsed)
        let daysElapsed = new Date().getDay()
        if (daysElapsed === 0) daysElapsed = 7 // Sunday is the 7th day
        
        setWeeklyWinRate(Math.round((uniqueDaysWithCompletion / daysElapsed) * 100))
      }

      // ── Digital Addiction Widget ──
      const sevenDaysAgo = new Date()
      sevenDaysAgo.setDate(sevenDaysAgo.getDate() - 7)
      const sevenDaysAgoStr = getLocalDateStr(sevenDaysAgo)
      const { data: stHistory } = await sb.from('screen_time_logs')
        .select('*').eq('user_id', user.id)
        .gte('date', sevenDaysAgoStr)
        .order('date', { ascending: false })

      if (stHistory && stHistory.length > 0) {
        const getDoom = (l) => parseInt(l.doom_scroll_minutes ?? l.doomscroll_minutes) || 0
        const avgScreenNum = stHistory.reduce((s, l) => s + (parseFloat(l.total_hours) || 0), 0) / stHistory.length
        const avgScreen = avgScreenNum.toFixed(1)
        const avgDoom = Math.round(stHistory.reduce((s, l) => s + getDoom(l), 0) / stHistory.length)
        const avgStreamingNum = stHistory.reduce((s, l) => s + (parseFloat(l.streaming_hours) || 0), 0) / stHistory.length
        const avgStreaming = avgStreamingNum.toFixed(1)
        const todaySt = stHistory.find(l => l.date === todayStr)
        // Clean day definition: Screen Time < 6h, Doomscroll < 60m, Streaming < 1h
        const daysClean = stHistory.filter(l => (parseFloat(l.total_hours) || 0) < 6 && getDoom(l) < 60 && (parseFloat(l.streaming_hours) || 0) < 1).length

        // Addiction / Threat Score (0 to 100). Higher = worse.
        let addScore = 0
        // Factor 1: 7d avg screen time (target < 6h)
        if (avgScreenNum > 10) addScore += 35
        else if (avgScreenNum > 8) addScore += 25
        else if (avgScreenNum >= 6) addScore += 15

        // Factor 2: 7d avg doomscroll (target < 60m)
        if (avgDoom > 120) addScore += 35
        else if (avgDoom > 90) addScore += 25
        else if (avgDoom >= 60) addScore += 15

        // Factor 3: Today's screen time (target < 6h)
        if (!todaySt) addScore += 15
        else if ((parseFloat(todaySt.total_hours) || 0) > 8) addScore += 25
        else if ((parseFloat(todaySt.total_hours) || 0) >= 6) addScore += 15

        // Factor 4: Clean days in last 7 (target >= 5)
        if (daysClean < 3) addScore += 20
        else if (daysClean < 5) addScore += 10

        // Factor 5: Streaming avg (target < 1h)
        if (avgStreamingNum >= 1) addScore += 10

        addScore = Math.min(100, Math.max(0, addScore))
        setAddictionData({ avgScreen, avgDoom, avgStreaming, daysClean, addScore, todaySt, total: stHistory.length })
      } else {
        setAddictionData({ avgScreen: '—', avgDoom: 0, avgStreaming: '0', daysClean: 0, addScore: 50, todaySt: null, total: 0 })
      }

      // Check work_hours_logs first (primary work logging table)
      const { data: workHoursLogRows } = await sb
        .from('work_hours_logs')
        .select('*')
        .eq('user_id', user.id)
        .eq('date', todayStr)
        .limit(1)

      let workLogged = false
      let workHours = 0
      if (workHoursLogRows && workHoursLogRows.length > 0) {
        workLogged = true
        workHours = Number(workHoursLogRows[0].total_hours_worked) || Number(workHoursLogRows[0].hours) || Number(workHoursLogRows[0].duration_hours) || 0
      } else {
        // Fallback: check work_logs but EXCLUDE speaking_practice entries
        const { data: directWorkLogs } = await sb
          .from('work_logs')
          .select('*')
          .eq('user_id', user.id)
          .eq('date', todayStr)
          .neq('type', 'speaking_practice')
          .limit(1)
        if (directWorkLogs && directWorkLogs.length > 0) {
          workLogged = true
          workHours = Number(directWorkLogs[0].total_hours_worked) || Number(directWorkLogs[0].duration_hours) || Number(directWorkLogs[0].hours) || 0
        }
      }
      setEodWorkData({ logged: workLogged, hours: workHours })

      // Fetch Today Speaking Practice Log
      const { data: todaySpeakingLog } = await sb
        .from('speaking_logs')
        .select('*')
        .eq('user_id', user.id)
        .eq('date', todayStr)
        .maybeSingle()

      if (todaySpeakingLog) {
        setEodSpeakingData({ logged: true, detail: `Topic: ${todaySpeakingLog.topic}` })
      } else {
        const localData = typeof window !== 'undefined' ? localStorage.getItem(`lokios_speaking_logs_${user.id}`) : null
        if (localData) {
          try {
            const parsed = JSON.parse(localData)
            const found = parsed.find(p => p.date === todayStr)
            if (found) setEodSpeakingData({ logged: true, detail: `Topic: ${found.topic}` })
            else setEodSpeakingData({ logged: false, detail: '' })
          } catch (e) {
            setEodSpeakingData({ logged: false, detail: '' })
          }
        } else {
          setEodSpeakingData({ logged: false, detail: '' })
        }
      }

      try {
        const cacheKey = `lokios_dashboard_recon_${user.id}_${todayStr}`
        localStorage.setItem(cacheKey, JSON.stringify({
          eodWorkData: { logged: workLogged, hours: workHours },
          eodSpeakingData: todaySpeakingLog ? { logged: true, detail: `Topic: ${todaySpeakingLog.topic}` } : { logged: false, detail: '' },
          todayScreenTime: stLogs && stLogs.length > 0 ? stLogs[0] : null,
          latestDebrief: debriefLogs && debriefLogs.length > 0 ? debriefLogs[0] : null,
          eodJournalLogged: (entries || []).some(e => e.date === todayStr)
        }))
      } catch (e) {}
    }
    fetchMetrics()

    const sb = createClient()
    const channel = sb
      .channel(`dashboard_realtime_sync_${user.id}`)
      .on('postgres_changes', { event: '*', schema: 'public', table: 'work_logs', filter: `user_id=eq.${user.id}` }, () => {
        fetchMetrics()
      })
      .on('postgres_changes', { event: '*', schema: 'public', table: 'work_hours_logs', filter: `user_id=eq.${user.id}` }, () => {
        fetchMetrics()
      })
      .on('postgres_changes', { event: '*', schema: 'public', table: 'tasks', filter: `user_id=eq.${user.id}` }, () => {
        fetchMetrics()
      })
      .on('postgres_changes', { event: '*', schema: 'public', table: 'screen_time_logs', filter: `user_id=eq.${user.id}` }, () => {
        fetchMetrics()
      })
      .on('postgres_changes', { event: '*', schema: 'public', table: 'xp_history', filter: `user_id=eq.${user.id}` }, () => {
        fetchMetrics()
      })
      .subscribe()

    const handleResume = () => {
      if (document.visibilityState === 'visible') fetchMetrics()
    }
    window.addEventListener('focus', handleResume)
    document.addEventListener('visibilitychange', handleResume)

    return () => {
      if (channel && sb?.removeChannel) {
        sb.removeChannel(channel)
      }
      window.removeEventListener('focus', handleResume)
      document.removeEventListener('visibilitychange', handleResume)
    }
  }, [user, todayLogs])

  const updatePriorityStatus = (entries) => {
    setPriorityStatusMap(prev => {
      const next = { ...prev, ...entries }
      if (typeof window !== 'undefined' && user) {
        try {
          localStorage.setItem(`lokios_priority_status_${user.id}`, JSON.stringify(next))
        } catch (e) {}
      }
      return next
    })
  }

  const toggleEventCompleted = (id) => {
    setCompletedEventIds(prev => {
      const next = new Set(prev)
      if (next.has(id)) next.delete(id)
      else next.add(id)
      return next
    })
  }

  // ── Quick Log Submit Handlers for EOD Recon ──
  const submitEodScreen = async (e) => {
    e.preventDefault()
    if (!user) return
    const payload = {
      user_id: user.id,
      date: todayStr,
      total_hours: parseFloat(eodScreenForm.total_hours) || 0,
      doom_scroll_minutes: parseInt(eodScreenForm.doomscroll_minutes) || 0,
      streaming_hours: parseFloat(eodScreenForm.streaming_hours) || 0
    }
    // Optimistic UI updates (0ms delay)
    setTodayScreenTime(payload)
    setEodQuickLogModal(null)

    // Background DB sync with upsert and dynamic XP calculation
    const sb = createClient()
    const { data } = await sb.from('screen_time_logs')
      .upsert(payload, { onConflict: 'user_id,date' })
      .select()
      .single()
    const saved = data || payload
    setTodayScreenTime(saved)
    await syncScreenTimeXP(user.id, saved)
    await profileHook?.fetchProfile?.()
    fetchMetrics()
  }

  const submitEodJournal = async (e) => {
    e.preventDefault()
    if (!user || !eodJournalForm.content.trim()) return
    const payload = {
      user_id: user.id,
      date: todayStr,
      mood: eodJournalForm.mood,
      content: eodJournalForm.content
    }
    // Optimistic UI updates (0ms delay)
    setEodJournalLogged(true)
    setEodQuickLogModal(null)

    // Background DB sync
    const sb = createClient()
    await sb.from('journal_entries').insert(payload)
  }

  const submitEodWork = async (e) => {
    e.preventDefault()
    if (!user) return
    const hrs = parseFloat(eodWorkForm.hours) || 0
    const cleanNotes = (eodWorkForm.notes || '').trim()

    // Optimistic UI updates (0ms delay)
    setEodWorkData({ logged: true, hours: hrs })
    setEodQuickLogModal(null)

    if (typeof window !== 'undefined') {
      const cacheKey = `lokios_dashboard_recon_${user.id}_${todayStr}`
      try {
        const cached = localStorage.getItem(cacheKey)
        const parsed = cached ? JSON.parse(cached) : {}
        parsed.eodWorkData = { logged: true, hours: hrs }
        localStorage.setItem(cacheKey, JSON.stringify(parsed))
      } catch (errCache) {}
    }

    // Background DB sync
    try {
      const sb = createClient()
      const cleanWorkHoursData = {
        user_id: user.id,
        date: todayStr,
        total_hours_worked: hrs,
        focused_hours: hrs,
        beyond_tatva_hours: 0,
        unfocused_hours: 0,
        deep_execution_hours: 0,
        notes: cleanNotes,
        updated_at: new Date().toISOString()
      }

      await sb.from('work_hours_logs').upsert(cleanWorkHoursData, { onConflict: 'user_id,date' })

      const cleanWorkLogData = {
        user_id: user.id,
        date: todayStr,
        title: eodWorkForm.work_type ? `Work Session (${eodWorkForm.work_type})` : 'Work Session',
        type: 'project_work',
        description: cleanNotes,
        duration_hours: hrs,
        total_hours_worked: hrs,
        focused_hours: hrs,
        notes: cleanNotes,
        updated_at: new Date().toISOString()
      }

      const { data: existingWorkLog } = await sb
        .from('work_logs')
        .select('id')
        .eq('user_id', user.id)
        .eq('date', todayStr)
        .limit(1)

      if (existingWorkLog && existingWorkLog.length > 0) {
        await sb.from('work_logs').update(cleanWorkLogData).eq('id', existingWorkLog[0].id)
      } else {
        await sb.from('work_logs').insert(cleanWorkLogData)
      }
    } catch (err) {
      console.error('submitEodWork error:', err)
    }
  }

  const submitEodSpeaking = async (e) => {
    if (e && e.preventDefault) e.preventDefault()
    if (!user) return

    let formattedLink = eodSpeakingForm.drive_link.trim()
    if (formattedLink && !formattedLink.startsWith('http://') && !formattedLink.startsWith('https://')) {
      formattedLink = `https://${formattedLink}`
    }

    const topicName = eodSpeakingForm.topic.trim() || 'Daily Speaking Practice'

    const payload = {
      user_id: user.id,
      date: todayStr,
      topic: topicName,
      drive_link: formattedLink,
      notes: eodSpeakingForm.notes.trim(),
      prep_duration_minutes: 10,
      rating: 5,
      created_at: new Date().toISOString()
    }
    // Optimistic UI updates (0ms delay)
    setEodSpeakingData({ logged: true, detail: `Topic: ${topicName}` })
    setEodQuickLogModal(null)

    // Save to local storage first for 100% phone reliability
    const localData = localStorage.getItem(`lokios_speaking_logs_${user.id}`)
    const parsed = localData ? JSON.parse(localData) : []
    const updatedLocal = [payload, ...parsed.filter(p => p.date !== todayStr)]
    localStorage.setItem(`lokios_speaking_logs_${user.id}`, JSON.stringify(updatedLocal))

    // Background DB sync to dual tables (speaking_logs AND work_logs for 100% cross-device sync)
    const sb = createClient()
    try {
      await sb.from('speaking_logs').insert(payload)
    } catch (spErr) {
      console.warn('speaking_logs insert error:', spErr)
    }

    try {
      await sb.from('work_logs').insert({
        user_id: user.id,
        date: todayStr,
        title: `Speaking Practice: ${topicName}`,
        description: eodSpeakingForm.notes.trim() || topicName,
        type: 'speaking_practice',
        media_urls: formattedLink ? [formattedLink] : [],
        duration_hours: 0.25,
        created_at: new Date().toISOString()
      })
    } catch (wlErr) {
      console.warn('work_logs insert error:', wlErr)
    }
  }

  // ── Derived values ────────────────────────────────────────────────────────
  const currentStreak = profile?.current_streak ?? profile?.streak_days ?? 0

  const journalLoggedToday = (entries || []).some(e => e.date === todayStr) || eodJournalLogged
  const screenIntelLoggedToday = !!todayScreenTime && todayScreenTime.date === todayStr

  const eodItems = [
    {
      key: 'work',
      label: 'Work Session',
      subtitle: 'Work hours & tasks completed',
      isDone: eodWorkData.logged,
      detail: eodWorkData.logged ? `${eodWorkData.hours} hrs logged` : 'No work hours logged today',
      path: '/work',
      icon: Briefcase,
      color: '#A78BFA'
    },
    {
      key: 'journal',
      label: 'Journal Entry',
      subtitle: 'Daily reflection & emotional debrief',
      isDone: journalLoggedToday,
      detail: journalLoggedToday ? 'Daily entry written' : 'No journal entry written today',
      path: '/journal',
      icon: BookOpen,
      color: '#60A5FA'
    },
    {
      key: 'screen',
      label: 'Screen Intel',
      subtitle: 'Digital discipline & screen time',
      isDone: screenIntelLoggedToday,
      detail: screenIntelLoggedToday ? `${todayScreenTime.total_hours || 0} hrs logged` : 'Screen intel missing for today',
      path: '/screen-time',
      icon: Smartphone,
      color: '#22c55e'
    },
    {
      key: 'speaking',
      label: 'Speaking Practice',
      subtitle: '30-day camera challenge & video proof',
      isDone: eodSpeakingData.logged,
      detail: eodSpeakingData.detail || (eodSpeakingData.logged ? 'Video proof logged' : 'No speaking practice today'),
      path: '/speaking',
      icon: Mic,
      color: '#EAB308'
    }
  ]

  const eodCompletedCount = eodItems.filter(i => i.isDone).length
  const isEodAllDone = eodCompletedCount === eodItems.length
  const longestStreak = profile?.longest_streak ?? 0

  const currentLevel                                           = calculateLevel(totalXp)
  const { current: xpInLevel, required: xpForNextLevel, percentage: levelPct } = xpToNextLevel(totalXp)
  const xpNeeded     = Math.max(0, xpForNextLevel - xpInLevel)
  const currentRankConfig = RANK_CONFIG[currentRank.code] || RANK_CONFIG['I']
  const arcColor     = currentRankConfig?.color || '#9CA3AF'
  const sagaAccentColor = currentRankConfig?.color || '#f97316'
  const momentumStateColor = dailyMomentum?.color || 'var(--warning)'
  const nextArc      = ARC_CONFIG[currentArcIndex + 1] || null

  const minSagaXp = currentRankConfig.minXp || 0
  const maxSagaXp = currentRankConfig.maxXp || 4999
  const currentXpInSaga = Math.max(0, totalXp - minSagaXp)
  const totalXpInSaga = Math.max(1, maxSagaXp - minSagaXp + 1)
  const sagaProgressPct = Math.min(100, Math.max(0, Math.round((currentXpInSaga / totalXpInSaga) * 100)))

  const currentSagaImage = SAGA_IMAGES[currentRank.code] || SAGA_IMAGES['I'] || '/sagas/Awakening.png'

  // Active artwork & saga display (auto-cycling or user selected)
  const displayedRankConfig = RANK_CONFIG[displayedArc.rank] || RANK_CONFIG['I']
  const displayedSagaImage = SAGA_IMAGES[displayedArc.rank] || SAGA_IMAGES['I'] || '/sagas/Awakening.png'
  const displayedSagaColor = displayedRankConfig?.color || sagaAccentColor

  const handleNextQuote = () => {
    setQuoteIndex(prev => (prev + 1) % SAGA_DISCIPLINE_QUOTES.length)
  }

  const hoursLeft = +(24 - currentTime.getHours() - currentTime.getMinutes() / 60).toFixed(1)
  const dayPct    = Math.round(((currentTime.getHours() * 60 + currentTime.getMinutes()) / 1440) * 100)
  const dayUrgency = dayPct > 80 ? 'danger' : dayPct > 60 ? 'warning' : 'ok'

  const flameColor = currentStreak >= 30 ? '#F59E0B' : currentStreak >= 7 ? '#f97316' : '#ef4444'

  // todayStr is defined at the top of component

  // ── Dynamic Daily Ops Momentum Engine (-10 to +10) ────────────────────────
  // 1. Habits Performance (Completed vs Failed Today)
  const habitsCompletedToday = (todayLogs || []).filter(l => l.date === todayStr && l.status === 'completed').length
  const habitsFailedToday    = (todayLogs || []).filter(l => l.date === todayStr && l.status === 'failed').length
  const habitComponent       = (habitsCompletedToday * 1.5) - (habitsFailedToday * 1.5)

  // 2. Operations / Tasks (Completed Today vs Overdue / Procrastinated)
  const tasksCompletedToday  = (tasks || []).filter(t => t.status === 'completed' && t.completed_at?.startsWith(todayStr)).length
  const tasksOverdue         = (tasks || []).filter(t => t.status === 'pending' && t.due_date && t.due_date < todayStr).length
  const opsComponent         = (tasksCompletedToday * 1.0) - (tasksOverdue * 1.0)

  // 3. Missions / Goals (Completed vs Stalled / Overdue)
  const missionsCompleted    = (sideQuests || []).filter(g => g.status === 'completed').length
  const missionsStalled      = (sideQuests || []).filter(g => g.status !== 'completed' && g.deadline && g.deadline < todayStr).length
  const missionsComponent    = (missionsCompleted * 2.0) - (missionsStalled * 1.5)

  // 4. Streak & Weekly Win Rate Inertia
  const streakComponent      = currentStreak >= 14 ? 3.0 : currentStreak >= 7 ? 2.0 : currentStreak >= 1 ? 1.0 : 0.0
  const winRateComponent     = weeklyWinRate >= 80 ? 3.0 : weeklyWinRate >= 60 ? 1.5 : weeklyWinRate >= 40 ? 0.0 : -3.0

  // 5. Digital Discipline / Screen Intel Component (-2.0 to +2.0)
  let screenComponent = 0
  if (todayScreenTime) {
    const stHours = parseFloat(todayScreenTime.total_hours) || 0
    const stDoom = parseInt(todayScreenTime.doom_scroll_minutes) || 0
    if (stHours <= 4 && stDoom <= 30) {
      screenComponent = 2.0
    } else if (stHours <= 6 && stDoom <= 60) {
      screenComponent = 1.5
    } else if (stHours > 8 || stDoom > 120) {
      screenComponent = -2.0
    } else if (stHours > 6.5 || stDoom > 80) {
      screenComponent = -1.5
    }
  }

  const rawMomentum          = habitComponent + opsComponent + missionsComponent + streakComponent + winRateComponent + screenComponent
  const momentumScore        = Math.max(-10, Math.min(10, parseFloat(rawMomentum.toFixed(1))))
  const momentumColor        = dailyMomentum?.color || (momentumScore >= 5 ? 'var(--success)' : momentumScore >= 0 ? 'var(--warning)' : 'var(--danger)')
  const momentumText         = momentumScore >= 5 ? 'SURGING' : momentumScore >= 0 ? 'STEADY' : 'DECLINING'

  const dayOfYear = Math.floor((new Date() - new Date(new Date().getFullYear(), 0, 0)) / 1000 / 60 / 60 / 24)
  const briefing = BRIEFINGS[dayOfYear % BRIEFINGS.length]

  const lastJournalDate = entries?.[0]?.date
  const journalDoneToday = lastJournalDate === todayStr

  let deadlineDays = null
  let deadlineUrgency = 'ok'
  if (mainQuest?.deadline) {
    const msDiff = new Date(mainQuest.deadline) - new Date()
    deadlineDays = Math.max(0, Math.ceil(msDiff / (1000 * 60 * 60 * 24)))
    deadlineUrgency = deadlineDays <= 3 ? 'danger' : deadlineDays <= 7 ? 'warning' : 'ok'
  }

  return (
    <AppShell>
      <div className="page-container relative max-w-[1600px] pb-2 lg:pb-10">

        <style dangerouslySetInnerHTML={{ __html: `
          :root { --arc-color: ${arcColor}; }
          .arc-glow { box-shadow: 0 0 30px ${arcColor}15, 0 0 60px ${arcColor}05; }
        ` }} />



        {/* ══════════════════════════════════════════════════════════════════
            OPAL DYNAMIC ATMOSPHERIC HERO CANVAS (CHANGING IMAGERY & MOOD)
        ══════════════════════════════════════════════════════════════════ */}
        <div 
          className="mb-6 rounded-3xl border border-white/10 shadow-[0_20px_60px_rgba(0,0,0,0.7)] overflow-hidden transition-all relative"
          style={{
            background: 'rgba(10, 13, 24, 0.9)',
            backdropFilter: 'blur(24px)',
            borderRadius: '24px',
            border: '1px solid rgba(255, 255, 255, 0.1)',
            overflow: 'hidden'
          }}
        >
          
          {/* Subtle Ambient Radial Aura behind Hero */}
          <div 
            className="absolute top-0 right-0 w-[450px] h-[450px] rounded-full pointer-events-none transition-all duration-1000"
            style={{
              background: `radial-gradient(circle, ${displayedSagaColor}25, transparent 70%)`,
              transform: 'translate(20%, -20%)',
              filter: 'blur(60px)'
            }}
          />

          <div className="relative z-10 flex flex-col-reverse lg:flex-row items-center justify-between gap-6 p-4 sm:p-6 lg:p-8">
            
            {/* ── LEFT SIDE (DESKTOP): INTELLIGENCE & PROGRESSION ── */}
            <div className="flex-1 w-full min-w-0 flex flex-col justify-between space-y-4 sm:space-y-5">
              
              {/* Top Time-of-Day Atmosphere Pill */}
              <div className="flex flex-wrap items-center gap-2">
                <div 
                  className="px-3 py-1 rounded-full border text-[10px] sm:text-[11px] font-mono font-bold uppercase tracking-wider flex items-center gap-1.5 shrink-0"
                  style={{
                    backgroundColor: `${timeAtmosphere.accent}15`,
                    borderColor: `${timeAtmosphere.accent}35`,
                    color: timeAtmosphere.accent,
                    boxShadow: `0 0 14px ${timeAtmosphere.glow}`
                  }}
                >
                  <timeAtmosphere.icon size={13} />
                  <span>{timeAtmosphere.label}</span>
                </div>
                <span className="font-mono text-[10px] text-slate-400 hidden sm:inline">
                  {timeAtmosphere.timeDesc}
                </span>

                {/* Auto-cycle toggle pill */}
                <button
                  type="button"
                  onClick={() => setIsAutoCycling(prev => !prev)}
                  title={isAutoCycling ? "Auto-cycling imagery every 10s (Click to pause)" : "Auto-cycle paused (Click to resume)"}
                  className="ml-auto px-2.5 py-0.5 rounded-full border border-white/10 bg-white/5 hover:bg-white/10 text-slate-300 font-mono text-[9px] uppercase tracking-wider flex items-center gap-1.5 transition-all"
                >
                  {isAutoCycling ? <Pause size={10} className="text-cyan-400" /> : <Play size={10} className="text-slate-400" />}
                  <span>{isAutoCycling ? 'Auto' : 'Paused'}</span>
                </button>
              </div>

              {/* Header: SAGA Title & Switcher */}
              <div>
                <div className="flex items-center gap-2 mb-1">
                  <span className="font-mono text-xs uppercase tracking-[0.25em] font-bold text-indigo-400">
                    SAGA {displayedArc.rank}
                  </span>
                  {displayedSagaIndex !== currentArcIndex && (
                    <button
                      type="button"
                      onClick={() => setActiveArtworkIndex(currentArcIndex)}
                      className="px-2 py-0.5 rounded-full bg-indigo-500/20 border border-indigo-400/40 text-indigo-300 font-mono text-[8px] uppercase tracking-wider hover:bg-indigo-500/30 transition-all"
                    >
                      Return to LV.{currentLevel} Saga ({currentRank.code})
                    </button>
                  )}
                </div>
                <h1 className="font-display font-black text-2xl sm:text-4xl text-white tracking-[0.12em] uppercase leading-tight">
                  {splitTitle.primary}
                </h1>
                <h2 
                  className="font-display font-black text-xl sm:text-3xl tracking-[0.18em] uppercase leading-none mt-1 transition-colors duration-500"
                  style={{ color: displayedSagaColor }}
                >
                  {splitTitle.secondary}
                </h2>
              </div>

              {/* Dynamic Rotating Motivational Quote Inset Pod */}
              <div 
                onClick={handleNextQuote}
                title="Click to cycle next mindset quote"
                className="rounded-2xl border border-white/10 bg-black/40 p-4 sm:p-5 flex items-center gap-4 hover:border-white/20 transition-all cursor-pointer group"
              >
                <div 
                  className="w-11 h-11 rounded-2xl flex items-center justify-center shrink-0 border transition-transform group-hover:scale-105"
                  style={{ 
                    backgroundColor: `${displayedSagaColor}15`, 
                    borderColor: `${displayedSagaColor}40`, 
                    color: displayedSagaColor,
                    boxShadow: `0 0 16px ${displayedSagaColor}25`
                  }}
                >
                  <Sparkles size={20} />
                </div>
                <div className="min-w-0 flex-1">
                  <p className="font-mono text-xs sm:text-sm text-slate-200 leading-relaxed italic">
                    "{SAGA_DISCIPLINE_QUOTES[quoteIndex % SAGA_DISCIPLINE_QUOTES.length]}"
                  </p>
                </div>
              </div>

              {/* Progress to Next Saga Pod */}
              <div className="rounded-2xl border border-white/10 bg-black/40 p-4 sm:p-5 space-y-3">
                <div className="flex items-center justify-between font-mono text-[10px] sm:text-[11px] text-slate-400 uppercase tracking-widest font-bold">
                  <span>PROGRESS TO NEXT SAGA</span>
                  <span>{sagaProgressPct}%</span>
                </div>

                <div className="flex flex-col sm:flex-row sm:items-center justify-between gap-4">
                  {/* Left: Huge Percentage & Bar */}
                  <div className="flex-1 space-y-2">
                    <div className="flex items-baseline justify-between">
                      <span 
                        className="font-display font-black text-3xl sm:text-4xl leading-none"
                        style={{ color: sagaAccentColor }}
                      >
                        {sagaProgressPct}%
                      </span>
                      <span className="font-mono text-xs font-bold text-slate-400">
                        {currentXpInSaga.toLocaleString()} / {totalXpInSaga.toLocaleString()} XP
                      </span>
                    </div>

                    {/* Glowing Progress Track */}
                    <div className="w-full h-2.5 rounded-full bg-slate-950 border border-white/10 p-[1px] relative overflow-hidden">
                      <motion.div 
                        className="h-full rounded-full transition-all duration-500 shadow-lg"
                        style={{ 
                          width: `${Math.max(4, Math.min(100, sagaProgressPct))}%`,
                          backgroundColor: sagaAccentColor,
                          boxShadow: `0 0 12px ${sagaAccentColor}`
                        }}
                      />
                    </div>
                  </div>

                  {/* Right: Next Saga Inset Capsule */}
                  {nextArc && (
                    <div className="p-3 rounded-xl border border-white/10 bg-black/50 flex items-center gap-3 shrink-0">
                      <div className="w-8 h-8 rounded-xl bg-purple-950/60 border border-purple-500/40 flex items-center justify-center text-purple-400 shrink-0">
                        <Target size={15} />
                      </div>
                      <div className="min-w-0">
                        <span className="font-mono text-[9px] uppercase tracking-wider text-purple-400 font-bold block">
                          NEXT SAGA
                        </span>
                        <span className="font-display font-bold text-xs text-white uppercase truncate block">
                          SAGA {nextArc.rank} • {nextArc.name}
                        </span>
                      </div>
                    </div>
                  )}
                </div>
              </div>

              {/* Bottom Quick Saga Switcher Dots & Roster Toggle */}
              <div className="flex flex-wrap items-center justify-between gap-2 pt-1">
                {/* 8 Saga Quick Dot Pills */}
                <div className="flex items-center gap-1.5 overflow-x-auto hide-scrollbar py-1">
                  {ARC_CONFIG.map((s, idx) => {
                    const isSelected = idx === displayedSagaIndex
                    const isUserCurrent = s.rank === currentRank.code
                    return (
                      <button
                        key={s.rank}
                        type="button"
                        onClick={() => {
                          setActiveArtworkIndex(idx)
                          setIsAutoCycling(false)
                        }}
                        title={`Saga ${s.rank}: ${s.name}`}
                        className={`px-2 py-0.5 rounded-full font-mono text-[9px] font-bold uppercase transition-all ${
                          isSelected
                            ? 'bg-white text-black shadow-md shadow-white/20 scale-105'
                            : isUserCurrent
                            ? 'bg-indigo-500/30 text-indigo-300 border border-indigo-400/40'
                            : 'bg-white/5 text-slate-400 hover:text-white hover:bg-white/10'
                        }`}
                      >
                        {s.rank}
                      </button>
                    )
                  })}
                </div>

                <button
                  type="button"
                  onClick={() => setSagaRosterOpen(prev => !prev)}
                  className="flex items-center gap-1.5 px-3 py-1 rounded-xl border border-white/10 bg-white/5 hover:bg-white/10 text-white font-mono text-[10px] font-bold uppercase tracking-wider transition-all shrink-0 ml-auto"
                >
                  <span>{sagaRosterOpen ? 'HIDE ROSTER' : 'VIEW ALL SAGAS'}</span>
                  {sagaRosterOpen ? <ChevronUp size={12} /> : <ChevronDown size={12} />}
                </button>
              </div>

            </div>

            {/* ── RIGHT SIDE (DESKTOP): 1:1 SQUARE ARTWORK WITH SMOOTH CROSSFADE ── */}
            <div className="w-full sm:w-[320px] md:w-[360px] lg:w-[380px] shrink-0 flex flex-col items-center">
              <div 
                onClick={() => {
                  setActiveArtworkIndex(prev => {
                    const base = prev === null ? (currentArcIndex >= 0 ? currentArcIndex : 0) : prev
                    return (base + 1) % ARC_CONFIG.length
                  })
                }}
                title="Click image to cycle next artwork"
                className="rounded-3xl overflow-hidden relative border border-white/15 bg-slate-950 shadow-[0_0_40px_rgba(0,0,0,0.85)] group cursor-pointer w-full max-w-[380px] aspect-square"
              >
                {/* Crossfading Dynamic Image */}
                <AnimatePresence mode="wait">
                  <motion.img 
                    key={displayedSagaImage}
                    src={displayedSagaImage} 
                    alt={displayedArc.name} 
                    initial={{ opacity: 0, scale: 0.97 }}
                    animate={{ opacity: 1, scale: 1 }}
                    exit={{ opacity: 0, scale: 1.03 }}
                    transition={{ duration: 0.5, ease: 'easeInOut' }}
                    className="w-full h-full object-cover aspect-square transition-transform duration-500 group-hover:scale-105"
                    onError={(e) => { e.currentTarget.src = '/sagas/Awakening.png' }}
                  />
                </AnimatePresence>

                {/* Subtle cyber border & caption overlay on hover */}
                <div className="absolute inset-0 ring-1 ring-inset ring-white/10 rounded-3xl pointer-events-none" />
                <div className="absolute bottom-2 inset-x-2 py-1 px-2.5 rounded-full bg-black/60 backdrop-blur-md border border-white/10 flex items-center justify-between text-[9px] font-mono text-slate-300 opacity-0 group-hover:opacity-100 transition-opacity">
                  <span>{displayedArc.name}</span>
                  <span className="text-indigo-300">Tap to cycle ↻</span>
                </div>
              </div>

              {/* Prev / Next Chevrons below image */}
              <div className="flex items-center justify-center gap-3 mt-2.5">
                <button
                  type="button"
                  onClick={() => {
                    setActiveArtworkIndex(prev => {
                      const base = prev === null ? (currentArcIndex >= 0 ? currentArcIndex : 0) : prev
                      return (base - 1 + ARC_CONFIG.length) % ARC_CONFIG.length
                    })
                    setIsAutoCycling(false)
                  }}
                  className="w-8 h-8 rounded-full border border-white/10 bg-white/5 hover:bg-white/15 flex items-center justify-center text-slate-300 transition-all active:scale-95"
                  title="Previous Saga Artwork"
                >
                  <ChevronLeft size={16} />
                </button>

                <span className="font-mono text-[9px] text-slate-400 font-bold uppercase tracking-widest">
                  {displayedSagaIndex + 1} / {ARC_CONFIG.length}
                </span>

                <button
                  type="button"
                  onClick={() => {
                    setActiveArtworkIndex(prev => {
                      const base = prev === null ? (currentArcIndex >= 0 ? currentArcIndex : 0) : prev
                      return (base + 1) % ARC_CONFIG.length
                    })
                    setIsAutoCycling(false)
                  }}
                  className="w-8 h-8 rounded-full border border-white/10 bg-white/5 hover:bg-white/15 flex items-center justify-center text-slate-300 transition-all active:scale-95"
                  title="Next Saga Artwork"
                >
                  <ChevronRight size={16} />
                </button>
              </div>
            </div>

          </div>

          {/* ── EXPANDABLE 8-SAGA LOCKED/UNLOCKED ROSTER ── */}
          <AnimatePresence>
            {sagaRosterOpen && (
              <motion.div
                initial={{ opacity: 0, height: 0 }}
                animate={{ opacity: 1, height: 'auto' }}
                exit={{ opacity: 0, height: 0 }}
                className="border-t border-white/10 p-4 sm:p-6 bg-black/60"
              >
                <div className="flex items-center justify-between mb-4">
                  <div className="flex items-center gap-2">
                    <span className="w-2 h-2 rounded-full bg-indigo-400 shadow-[0_0_8px_#818cf8]" />
                    <h3 className="font-mono text-xs font-bold text-white uppercase tracking-wider">
                      SAGA PROGRESSION ROSTER
                    </h3>
                  </div>
                  <span className="font-mono text-[10px] text-slate-400 uppercase font-bold">
                    CURRENT LEVEL: LV.{currentLevel}
                  </span>
                </div>

                <div 
                  style={{ 
                    display: 'grid', 
                    gridTemplateColumns: 'repeat(auto-fit, minmax(130px, 1fr))', 
                    gap: '12px', 
                    width: '100%' 
                  }}
                >
                  {ARC_CONFIG.map((saga, sIdx) => {
                    const isCurrent = saga.rank === currentRank.code
                    const isSelected = sIdx === displayedSagaIndex
                    const isUnlocked = currentLevel >= saga.minLvl
                    const isCompleted = currentLevel > saga.maxLvl
                    const sagaImg = SAGA_IMAGES[saga.rank] || '/sagas/the-spark.png'

                    return (
                      <div 
                        key={saga.rank}
                        onClick={() => {
                          setActiveArtworkIndex(sIdx)
                          setIsAutoCycling(false)
                        }}
                        className={`rounded-2xl border p-2.5 flex flex-col items-center text-center transition-all cursor-pointer ${
                          isSelected
                            ? 'bg-indigo-950/50 border-indigo-400 shadow-[0_0_20px_rgba(129,140,248,0.4)] ring-2 ring-indigo-400/50'
                            : isCurrent
                            ? 'bg-indigo-950/30 border-indigo-400/50'
                            : isUnlocked
                            ? 'bg-black/40 border-white/10 hover:border-white/20'
                            : 'bg-black/60 border-white/5 opacity-50'
                        }`}
                      >
                        {/* 1:1 Square Thumbnail */}
                        <div className="w-full aspect-square rounded-xl overflow-hidden relative mb-2 bg-slate-950 border border-white/10">
                          <img 
                            src={sagaImg} 
                            alt={saga.name} 
                            className={`w-full h-full object-cover aspect-square transition-all ${
                              !isUnlocked ? 'grayscale contrast-125 brightness-50' : ''
                            }`}
                            onError={(e) => { e.currentTarget.src = '/sagas/the-spark.png' }}
                          />

                          {/* Lock / Active Badges */}
                          {isCurrent ? (
                            <div className="absolute top-1 right-1 px-1.5 py-0.5 rounded bg-indigo-500 text-black font-mono text-[8px] font-black uppercase shadow-md">
                              ACTIVE
                            </div>
                          ) : !isUnlocked ? (
                            <div className="absolute inset-0 bg-black/60 backdrop-blur-[1px] flex flex-col items-center justify-center text-slate-300">
                              <Lock size={16} className="text-slate-400 mb-0.5" />
                              <span className="font-mono text-[8px] font-bold text-slate-300">LV.{saga.minLvl}+</span>
                            </div>
                          ) : isCompleted ? (
                            <div className="absolute top-1 right-1 px-1.5 py-0.5 rounded bg-emerald-500/90 text-black font-mono text-[8px] font-black uppercase shadow-md">
                              ✓ DONE
                            </div>
                          ) : null}
                        </div>

                        {/* Title & Level Range */}
                        <div className="w-full min-w-0">
                          <div className="font-mono text-[8px] uppercase tracking-wider text-slate-400 font-bold">
                            SAGA {saga.rank}
                          </div>
                          <div className="font-display font-bold text-[11px] text-white uppercase tracking-tight truncate">
                            {saga.name}
                          </div>
                          <div className="font-mono text-[9px] text-slate-400 mt-0.5">
                            LV.{saga.minLvl} - {saga.maxLvl === 999 ? '∞' : saga.maxLvl}
                          </div>
                        </div>
                      </div>
                    )
                  })}
                </div>
              </motion.div>
            )}
          </AnimatePresence>

        </div>

        {/* ══════════════════════════════════════════════════════════════════
            DAILY PROTOCOL STATUS FLOATING DECK (INSTANT MODAL LAUNCH)
        ══════════════════════════════════════════════════════════════════ */}
        <div 
          className="mb-6 rounded-3xl border border-white/10 p-3.5 sm:p-5"
          style={{
            background: 'rgba(9, 13, 26, 0.85)',
            backdropFilter: 'blur(24px)',
            borderRadius: '24px',
            border: '1px solid rgba(255, 255, 255, 0.1)',
            boxShadow: '0 12px 40px rgba(0, 0, 0, 0.5)'
          }}
        >
          <div className="flex items-center justify-between mb-3 px-1">
            <div className="flex items-center gap-2">
              <span className="w-2 h-2 rounded-full bg-emerald-400 animate-pulse shadow-[0_0_8px_#34d399]" />
              <span className="font-mono text-[10px] sm:text-xs uppercase tracking-widest text-white font-bold">
                DAILY PROTOCOLS ({eodCompletedCount} / {eodItems.length + (isDebriefDoneThisWeek ? 1 : 0)} LOGGED)
              </span>
            </div>
            <span className="font-mono text-[9px] text-slate-400 uppercase font-semibold">
              TAP PILL TO QUICK LOG
            </span>
          </div>

          <div className="daily-protocols-grid gap-2.5">
            {eodItems.map((item) => {
              const ItemIcon = item.icon
              const displayLabel = item.key === 'work' ? 'Work Session' : item.key === 'journal' ? 'Daily Journal' : item.key === 'screen' ? 'Screen Intel' : item.key === 'speaking' ? 'Speaking Challenge' : item.label

              return (
                <button
                  key={item.key}
                  type="button"
                  onClick={() => setEodQuickLogModal(item.key)}
                  className={`p-3 rounded-2xl border text-left transition-all flex flex-col justify-between group relative overflow-hidden active:scale-95 ${
                    item.isDone
                      ? 'bg-emerald-950/30 border-emerald-500/40 text-white shadow-[0_0_15px_rgba(16,185,129,0.15)]'
                      : 'bg-white/[0.02] border-white/10 hover:border-white/20 text-slate-300 hover:bg-white/[0.05]'
                  }`}
                >
                  <div className="flex items-center justify-between w-full mb-2">
                    <div className={`w-8 h-8 rounded-xl flex items-center justify-center ${item.isDone ? 'bg-emerald-500/20 text-emerald-400' : 'bg-white/5 text-slate-400'}`}>
                      <ItemIcon size={16} style={{ color: item.isDone ? '#34d399' : 'currentColor' }} />
                    </div>
                    <div className={`flex items-center gap-1 px-2 py-0.5 rounded-full font-mono text-[8px] font-bold uppercase tracking-wider ${
                      item.isDone ? 'bg-emerald-500/20 text-emerald-300 border border-emerald-500/40' : 'bg-white/5 text-slate-400'
                    }`}>
                      <span className={`w-1.5 h-1.5 rounded-full ${item.isDone ? 'bg-emerald-400 shadow-[0_0_6px_#34d399]' : 'bg-slate-500'}`} />
                      <span>{item.isDone ? 'DONE' : '+ LOG'}</span>
                    </div>
                  </div>

                  <div>
                    <div className="font-display font-bold text-xs uppercase tracking-wide truncate text-white">
                      {displayLabel}
                    </div>
                    <div className="font-mono text-[9px] text-slate-400 truncate mt-0.5">
                      {item.detail}
                    </div>
                  </div>
                </button>
              )
            })}

            {/* 5th Pill: Weekly Debrief */}
            <Link
              href="/journal?tab=weekly"
              className={`p-3 rounded-2xl border text-left transition-all flex flex-col justify-between group relative overflow-hidden active:scale-95 ${
                isDebriefDoneThisWeek
                  ? 'bg-emerald-950/30 border-emerald-500/40 text-white shadow-[0_0_15px_rgba(16,185,129,0.15)]'
                  : new Date().getDay() === 0
                  ? 'bg-amber-950/30 border-amber-500/40 text-amber-300 shadow-[0_0_15px_rgba(245,158,11,0.15)]'
                  : 'bg-white/[0.02] border-white/10 hover:border-white/20 text-slate-300 hover:bg-white/[0.05]'
              }`}
            >
              <div className="flex items-center justify-between w-full mb-2">
                <div className={`w-8 h-8 rounded-xl flex items-center justify-center ${isDebriefDoneThisWeek ? 'bg-emerald-500/20 text-emerald-400' : 'bg-white/5 text-slate-400'}`}>
                  {isDebriefDoneThisWeek ? <CheckCircle2 size={16} className="text-emerald-400" /> : <ClipboardList size={16} className={new Date().getDay() === 0 ? 'text-amber-400' : 'text-slate-400'} />}
                </div>
                <div className={`flex items-center gap-1 px-2 py-0.5 rounded-full font-mono text-[8px] font-bold uppercase tracking-wider ${
                  isDebriefDoneThisWeek ? 'bg-emerald-500/20 text-emerald-300 border border-emerald-500/40' : new Date().getDay() === 0 ? 'bg-amber-500/20 text-amber-300 border border-amber-500/40' : 'bg-white/5 text-slate-400'
                }`}>
                  <span className={`w-1.5 h-1.5 rounded-full ${isDebriefDoneThisWeek ? 'bg-emerald-400 shadow-[0_0_6px_#34d399]' : new Date().getDay() === 0 ? 'bg-amber-400 animate-pulse' : 'bg-slate-500'}`} />
                  <span>{isDebriefDoneThisWeek ? 'DONE' : new Date().getDay() === 0 ? 'DUE TODAY' : 'DUE SUN'}</span>
                </div>
              </div>

              <div>
                <div className="font-display font-bold text-xs uppercase tracking-wide truncate text-white">
                  Weekly Debrief
                </div>
                <div className="font-mono text-[9px] text-slate-400 truncate mt-0.5">
                  {isDebriefDoneThisWeek ? 'Cycle completed' : new Date().getDay() === 0 ? 'Sunday debrief due' : 'Reflection cycle'}
                </div>
              </div>
            </Link>
          </div>
        </div>

        {/* ══════════════════════════════════════════════════════════════════
            MAIN BENTO GRID
        ══════════════════════════════════════════════════════════════════ */}
        <div className="bento-grid">

          {/* LEFT (8 cols) */}
          <div className="col-8 flex flex-col gap-3 lg:gap-4">

            {/* ACTIVE OBJECTIVE & COUNTDOWN */}
            {mainQuest ? (
              <div
                className="relative overflow-hidden dashboard-card p-5 sm:p-6"
                style={{
                  borderLeft: '4px solid var(--info)',
                }}
              >
                <div className="absolute top-0 right-0 pointer-events-none" style={{
                  width: '240px', height: '240px', borderRadius: '50%',
                  background: 'var(--info)', opacity: 0.07, filter: 'blur(50px)',
                  transform: 'translate(30%, -30%)',
                }} />
                <div className="flex items-center gap-2 mb-3 relative z-10">
                  <Target size={14} color="var(--info)" />
                  <span className="font-mono text-[9px] uppercase tracking-widest text-info font-bold">Active Objective</span>
                  <span className="ml-auto font-mono text-[8px] text-info animate-pulse px-2 py-0.5 rounded-full bg-cyan-500/10 border border-cyan-500/30">● EXECUTING</span>
                </div>
                
                <div className="flex flex-col sm:flex-row justify-between gap-4 relative z-10">
                  <div className="flex-1">
                    <h2 className="font-display font-bold text-white leading-tight mb-2"
                      style={{ fontSize: 'clamp(1.2rem, 3vw, 1.6rem)' }}>
                      {mainQuest.title}
                    </h2>
                    {mainQuest.description && (
                      <p className="font-mono text-[10px] text-slate-400 mb-4 line-clamp-2">{mainQuest.description}</p>
                    )}
                    <TacticalProgress value={mainQuest.progress} max={100} showValue color="var(--info)" />
                  </div>

                  {/* OPERATION DEADLINE COUNTDOWN */}
                  {deadlineDays !== null && (
                    <div className="shrink-0 flex flex-col items-center justify-center p-3.5 rounded-2xl border border-white/10 bg-white/[0.02] min-w-[100px] sm:min-w-[120px]">
                      <Clock size={16} className="mb-1" style={{
                        color: deadlineUrgency === 'danger' ? 'var(--danger)' : deadlineUrgency === 'warning' ? 'var(--warning)' : 'var(--info)'
                      }} />
                      <div className="font-display font-bold" style={{
                        fontSize: '2rem', lineHeight: 1,
                        color: deadlineUrgency === 'danger' ? 'var(--danger)' : deadlineUrgency === 'warning' ? 'var(--warning)' : '#ffffff'
                      }}>
                        {deadlineDays}
                      </div>
                      <div className="font-mono text-[8px] text-slate-400 uppercase mt-1">Days Left</div>
                    </div>
                  )}
                </div>
              </div>
            ) : (
              <div className="dashboard-card border-dashed text-center p-6">
                <AlertTriangle size={24} className="text-slate-500 mx-auto mb-2" />
                <p className="font-mono text-[11px] text-slate-400 mb-3">No active directives</p>
                <Link href="/goals" className="btn btn-primary btn-sm rounded-xl font-mono text-[10px] px-4 py-2">ASSIGN MISSION</Link>
              </div>
            )}

            {/* ══════════════════════════════════════════════════════════════════
                TODAY'S OPERATIONS & SCHEDULE
            ══════════════════════════════════════════════════════════════════ */}
            <div className="dashboard-card p-5 sm:p-6" style={{ borderLeft: '4px solid var(--accent-primary)' }}>
              <div className="flex items-center justify-between gap-2 mb-4 flex-wrap">
                <div className="flex items-center gap-2 flex-wrap">
                  <CalendarIcon size={14} className="text-amber-400" />
                  <span className="font-mono text-[9px] sm:text-[10px] uppercase tracking-widest text-amber-300 font-bold">
                    Today's Operations
                  </span>
                  <span className="px-2 py-0.5 rounded-full font-mono text-[8px] font-bold uppercase bg-amber-500/15 text-amber-300 border border-amber-500/30">
                    {todayCalendarEvents.length + todayTasksScheduled.length} {todayCalendarEvents.length + todayTasksScheduled.length === 1 ? 'Item' : 'Items'}
                  </span>
                </div>
                <div className="flex items-center gap-2 shrink-0">
                  <Link
                    href="/tasks"
                    className="font-mono text-[9px] text-slate-400 hover:text-white flex items-center gap-1 transition-colors"
                  >
                    <span>Tasks</span>
                    <ArrowUpRight size={10} />
                  </Link>
                  <span className="text-slate-600 text-xs">·</span>
                  <Link
                    href="/calendar"
                    className="font-mono text-[9px] text-slate-400 hover:text-white flex items-center gap-1 transition-colors"
                  >
                    <span>Calendar</span>
                    <ArrowUpRight size={10} />
                  </Link>
                </div>
              </div>

              {todayCalendarEvents.length === 0 && todayTasksScheduled.length === 0 ? (
                <div className="p-5 text-center rounded-2xl bg-white/[0.02] border border-dashed border-white/10">
                  <p className="font-mono text-[11px] text-slate-400 mb-2.5">No scheduled operations or calendar events for today.</p>
                  <div className="flex items-center justify-center gap-2">
                    <Link href="/tasks" className="btn btn-secondary btn-sm font-mono text-[9px] rounded-xl">
                      + ADD TASK
                    </Link>
                    <Link href="/calendar" className="btn btn-secondary btn-sm font-mono text-[9px] rounded-xl">
                      + ADD EVENT
                    </Link>
                  </div>
                </div>
              ) : (
                <div className="space-y-2.5">
                  {/* Calendar Events First */}
                  {todayCalendarEvents.map((evt, idx) => (
                    <div
                      key={evt.id || idx}
                      className="flex items-center justify-between gap-3 p-3 rounded-2xl bg-cyan-950/20 border border-cyan-500/30 transition-all hover:border-cyan-500/50"
                    >
                      <div className="flex items-center gap-2.5 min-w-0">
                        <span className="w-2 h-2 rounded-full bg-cyan-400 animate-pulse shadow-[0_0_8px_#22d3ee] shrink-0" />
                        <div className="min-w-0">
                          <span className="font-display font-semibold text-xs text-white truncate block">
                            {evt.title}
                          </span>
                          {evt.description && (
                            <span className="font-mono text-[9px] text-slate-400 truncate block">
                              {evt.description}
                            </span>
                          )}
                        </div>
                      </div>
                      <div className="flex items-center gap-2 shrink-0">
                        {evt.start_time && (
                          <span className="font-mono text-[10px] text-cyan-300 font-bold bg-cyan-500/10 px-2 py-0.5 rounded-full border border-cyan-500/20">
                            {evt.start_time.includes('T') ? evt.start_time.split('T')[1].slice(0, 5) : evt.start_time}
                          </span>
                        )}
                        <span className="font-mono text-[8px] font-bold text-cyan-400 uppercase tracking-wider bg-cyan-500/20 px-2 py-0.5 rounded-full border border-cyan-500/30">
                          EVENT
                        </span>
                      </div>
                    </div>
                  ))}

                  {/* Scheduled Tasks */}
                  {todayTasksScheduled.map(task => {
                    const isDone = task.status === 'completed'
                    return (
                      <div
                        key={task.id}
                        className={`flex items-center justify-between gap-3 p-3 rounded-2xl border transition-all ${
                          isDone
                            ? 'bg-emerald-950/20 border-emerald-500/30 text-slate-400'
                            : 'bg-white/[0.02] border-white/10 hover:border-white/20 text-white'
                        }`}
                      >
                        <div className="flex items-center gap-2.5 min-w-0 flex-1">
                          <button
                            type="button"
                            onClick={async () => {
                              if (isDone) {
                                if (undoCompleteTask) await undoCompleteTask(task.id)
                              } else {
                                if (completeTask) await completeTask(task.id)
                              }
                              if (fetchTasks) await fetchTasks()
                              if (profileHook?.fetchProfile) await profileHook.fetchProfile()
                            }}
                            className={`w-6 h-6 rounded-xl flex items-center justify-center transition-all shrink-0 ${
                              isDone
                                ? 'bg-emerald-500 text-black shadow-[0_0_10px_rgba(16,185,129,0.4)]'
                                : 'border border-white/20 hover:border-emerald-400 hover:bg-emerald-500/10 text-transparent hover:text-emerald-400'
                            }`}
                            title={isDone ? 'Undo complete' : 'Mark complete'}
                          >
                            <Check size={13} strokeWidth={3} className={isDone ? 'opacity-100' : 'opacity-0 hover:opacity-100'} />
                          </button>
                          <div className="min-w-0 flex-1">
                            <span className={`font-mono text-xs leading-snug break-words whitespace-normal block ${
                              isDone ? 'line-through text-slate-500' : 'text-slate-200'
                            }`}>
                              {task.title}
                            </span>
                            {task.description && (
                              <span className="font-mono text-[9px] text-slate-500 truncate block mt-0.5">
                                {task.description}
                              </span>
                            )}
                          </div>
                        </div>
                        <div className="flex items-center gap-1.5 shrink-0">
                          {task.due_time && (
                            <span className="font-mono text-[9px] text-slate-400">
                              {task.due_time}
                            </span>
                          )}
                          {isDone ? (
                            <span className="font-mono text-[8px] font-bold text-emerald-300 uppercase px-2 py-0.5 rounded-full bg-emerald-500/20 border border-emerald-500/40">
                              DONE
                            </span>
                          ) : (
                            <span className="font-mono text-[8px] font-bold text-amber-300 uppercase px-2 py-0.5 rounded-full bg-amber-500/20 border border-amber-500/40">
                              +25 XP
                            </span>
                          )}
                        </div>
                      </div>
                    )
                  })}
                </div>
              )}
            </div>



            {/* NEXT WEEK PRIORITIES // WEEKLY DEBRIEF WIDGET */}
            <div className="dashboard-card p-5 sm:p-6" style={{ borderLeft: '4px solid var(--info)' }}>
              <div className="flex items-center justify-between gap-2 mb-4">
                <div className="flex items-center gap-2">
                  <ClipboardList size={14} color="var(--info)" />
                  <span className="font-mono text-[9px] sm:text-[10px] uppercase tracking-widest text-info font-bold">Next Week Priorities // Weekly Debrief</span>
                </div>
                <Link href="/journal" className="font-mono text-[9px] text-slate-400 hover:text-info flex items-center gap-1 transition-colors">
                  <span>DEBRIEF</span>
                  <ArrowUpRight size={10} />
                </Link>
              </div>

              {debriefPriorityList.length > 0 ? (
                (() => {
                  const updateDebriefWorkLog = async (priorityTitle, newTag) => {
                    if (!user) return
                    const sb = createClient()
                    const curDebrief = latestDebriefRef.current || latestDebrief
                    if (!curDebrief?.id) return

                    const cleanTarget = priorityTitle
                      .replace(/\[DONE\]|\[FAILED\]/gi, '')
                      .replace(/^[-*•]\s*(\[[ xXvV✓✕]\])?\s*/, '')
                      .replace(/^\d+[\.\)]\s*/, '')
                      .trim()
                      .toLowerCase()

                    if (!cleanTarget) return

                    // Fetch fresh description from Supabase to prevent race conditions across rapid clicks
                    let currentDesc = curDebrief.description || ''
                    try {
                      const { data: fresh } = await sb.from('work_logs').select('description').eq('id', curDebrief.id).single()
                      if (fresh?.description) {
                        currentDesc = fresh.description
                      }
                    } catch (err) {}

                    const lines = currentDesc.split('\n')
                    let matched = false
                    const updatedLines = lines.map(line => {
                      const cleanLine = line
                        .replace(/\[DONE\]|\[FAILED\]/gi, '')
                        .replace(/^[-*•]\s*(\[[ xXvV✓✕]\])?\s*/, '')
                        .replace(/^\d+[\.\)]\s*/, '')
                        .trim()
                        .toLowerCase()

                      if (!matched && (cleanLine === cleanTarget || cleanLine.includes(cleanTarget) || cleanTarget.includes(cleanLine))) {
                        matched = true
                        const prefixMatch = line.match(/^(\s*\d+[\.\)]\s*|\s*[-*•]\s*)?/)?.[0] || ''
                        const pureLine = line
                          .replace(/\[DONE\]|\[FAILED\]/gi, '')
                          .replace(/^(\s*\d+[\.\)]\s*|\s*[-*•]\s*)?/, '')
                          .trim()
                        return newTag ? `${prefixMatch}${pureLine} ${newTag}` : `${prefixMatch}${pureLine}`
                      }
                      return line
                    })

                    const newDesc = updatedLines.join('\n')
                    const nowIso = new Date().toISOString()
                    await sb.from('work_logs').update({ description: newDesc, updated_at: nowIso }).eq('id', curDebrief.id)
                    const updatedObj = { ...curDebrief, description: newDesc, updated_at: nowIso }
                    latestDebriefRef.current = updatedObj
                    setLatestDebrief(updatedObj)

                    if (typeof window !== 'undefined') {
                      try {
                        const rawHist = localStorage.getItem(`lokios_debrief_history_${user.id}`)
                        if (rawHist) {
                          const parsed = JSON.parse(rawHist)
                          const next = parsed.map(p => (p.id === curDebrief.id || p.title === curDebrief.title) ? updatedObj : p)
                          localStorage.setItem(`lokios_debrief_history_${user.id}`, JSON.stringify(next))
                        }
                        const todayStr = getLocalDateStr(new Date())
                        const cacheKey = `lokios_dashboard_recon_${user.id}_${todayStr}`
                        const reconCache = localStorage.getItem(cacheKey)
                        const parsedRecon = reconCache ? JSON.parse(reconCache) : {}
                        parsedRecon.latestDebrief = updatedObj
                        localStorage.setItem(cacheKey, JSON.stringify(parsedRecon))
                      } catch (e) {}
                    }
                  }

                  return (
                    <div className="space-y-2">
                      {debriefPriorityList.map((gt) => {
                        const isDone = gt.status === 'completed'
                        const isFailed = gt.status === 'failed' || gt.status === 'cancelled'

                        const goalTitleText = typeof gt.title === 'string' ? gt.title : (gt.title?.title || gt.title?.name || 'Priority Goal')
                        const isLongTitle = goalTitleText.length > 35
                        const stableSourceId = `debrief_p_${goalTitleText.trim().toLowerCase().replace(/\s+/g, '_')}`

                        const handleMarkDone = async () => {
                          updatePriorityStatus({ [gt.id]: 'completed', [goalTitleText]: 'completed', [stableSourceId]: 'completed' })
                          let targetIds = gt.matchingTaskIds && gt.matchingTaskIds.length > 0 ? [...gt.matchingTaskIds] : []

                          if (targetIds.length === 0 && user) {
                            const endOfWeekStr = getLocalDateStr(getEndOfWeek(new Date()))
                            const res = await addTask({
                              title: goalTitleText,
                              type: 'custom',
                              category: 'weekly_goal',
                              due_date: endOfWeekStr,
                              status: 'completed',
                              completed_at: new Date().toISOString(),
                              description: '[Weekly Goal] Priority for Next Week'
                            })
                            if (res?.data?.id) targetIds.push(res.data.id)
                          }

                          for (const tid of targetIds) {
                            const updates = { completed_at: new Date().toISOString(), status: 'completed' }
                            await createClient().from('tasks').update(updates).eq('id', tid).eq('user_id', user.id)
                          }

                          await updateDebriefWorkLog(goalTitleText, '[DONE]')
                          await robustAwardXP(user.id, 25, 'task_complete', stableSourceId, `Completed Priority Goal: ${goalTitleText}`, 'discipline')

                          if (fetchTasks) await fetchTasks()
                          await profileHook?.fetchProfile?.()
                        }

                        const handleMarkFailed = async () => {
                          updatePriorityStatus({ [gt.id]: 'failed', [goalTitleText]: 'failed', [stableSourceId]: 'failed' })
                          let targetIds = gt.matchingTaskIds && gt.matchingTaskIds.length > 0 ? [...gt.matchingTaskIds] : []

                          if (targetIds.length === 0 && user) {
                            const endOfWeekStr = getLocalDateStr(getEndOfWeek(new Date()))
                            const res = await addTask({
                              title: goalTitleText,
                              type: 'custom',
                              category: 'weekly_goal',
                              due_date: endOfWeekStr,
                              status: 'failed',
                              completed_at: new Date().toISOString(),
                              description: '[Weekly Goal] Priority for Next Week'
                            })
                            if (res?.data?.id) targetIds.push(res.data.id)
                          }

                          for (const tid of targetIds) {
                            const updates = { completed_at: new Date().toISOString(), status: 'failed' }
                            await createClient().from('tasks').update(updates).eq('id', tid).eq('user_id', user.id)
                          }

                          await updateDebriefWorkLog(goalTitleText, '[FAILED]')
                          await robustAwardXP(user.id, -25, 'task_failed', stableSourceId, `Failed Priority Goal: ${goalTitleText}`, 'discipline')

                          if (fetchTasks) await fetchTasks()
                          await profileHook?.fetchProfile?.()
                        }

                        const handleReopen = async () => {
                          updatePriorityStatus({ [gt.id]: 'pending', [goalTitleText]: 'pending', [stableSourceId]: 'pending', [gt.title]: 'pending' })
                          const targetIds = gt.matchingTaskIds && gt.matchingTaskIds.length > 0 ? gt.matchingTaskIds : (gt.taskId ? [gt.taskId] : [])
                          for (const tid of targetIds) {
                            const updates = { completed_at: null, status: 'pending' }
                            await createClient().from('tasks').update(updates).eq('id', tid).eq('user_id', user.id)
                          }
                          await updateDebriefWorkLog(goalTitleText, '')
                          await robustRemoveXP(user.id, 'task_complete', stableSourceId)
                          await robustRemoveXP(user.id, 'task_failed', stableSourceId)
                          if (fetchTasks) await fetchTasks()
                          await profileHook?.fetchProfile?.()
                        }

                        return (
                          <div key={gt.id} className={`flex items-start sm:items-center justify-between gap-3 p-3 rounded-2xl border transition-all w-full max-w-full overflow-hidden ${
                            isDone ? 'border-emerald-500/30 bg-emerald-950/20' : isFailed ? 'border-rose-500/30 bg-rose-950/20' : 'border-white/10 bg-white/[0.02] hover:border-white/20'
                          }`}>
                            <div className="flex items-start sm:items-center gap-2.5 flex-1 min-w-0">
                              {/* Action Buttons */}
                              <div className="flex items-center gap-1.5 shrink-0 mt-0.5 sm:mt-0">
                                {isDone || isFailed ? (
                                  <button
                                    type="button"
                                    onClick={handleReopen}
                                    title="Re-open Priority Goal"
                                    className="w-7 h-7 rounded-xl flex items-center justify-center border border-white/10 hover:border-cyan-400 text-cyan-400 bg-white/5 transition-all shrink-0 active:scale-95"
                                  >
                                    <RotateCcw size={12} />
                                  </button>
                                ) : (
                                  <>
                                    <button
                                      type="button"
                                      onClick={handleMarkDone}
                                      title="Mark Completed (+25 XP)"
                                      className="w-7 h-7 rounded-xl flex items-center justify-center border border-emerald-500/40 hover:bg-emerald-500 text-emerald-400 hover:text-black transition-all shrink-0 active:scale-95"
                                    >
                                      <Check size={14} strokeWidth={2.5} />
                                    </button>
                                    <button
                                      type="button"
                                      onClick={handleMarkFailed}
                                      title="Mark Failed (-25 XP)"
                                      className="w-7 h-7 rounded-xl flex items-center justify-center border border-rose-500/40 hover:bg-rose-500 text-rose-400 hover:text-white transition-all shrink-0 active:scale-95"
                                    >
                                      <X size={14} strokeWidth={2.5} />
                                    </button>
                                  </>
                                )}
                              </div>
                              <span className={`font-mono leading-snug break-words whitespace-normal flex-1 min-w-0 transition-all ${
                                isLongTitle ? 'text-[11px]' : 'text-xs'
                              } ${
                                isDone 
                                  ? 'text-emerald-400/80 line-through decoration-emerald-500 font-medium' 
                                  : isFailed 
                                  ? 'text-rose-400/80 line-through decoration-rose-500 font-medium' 
                                  : 'text-slate-200 font-medium'
                              }`}>
                                {goalTitleText}
                              </span>
                            </div>
                            {isDone ? (
                              <span className="font-mono text-[8px] font-bold text-emerald-300 uppercase shrink-0 px-2 py-0.5 rounded-full bg-emerald-500/20 border border-emerald-500/40 whitespace-nowrap self-center">DONE (+25 XP)</span>
                            ) : isFailed ? (
                              <span className="font-mono text-[8px] font-bold text-rose-300 uppercase shrink-0 px-2 py-0.5 rounded-full bg-rose-500/20 border border-rose-500/40 whitespace-nowrap self-center">FAILED (-25 XP)</span>
                            ) : (
                              <span className="font-mono text-[8px] font-bold text-amber-300 uppercase shrink-0 px-2 py-0.5 rounded-full bg-amber-500/20 border border-amber-500/40 whitespace-nowrap self-center">+25 XP</span>
                            )}
                          </div>
                        )
                      })}
                    </div>
                  )
                })()
              ) : (
                <div className="p-5 text-center rounded-2xl bg-white/[0.02] border border-dashed border-white/10">
                  <p className="font-mono text-[11px] text-slate-400 mb-2.5">No priorities logged for this cycle.</p>
                  <Link href="/journal" className="btn btn-secondary btn-sm font-mono text-[9px] rounded-xl">
                    INITIALIZE WEEKLY DEBRIEF
                  </Link>
                </div>
              )}
            </div>

            {/* 30-DAY XP TRAJECTORY GRAPH */}
            <div className="dashboard-card p-5 sm:p-6" style={{ borderLeft: `4px solid ${arcColor}` }}>
              <div className="flex items-center justify-between gap-2 mb-3">
                <div className="flex items-center gap-2">
                  <BarChart2 size={14} style={{ color: arcColor }} />
                  <span className="font-mono text-[9px] sm:text-[10px] uppercase tracking-widest text-slate-300 font-bold">30-Day Project Trajectory (XP)</span>
                </div>
                <span className="font-mono text-[8px] text-slate-500 uppercase">XP Velocity</span>
              </div>
              <div style={{ width: '100%', height: '140px' }}>
                <ResponsiveContainer>
                  <AreaChart data={xpTrajectory} margin={{ top: 5, right: 0, left: 0, bottom: 0 }}>
                    <defs>
                      <linearGradient id="colorXp" x1="0" y1="0" x2="0" y2="1">
                        <stop offset="5%" stopColor={arcColor} stopOpacity={0.35}/>
                        <stop offset="95%" stopColor={arcColor} stopOpacity={0}/>
                      </linearGradient>
                    </defs>
                    <Tooltip content={<CustomTooltip />} />
                    <Area type="monotone" dataKey="xp" stroke={arcColor} fillOpacity={1} fill="url(#colorXp)" strokeWidth={2} />
                  </AreaChart>
                </ResponsiveContainer>
              </div>
            </div>

            {/* DAILY CLASSIFIED BRIEFING */}
            <div className="dashboard-card p-5 sm:p-6 relative overflow-hidden" style={{ borderLeft: '4px solid rgba(168, 85, 247, 0.6)' }}>
              <div className="flex items-center gap-2 mb-2.5">
                <Sparkles size={14} className="text-purple-400" />
                <span className="font-mono text-[9px] sm:text-[10px] uppercase tracking-widest text-purple-300 font-bold">Daily Briefing // Mindset</span>
              </div>
              <p className="font-display text-white text-base sm:text-lg leading-snug italic font-medium">
                "{briefing}"
              </p>
            </div>

          </div>

          {/* RIGHT SIDEBAR (4 cols) */}
          <div className="col-4 flex flex-col gap-3 lg:gap-4">

            {/* OPAL CIRCULAR MOMENTUM FOCUS RING */}
            <div className="dashboard-card relative overflow-hidden flex flex-col items-center text-center p-5 sm:p-6" style={{ borderTop: `1px solid ${momentumColor}30` }}>
              {/* Luminous atmospheric aura glow behind ring */}
              <div 
                className="absolute top-1/2 left-1/2 -translate-x-1/2 -translate-y-1/2 w-48 h-48 rounded-full pointer-events-none filter blur-3xl opacity-20 transition-all duration-700"
                style={{ background: momentumColor }}
              />

              <div className="flex items-center justify-between w-full mb-3 relative z-10">
                <div className="flex items-center gap-2">
                  <Activity size={14} style={{ color: momentumColor }} />
                  <span className="font-mono text-[9px] sm:text-[10px] uppercase tracking-widest text-slate-300 font-bold">
                    Momentum Focus
                  </span>
                </div>
                <span 
                  className="px-2.5 py-0.5 rounded-full font-mono text-[8px] font-black uppercase tracking-wider border shadow-sm"
                  style={{
                    color: momentumColor,
                    borderColor: `${momentumColor}40`,
                    background: `${momentumColor}15`
                  }}
                >
                  {dailyMomentum?.state || momentumText}
                </span>
              </div>

              {/* Signature Opal SVG Circular Gauge */}
              <div className="relative w-36 h-36 sm:w-44 sm:h-44 flex items-center justify-center my-1 shrink-0">
                <svg className="w-full h-full transform -rotate-90" viewBox="0 0 176 176">
                  {/* Background Track Ring */}
                  <circle
                    cx="88"
                    cy="88"
                    r="68"
                    fill="none"
                    stroke="rgba(255, 255, 255, 0.06)"
                    strokeWidth="9"
                    strokeLinecap="round"
                  />
                  {/* Glowing Active Arc */}
                  <circle
                    cx="88"
                    cy="88"
                    r="68"
                    fill="none"
                    stroke={momentumColor}
                    strokeWidth="9"
                    strokeDasharray={2 * Math.PI * 68}
                    strokeDashoffset={2 * Math.PI * 68 * (1 - Math.max(0.06, Math.min(1, ((momentumScore + 10) / 20))))}
                    strokeLinecap="round"
                    style={{
                      transition: 'stroke-dashoffset 1.2s cubic-bezier(0.16, 1, 0.3, 1)',
                      filter: `drop-shadow(0 0 8px ${momentumColor}80)`
                    }}
                  />
                </svg>

                {/* Ring Center Metrics */}
                <div className="absolute inset-0 flex flex-col items-center justify-center pointer-events-none">
                  <span className="font-mono text-[8px] uppercase tracking-widest text-slate-400 font-semibold mb-0.5">
                    Momentum
                  </span>
                  <div 
                    className="font-display font-black tracking-tight leading-none"
                    style={{ fontSize: '2rem', color: momentumColor }}
                  >
                    {momentumScore > 0 ? '+' : ''}{momentumScore}
                  </div>
                  <span className="font-mono text-[7px] text-slate-500 uppercase mt-1">
                    -10 to +10 range
                  </span>
                </div>
              </div>

              {/* Status Pills: Streak & Win Rate */}
              <div style={{ display: 'grid', gridTemplateColumns: '1fr 1fr', gap: '8px', width: '100%' }} className="mt-3.5 relative z-10">
                <div className="flex items-center justify-center gap-1.5 py-2 px-3 rounded-2xl bg-white/[0.03] border border-white/10">
                  <Flame size={14} color={flameColor} className="animate-pulse" />
                  <span className="font-mono font-bold text-white text-xs">
                    {currentStreak} <span className="text-[9px] text-slate-400 font-normal">days streak</span>
                  </span>
                </div>
                <div className="flex items-center justify-center gap-1.5 py-2 px-3 rounded-2xl bg-white/[0.03] border border-white/10">
                  <Zap size={13} className="text-cyan-400" />
                  <span className="font-mono font-bold text-white text-xs">
                    {weeklyWinRate}% <span className="text-[9px] text-slate-400 font-normal">win rate</span>
                  </span>
                </div>
              </div>

              {/* Interactive Breakdown Accordion Toggle */}
              <button
                type="button"
                onClick={() => setMomentumExpanded(!momentumExpanded)}
                className="w-full mt-3 py-2 px-3 rounded-xl bg-white/[0.02] hover:bg-white/[0.06] border border-white/5 hover:border-white/10 flex items-center justify-between text-slate-400 hover:text-white transition-all text-[9px] font-mono uppercase tracking-wider active:scale-95"
              >
                <span>{momentumExpanded ? 'Hide Factors' : 'View Breakdown Factors'}</span>
                <ChevronDown size={12} className={`transition-transform duration-300 ${momentumExpanded ? 'rotate-180' : ''}`} />
              </button>

              {/* Momentum Breakdown */}
              <AnimatePresence>
                {momentumExpanded && (
                  <motion.div 
                    initial={{ opacity: 0, height: 0 }} 
                    animate={{ opacity: 1, height: 'auto' }} 
                    exit={{ opacity: 0, height: 0 }}
                    className="w-full mt-3 pt-3 overflow-hidden border-t border-white/10"
                  >
                    <div className="flex flex-col gap-2 font-mono text-[9px] text-slate-400 tracking-wider">
                      <div className="flex justify-between items-center py-1 border-b border-white/5">
                        <span>Habits Today ({habitsCompletedToday}/{habitsCompletedToday + habitsFailedToday})</span> 
                        <span className="font-bold" style={{ color: habitComponent > 0 ? '#34d399' : habitComponent < 0 ? '#f87171' : 'inherit' }}>
                          {habitComponent > 0 ? '+' : ''}{habitComponent.toFixed(1)}
                        </span>
                      </div>
                      <div className="flex justify-between items-center py-1 border-b border-white/5">
                        <span>Operations ({tasksCompletedToday} done / {tasksOverdue} overdue)</span> 
                        <span className="font-bold" style={{ color: opsComponent > 0 ? '#34d399' : opsComponent < 0 ? '#f87171' : 'inherit' }}>
                          {opsComponent > 0 ? '+' : ''}{opsComponent.toFixed(1)}
                        </span>
                      </div>
                      <div className="flex justify-between items-center py-1 border-b border-white/5">
                        <span>Missions ({missionsCompleted} done / {missionsStalled} stalled)</span> 
                        <span className="font-bold" style={{ color: missionsComponent > 0 ? '#34d399' : missionsComponent < 0 ? '#f87171' : 'inherit' }}>
                          {missionsComponent > 0 ? '+' : ''}{missionsComponent.toFixed(1)}
                        </span>
                      </div>
                      <div className="flex justify-between items-center py-1 border-b border-white/5">
                        <span>Streak Inertia ({currentStreak}d)</span> 
                        <span className="font-bold" style={{ color: streakComponent > 0 ? '#34d399' : 'inherit' }}>
                          {streakComponent > 0 ? '+' : ''}{streakComponent.toFixed(1)}
                        </span>
                      </div>
                      <div className="flex justify-between items-center py-1 border-b border-white/5">
                        <span>Weekly Win Rate ({weeklyWinRate}%)</span> 
                        <span className="font-bold" style={{ color: winRateComponent > 0 ? '#34d399' : winRateComponent < 0 ? '#f87171' : 'inherit' }}>
                          {winRateComponent > 0 ? '+' : ''}{winRateComponent.toFixed(1)}
                        </span>
                      </div>
                      {todayScreenTime && (
                        <div className="flex justify-between items-center py-1">
                          <span>Screen Intel ({todayScreenTime.total_hours}h / {todayScreenTime.doom_scroll_minutes || 0}m doom)</span> 
                          <span className="font-bold" style={{ color: screenComponent > 0 ? '#34d399' : screenComponent < 0 ? '#f87171' : 'inherit' }}>
                            {screenComponent > 0 ? '+' : ''}{screenComponent.toFixed(1)}
                          </span>
                        </div>
                      )}
                    </div>
                  </motion.div>
                )}
              </AnimatePresence>
            </div>

            {/* XP STAT MATRIX */}
            <div className="dashboard-card p-5 sm:p-6" style={{ borderLeft: `4px solid ${arcColor}` }}>
              <div className="flex items-center justify-between mb-3.5">
                <div className="flex items-center gap-2">
                  <Zap size={14} style={{ color: arcColor }} />
                  <span className="font-mono text-[9px] sm:text-[10px] uppercase tracking-widest text-slate-300 font-bold">XP Matrix</span>
                </div>
                <span className="font-mono text-[8px] text-slate-500 uppercase font-semibold">LV.{currentLevel} DYNAMICS</span>
              </div>
              <div style={{ display: 'grid', gridTemplateColumns: 'repeat(3, 1fr)', gap: '8px' }}>
                <div className="p-3 rounded-2xl bg-white/[0.02] border border-white/5">
                  <div className="font-display font-black tracking-tight leading-none text-cyan-400 text-lg sm:text-xl">
                    {xpNeeded >= 1000 ? `${(xpNeeded / 1000).toFixed(1)}k` : xpNeeded}
                  </div>
                  <div className="font-mono text-[8px] text-slate-400 uppercase mt-1.5">TO LV.{currentLevel + 1}</div>
                </div>
                <div className="p-3 rounded-2xl bg-white/[0.02] border border-white/5">
                  <div className="font-display font-black tracking-tight leading-none text-lg sm:text-xl" style={{ color: (dailyMomentum?.todayNet ?? xpToday) > 0 ? '#34d399' : (dailyMomentum?.todayNet ?? xpToday) < 0 ? '#f87171' : '#94a3b8' }}>
                    {dailyMomentum?.todayNet >= 0 ? '+' : ''}{dailyMomentum?.todayNet ?? xpToday}
                  </div>
                  <div className="font-mono text-[8px] text-slate-400 uppercase mt-1.5">TODAY</div>
                </div>
                <div className="p-3 rounded-2xl bg-white/[0.02] border border-white/5">
                  <div className="font-display font-black tracking-tight leading-none text-lg sm:text-xl" style={{ color: (dailyMomentum?.threeDayNet ?? xpThisWeek) > 0 ? '#34d399' : (dailyMomentum?.threeDayNet ?? xpThisWeek) < 0 ? '#f87171' : '#94a3b8' }}>
                    {dailyMomentum?.threeDayNet >= 0 ? '+' : ''}{dailyMomentum?.threeDayNet ?? xpThisWeek}
                  </div>
                  <div className="font-mono text-[8px] text-slate-400 uppercase mt-1.5">3-DAY NET</div>
                </div>
              </div>
            </div>

            {/* ── DIGITAL ADDICTION WIDGET ── */}
            {addictionData !== null && (
              <div
                className="dashboard-card p-5 sm:p-6 cursor-pointer transition-all hover:border-white/20"
                style={{ borderLeft: `4px solid ${addictionData.addScore >= 55 ? '#ef4444' : addictionData.addScore >= 30 ? '#f59e0b' : '#10b981'}` }}
                onClick={() => setExpandedWidget(expandedWidget === 'addiction' ? null : 'addiction')}
              >
                <div className="flex items-center justify-between mb-3.5">
                  <div className="flex items-center gap-2">
                    <Smartphone size={14} style={{ color: addictionData.addScore >= 55 ? '#ef4444' : addictionData.addScore >= 30 ? '#f59e0b' : '#10b981' }} />
                    <span className="font-mono text-[9px] sm:text-[10px] uppercase tracking-widest text-slate-300 font-bold">Digital Discipline</span>
                  </div>
                  <span className="font-mono text-[8px] font-bold px-2 py-0.5 rounded-full uppercase tracking-wider" style={{
                    color: addictionData.addScore >= 55 ? '#ef4444' : addictionData.addScore >= 30 ? '#f59e0b' : '#10b981',
                    background: addictionData.addScore >= 55 ? 'rgba(239,68,68,0.15)' : addictionData.addScore >= 30 ? 'rgba(245,158,11,0.15)' : 'rgba(16,185,129,0.15)',
                    border: `1px solid ${addictionData.addScore >= 55 ? 'rgba(239,68,68,0.3)' : addictionData.addScore >= 30 ? 'rgba(245,158,11,0.3)' : 'rgba(16,185,129,0.3)'}`
                  }}>
                    {addictionData.addScore >= 55 ? '⚠ HOOKED' : addictionData.addScore >= 30 ? 'DRIFTING' : '✓ CLEAN'}
                  </span>
                </div>

                <div className="flex items-end justify-between mb-3.5">
                  <div>
                    <div className="font-display font-bold tracking-tight leading-none text-2xl sm:text-3xl" style={{ color: addictionData.addScore >= 55 ? '#ef4444' : addictionData.addScore >= 30 ? '#f59e0b' : '#10b981' }}>
                      {addictionData.addScore}
                      <span className="font-mono text-[10px] text-slate-500 ml-1">/ 100</span>
                    </div>
                    <div className="font-mono text-[8px] text-slate-400 uppercase mt-1">Discipline Index</div>
                  </div>
                  <div className="text-right">
                    <div className="font-mono text-[11px] font-bold text-white">{addictionData.avgScreen}h <span className="text-slate-400 font-normal">avg/day</span></div>
                    <div className="font-mono text-[8px] text-slate-400 mt-0.5">{addictionData.daysClean}d clean (7d)</div>
                  </div>
                </div>

                {/* Addiction bar */}
                <div 
                  className="h-1.5 rounded-full bg-white/10 overflow-hidden mb-3"
                  style={{
                    height: '6px',
                    borderRadius: '9999px',
                    background: 'rgba(255, 255, 255, 0.1)',
                    overflow: 'hidden',
                    marginBottom: '12px'
                  }}
                >
                  <motion.div
                    className="h-full rounded-full"
                    style={{ 
                      height: '100%',
                      borderRadius: '9999px',
                      background: addictionData.addScore >= 55 ? '#ef4444' : addictionData.addScore >= 30 ? '#f59e0b' : '#10b981' 
                    }}
                    initial={{ width: 0 }} animate={{ width: `${addictionData.addScore}%` }} transition={{ duration: 1, ease: 'easeOut' }}
                  />
                </div>

                {/* Doomscroll meter */}
                <div className="flex items-center gap-2">
                  <span className="font-mono text-[9px] text-slate-400">Doomscroll 7d:</span>
                  <span className="font-mono text-[10px] font-bold" style={{ color: addictionData.avgDoom > 60 ? '#ef4444' : addictionData.avgDoom > 30 ? '#f59e0b' : '#10b981' }}>
                    {addictionData.avgDoom}m
                  </span>
                  {addictionData.todaySt && (
                    <span className="ml-auto font-mono text-[8px] px-2 py-0.5 rounded-full" style={{
                      background: (parseFloat(addictionData.todaySt.total_hours) || 0) <= 4 ? 'rgba(16,185,129,0.15)' : 'rgba(239,68,68,0.15)',
                      color: (parseFloat(addictionData.todaySt.total_hours) || 0) <= 4 ? '#34d399' : '#f87171'
                    }}>
                      Today: {addictionData.todaySt.total_hours || '?'}h
                    </span>
                  )}
                </div>

                <AnimatePresence>
                  {expandedWidget === 'addiction' && (
                    <motion.div initial={{ height: 0, opacity: 0 }} animate={{ height: 'auto', opacity: 1 }} exit={{ height: 0, opacity: 0 }}
                      className="overflow-hidden mt-3.5 pt-3.5 border-t border-white/10">
                      <div className="flex flex-col gap-2 font-mono text-[9px]">
                        <div className="text-slate-400 uppercase tracking-widest mb-0.5">INTEL BREAKDOWN</div>
                        {[
                          { label: `7-day avg screen time: ${addictionData.avgScreen}h (target ≤4h)`, ok: parseFloat(addictionData.avgScreen) <= 4 },
                          { label: `7-day avg doomscroll: ${addictionData.avgDoom}m (target ≤30m)`, ok: addictionData.avgDoom <= 30 },
                          { label: `Today logged: ${addictionData.todaySt ? addictionData.todaySt.total_hours + 'h' : 'not logged'}`, ok: !!addictionData.todaySt && (parseFloat(addictionData.todaySt.total_hours) || 0) <= 4 },
                          { label: `Clean days in last 7: ${addictionData.daysClean} (target ≥5)`, ok: addictionData.daysClean >= 5 },
                          { label: `Streaming avg: ${addictionData.avgStreaming || '0'}h (target ≤2h)`, ok: parseFloat(addictionData.avgStreaming || 0) <= 2 },
                        ].map((f, i) => (
                          <div key={i} className="flex items-center gap-2">
                            <span style={{ color: f.ok ? '#34d399' : '#f87171' }}>{f.ok ? '✓' : '✗'}</span>
                            <span className="text-slate-300">{f.label}</span>
                          </div>
                        ))}
                        <div className="mt-2 pt-2 border-t border-dashed border-white/10">
                          <div className="text-slate-500">Today's directive: ≤4h screen · ≤30m doom · ≤2h streaming</div>
                        </div>
                      </div>
                    </motion.div>
                  )}
                </AnimatePresence>
              </div>
            )}

            {/* DAY PRESSURE CLOCK */}
            <div className="dashboard-card p-5 sm:p-6">
              <div className="flex items-center justify-between mb-3.5">
                <div className="flex items-center gap-2">
                  <Clock size={14} className="text-slate-400" />
                  <span className="font-mono text-[9px] sm:text-[10px] uppercase tracking-widest text-slate-300 font-bold">Time Remaining</span>
                </div>
                <span className="font-mono text-[8px] font-bold px-2 py-0.5 rounded-full" style={{
                  color: dayUrgency === 'danger' ? '#f87171' : dayUrgency === 'warning' ? '#fbbf24' : '#94a3b8',
                  background: dayUrgency === 'danger' ? 'rgba(239,68,68,0.15)' : dayUrgency === 'warning' ? 'rgba(245,158,11,0.15)' : 'rgba(255,255,255,0.05)'
                }}>
                  {dayUrgency === 'danger' ? '⚠ EXECUTE NOW' : dayUrgency === 'warning' ? 'WINDOW CLOSING' : 'TIME ON SIDE'}
                </span>
              </div>
              <div className="flex items-center gap-4">
                <div className="relative shrink-0 w-12 h-12">
                  <svg className="w-12 h-12 transform -rotate-90">
                    <circle cx="24" cy="24" r="20" fill="none" stroke="rgba(255,255,255,0.08)" strokeWidth="4" />
                    <circle cx="24" cy="24" r="20" fill="none"
                      stroke={dayUrgency === 'danger' ? '#ef4444' : dayUrgency === 'warning' ? '#f59e0b' : arcColor}
                      strokeWidth="4"
                      strokeDasharray={`${2 * Math.PI * 20}`}
                      strokeDashoffset={`${2 * Math.PI * 20 * (1 - dayPct / 100)}`}
                      style={{ transition: 'stroke-dashoffset 1s ease' }}
                    />
                  </svg>
                  <div className="absolute inset-0 flex items-center justify-center">
                    <span className="font-mono font-bold text-white text-[9px]">{dayPct}%</span>
                  </div>
                </div>
                <div>
                  <div className="font-display font-black text-white text-2xl leading-none">
                    {hoursLeft}<span className="font-mono text-xs text-slate-400 font-normal">h left today</span>
                  </div>
                  <div className="font-mono text-[9px] text-slate-400 mt-1">
                    Day cycle resets at midnight
                  </div>
                </div>
              </div>
            </div>





          </div>
        </div>
      </div>


      {/* QUICK LOG MODAL FOR EOD RECON */}
      <AnimatePresence>
        {eodQuickLogModal && (
          <div className="modal-overlay" onClick={() => setEodQuickLogModal(null)}>
            <motion.div 
              initial={{ opacity: 0, scale: 0.95 }}
              animate={{ opacity: 1, scale: 1 }}
              exit={{ opacity: 0, scale: 0.95 }}
              onClick={e => e.stopPropagation()}
              className="w-full max-w-md p-6 border border-white/10 rounded-3xl shadow-[0_25px_60px_rgba(0,0,0,0.8)] relative m-4"
              style={{
                background: 'rgba(10, 13, 24, 0.96)',
                border: '1px solid rgba(255, 255, 255, 0.12)',
                borderRadius: '24px',
                backdropFilter: 'blur(32px)',
                WebkitBackdropFilter: 'blur(32px)',
                boxShadow: '0 25px 60px rgba(0,0,0,0.8)'
              }}
            >
              <button 
                onClick={() => setEodQuickLogModal(null)}
                className="w-8 h-8 rounded-full bg-white/5 hover:bg-white/10 flex items-center justify-center text-slate-400 hover:text-white transition-all absolute top-4 right-4"
              >
                <X size={16} />
              </button>

              {/* SCREEN INTEL QUICK LOG */}
              {eodQuickLogModal === 'screen' && (
                <form onSubmit={submitEodScreen} className="flex flex-col gap-4">
                  <div className="flex items-center gap-2 text-success border-b border-white/10 pb-3">
                    <Smartphone size={18} />
                    <span className="font-mono text-sm uppercase tracking-widest font-bold text-primary">
                      QUICK LOG // SCREEN INTEL
                    </span>
                  </div>
                  <div>
                    <label className="font-mono text-xs text-muted mb-1 block">TOTAL SCREEN TIME (HOURS)</label>
                    <input type="number" step="0.1" required className="input w-full font-mono text-xs" value={eodScreenForm.total_hours} onChange={e => setEodScreenForm({...eodScreenForm, total_hours: e.target.value})} placeholder="e.g. 4.5" />
                  </div>
                  <div>
                    <label className="font-mono text-xs text-muted mb-1 block">DOOMSCROLL TIME (MINUTES)</label>
                    <input type="number" required className="input w-full font-mono text-xs" value={eodScreenForm.doomscroll_minutes} onChange={e => setEodScreenForm({...eodScreenForm, doomscroll_minutes: e.target.value})} placeholder="e.g. 30" />
                  </div>
                  <div>
                    <label className="font-mono text-xs text-muted mb-1 block">STREAMING / VIDEO TIME (HOURS)</label>
                    <input type="number" step="0.1" required className="input w-full font-mono text-xs" value={eodScreenForm.streaming_hours} onChange={e => setEodScreenForm({...eodScreenForm, streaming_hours: e.target.value})} placeholder="e.g. 1.0" />
                  </div>
                  <div className="flex justify-end gap-2 mt-2">
                    <button type="button" className="btn btn-ghost btn-sm font-mono text-xs" onClick={() => setEodQuickLogModal(null)}>CANCEL</button>
                    <button type="submit" className="btn btn-primary btn-sm font-mono text-xs font-bold">+ SAVE SCREEN INTEL</button>
                  </div>
                </form>
              )}

              {/* JOURNAL QUICK LOG */}
              {eodQuickLogModal === 'journal' && (
                <form onSubmit={submitEodJournal} className="flex flex-col gap-4">
                  <div className="flex items-center gap-2 text-info border-b border-white/10 pb-3">
                    <BookOpen size={18} />
                    <span className="font-mono text-sm uppercase tracking-widest font-bold text-primary">
                      QUICK LOG // DAILY JOURNAL
                    </span>
                  </div>
                  <div>
                    <label className="font-mono text-xs text-muted mb-1 block">TODAY'S MOOD</label>
                    <select className="select w-full font-mono text-xs" value={eodJournalForm.mood} onChange={e => setEodJournalForm({...eodJournalForm, mood: e.target.value})}>
                      <option value="great">🟢 GREAT</option>
                      <option value="good">🟡 GOOD</option>
                      <option value="okay">🟠 OKAY</option>
                      <option value="bad">🔴 BAD</option>
                      <option value="terrible">⚫ TERRIBLE</option>
                    </select>
                  </div>
                  <div>
                    <label className="font-mono text-xs text-muted mb-1 block">DAILY REFLECTION / NOTES</label>
                    <textarea rows={4} required className="textarea w-full font-mono text-xs" value={eodJournalForm.content} onChange={e => setEodJournalForm({...eodJournalForm, content: e.target.value})} placeholder="What did you build, accomplish, or learn today?" />
                  </div>
                  <div className="flex justify-end gap-2 mt-2">
                    <button type="button" className="btn btn-ghost btn-sm font-mono text-xs" onClick={() => setEodQuickLogModal(null)}>CANCEL</button>
                    <button type="submit" className="btn btn-primary btn-sm font-mono text-xs font-bold">+ SAVE JOURNAL ENTRY</button>
                  </div>
                </form>
              )}

              {/* WORK QUICK LOG */}
              {eodQuickLogModal === 'work' && (
                <form onSubmit={submitEodWork} className="flex flex-col gap-4">
                  <div className="flex items-center gap-2 text-purple-400 border-b border-white/10 pb-3">
                    <Briefcase size={18} />
                    <span className="font-mono text-sm uppercase tracking-widest font-bold text-primary">
                      QUICK LOG // WORK SESSION
                    </span>
                  </div>
                  <div>
                    <label className="font-mono text-xs text-muted mb-1 block">HOURS WORKED TODAY</label>
                    <input type="number" step="0.5" required className="input w-full font-mono text-xs" value={eodWorkForm.hours} onChange={e => setEodWorkForm({...eodWorkForm, hours: e.target.value})} placeholder="e.g. 4.0" />
                  </div>
                  <div>
                    <label className="font-mono text-xs text-muted mb-1 block">WORK TYPE / CATEGORY</label>
                    <select className="select w-full font-mono text-xs" value={eodWorkForm.work_type} onChange={e => setEodWorkForm({...eodWorkForm, work_type: e.target.value})}>
                      <option value="deep_work">Deep Work / Engineering</option>
                      <option value="client_work">Client Work / Business</option>
                      <option value="learning">Learning / Research</option>
                      <option value="planning">Strategy & Planning</option>
                    </select>
                  </div>
                  <div>
                    <label className="font-mono text-xs text-muted mb-1 block">WORK NOTES (OPTIONAL)</label>
                    <textarea rows={3} className="textarea w-full font-mono text-xs" value={eodWorkForm.notes} onChange={e => setEodWorkForm({...eodWorkForm, notes: e.target.value})} placeholder="Key tasks accomplished in this session..." />
                  </div>
                  <div className="flex justify-end gap-2 mt-2">
                    <button type="button" className="btn btn-ghost btn-sm font-mono text-xs" onClick={() => setEodQuickLogModal(null)}>CANCEL</button>
                    <button type="submit" className="btn btn-primary btn-sm font-mono text-xs font-bold">+ SAVE WORK LOG</button>
                  </div>
                </form>
              )}

              {/* SPEAKING PRACTICE QUICK LOG */}
              {eodQuickLogModal === 'speaking' && (
                <form onSubmit={submitEodSpeaking} className="flex flex-col gap-4">
                  <div className="flex items-center gap-2 text-amber border-b border-white/10 pb-3">
                    <Mic size={18} />
                    <span className="font-mono text-sm uppercase tracking-widest font-bold text-primary">
                      QUICK LOG // SPEAKING PRACTICE
                    </span>
                  </div>
                  <div>
                    <label className="font-mono text-xs text-muted mb-1 block">TOPIC / TITLE</label>
                    <input type="text" required className="input w-full font-mono text-xs" value={eodSpeakingForm.topic} onChange={e => setEodSpeakingForm({...eodSpeakingForm, topic: e.target.value})} placeholder="e.g. Explain quantum computing..." />
                  </div>
                  <div>
                    <label className="font-mono text-xs text-muted mb-1 block">GOOGLE DRIVE / VIDEO URL (OPTIONAL)</label>
                    <input type="text" className="input w-full font-mono text-xs" value={eodSpeakingForm.drive_link} onChange={e => setEodSpeakingForm({...eodSpeakingForm, drive_link: e.target.value})} placeholder="https://drive.google.com/file/d/..." />
                  </div>
                  <div>
                    <label className="font-mono text-xs text-muted mb-1 block">SPEAKING NOTES (OPTIONAL)</label>
                    <textarea rows={3} className="textarea w-full font-mono text-xs" value={eodSpeakingForm.notes} onChange={e => setEodSpeakingForm({...eodSpeakingForm, notes: e.target.value})} placeholder="Key takeaways from this speech..." />
                  </div>
                  <div className="flex justify-end gap-2 mt-2">
                    <button type="button" className="btn btn-ghost btn-sm font-mono text-xs" onClick={() => setEodQuickLogModal(null)}>CANCEL</button>
                    <button type="submit" className="btn btn-primary btn-sm font-mono text-xs font-bold">+ SAVE SPEAKING LOG</button>
                  </div>
                </form>
              )}
            </motion.div>
          </div>
        )}
      </AnimatePresence>
    </AppShell>
  )
}

'use client'

import { useState, useEffect } from 'react'
import AppShell from '@/components/layout/AppShell'
import HudPanel from '@/components/ui/HudPanel'
import ConfirmModal from '@/components/ui/ConfirmModal'
import TacticalProgress from '@/components/ui/ProgressBar'
import { useGoals } from '@/lib/hooks/useGoals'
import { getLocalDateStr, parseTaskNotes } from '@/lib/utils/dates'
import { useOS } from '@/lib/context/OSContext'
import { Target, Flag, Star, Clock, Plus, Check, Trash2, Pause, Play, Edit2, ChevronDown, ChevronUp, X, RotateCcw, AlertTriangle, CheckSquare, Square } from 'lucide-react'
import { motion, AnimatePresence } from 'framer-motion'

export default function Missions() {
  const { mainQuest, mainQuests, sideQuests, longTermGoals, weeklyGoals, completedGoals, failedGoals, loading, error, fetchGoals, addGoal, completeGoal, undoCompleteGoal, deleteGoal, togglePauseGoal, updateGoal, updateProgress } = useGoals()
  const { failMission, undoFailMission, deleteMission, tasks: { tasks = [], completeOperation, deleteTask } = {} } = useOS() || {}
  const [activeTab, setActiveTab] = useState('main')
  const [showForm, setShowForm] = useState(false)
  const [expandedGoal, setExpandedGoal] = useState(null)
  
  const [confirmModal, setConfirmModal] = useState({ isOpen: false, title: '', message: '', danger: false, onConfirm: null, onCancel: null, confirmText: 'CONFIRM' })
  const [proofModal, setProofModal] = useState({ show: false, goal: null, url: '', note: '' })
  const [failMissionModal, setFailMissionModal] = useState({ show: false, goal: null, reason: '' })
  
  const [editingId, setEditingId] = useState(null)
  const [editForm, setEditForm] = useState({})

  const [formData, setFormData] = useState({ title: '', description: '', type: 'side_quest', difficulty: 'HARD', deadline: '', category: 'personal', customCategory: '' })

  const [isMobile, setIsMobile] = useState(false)
  useEffect(() => {
    setIsMobile(window.innerWidth < 640)
    const handleResize = () => setIsMobile(window.innerWidth < 640)
    window.addEventListener('resize', handleResize)
    return () => window.removeEventListener('resize', handleResize)
  }, [])

  const TABS = [
    { id: 'main', label: 'PRIMARY', icon: Flag, items: mainQuests || (mainQuest ? [mainQuest] : []) },
    { id: 'side', label: 'SIDE OPS', icon: Target, items: sideQuests },
    { id: 'long', label: 'LONG RANGE', icon: Star, items: longTermGoals },
    { id: 'weekly', label: 'WEEKLY', icon: Clock, items: weeklyGoals },
    { id: 'completed', label: 'COMPLETED', icon: Check, items: completedGoals },
    { id: 'failed', label: 'FAILED', icon: AlertTriangle, items: failedGoals }
  ]

  const activeData = TABS.find(t => t.id === activeTab)?.items || []

  const DIFFICULTY_CONFIG = {
    EASY: { label: 'EASY', color: 'var(--info)' },
    MEDIUM: { label: 'MEDIUM', color: 'var(--accent-primary)' },
    HARD: { label: 'HARD', color: 'var(--warning)' },
    EXTREME: { label: 'EXTREME', color: 'var(--danger)' }
  }

  // Helper to group archived goals by Month -> Subheading (Category)
  const groupArchivedGoals = (goalList) => {
    const monthsMap = {}
    goalList.forEach(goal => {
      const dateStr = goal.completed_at || goal.updated_at || goal.deadline || goal.created_at
      const d = dateStr ? new Date(dateStr) : new Date()
      const monthLabel = d.toLocaleString('en-US', { month: 'long', year: 'numeric' }).toUpperCase()
      
      let cat = goal.category || goal.type || 'GENERAL'
      if (cat === 'personal') cat = 'PERSONAL MISSION'
      else if (cat === 'business') cat = 'BEYOND TATVA (BUSINESS)'
      else if (cat === 'health') cat = 'FITNESS / HEALTH'
      else if (cat === 'learning') cat = 'LEARNING / SKILLS'
      else cat = String(cat).toUpperCase().replace('_', ' ')

      if (!monthsMap[monthLabel]) monthsMap[monthLabel] = { total: 0, subheadings: {} }
      monthsMap[monthLabel].total++
      if (!monthsMap[monthLabel].subheadings[cat]) monthsMap[monthLabel].subheadings[cat] = []
      monthsMap[monthLabel].subheadings[cat].push(goal)
    })
    return monthsMap
  }

  const handleAdd = async (e) => {
    e.preventDefault()
    if (formData.type === 'long_term' && !formData.deadline) {
      alert("LONG RANGE MISSIONS REQUIRE A STRICT DEADLINE.")
      return
    }
    let finalDesc = formData.description || ''
    if (formData.category === 'other' && formData.customCategory) {
      finalDesc = `[Category: ${formData.customCategory}]\n\n${finalDesc}`.trim()
    }
    const payload = {
      title: formData.title,
      description: finalDesc || null,
      type: formData.type,
      difficulty: formData.difficulty,
      deadline: formData.deadline || null,
      category: formData.category === 'other' ? 'other' : formData.category
    }
    const result = await addGoal(payload)
    if (result && result.error) {
      alert(`DEPLOYMENT FAILED: ${result.error.message || result.error}\n\nPlease let the AI know what this error says!`)
      return
    }
    
    setFormData({ title: '', description: '', type: 'side_quest', difficulty: 'HARD', deadline: '', category: 'personal', customCategory: '' })
    setShowForm(false)
  }

  const startEdit = (goal) => {
    setEditingId(goal.id)
    setEditForm({
      title: goal.title,
      description: goal.description || '',
      difficulty: goal.difficulty || 'HARD',
      type: goal.type || 'side_quest',
      category: goal.category || 'personal',
      customCategory: '',
      deadline: goal.deadline ? getLocalDateStr(new Date(goal.deadline)) : ''
    })
  }

  const saveEdit = async (id) => {
    const payload = { ...editForm }
    if (payload.category === 'other' && payload.customCategory) {
      payload.description = `[Category: ${payload.customCategory}]\n\n${payload.description || ''}`.trim()
    }
    delete payload.customCategory
    await updateGoal(id, payload)
    setEditingId(null)
  }

  const handleDeleteGoal = async (goal) => {
    setConfirmModal({
      isOpen: true,
      title: 'DELETE MISSION',
      message: `Are you sure you want to delete "${goal.title}"?`,
      danger: true,
      confirmText: 'DELETE',
      onConfirm: async () => {
        let revokeXp = true
        if (goal.status === 'completed' || goal.status === 'failed') {
          setConfirmModal({
            isOpen: true,
            title: 'REVOKE XP?',
            message: 'Do you want to revoke/refund the XP associated with this mission?\n\nREVOKE = XP will be deducted\nKEEP = You keep the XP',
            danger: true,
            confirmText: 'REVOKE XP',
            cancelText: 'KEEP XP',
            onConfirm: async () => {
              await deleteMission(goal.id, true)
              setConfirmModal({ isOpen: false })
            },
            onCancel: async () => {
              await deleteMission(goal.id, false)
              setConfirmModal({ isOpen: false })
            }
          })
          return
        }
        await deleteMission(goal.id, revokeXp)
        setConfirmModal({ isOpen: false })
      },
      onCancel: () => setConfirmModal({ isOpen: false })
    })
  }

  const handleCompleteGoal = (goal) => {
    setProofModal({ show: true, goal, url: '', note: '' })
  }

  const submitMissionCompletion = async (skipNotes = false) => {
    if (!proofModal.goal) return
    const urlToSend = skipNotes ? null : (proofModal.url.trim() || null)
    const noteToSend = skipNotes ? null : (proofModal.note.trim() || null)
    await completeGoal(proofModal.goal.id, urlToSend, false, noteToSend)
    setProofModal({ show: false, goal: null, url: '', note: '' })
  }

  const failGoal = (goal) => {
    setFailMissionModal({ show: true, goal, reason: '' })
  }

  const submitMissionFailure = async () => {
    if (!failMissionModal.goal) return
    await failMission(failMissionModal.goal.id, failMissionModal.reason.trim() || null)
    setFailMissionModal({ show: false, goal: null, reason: '' })
  }

  const renderGoalCard = (goal, i) => {
    const isCompleted = goal.status === 'completed'
    const isFailed = goal.status === 'failed'
    const isPaused = goal.status === 'paused'
    const isEditing = editingId === goal.id
    const isExpanded = expandedGoal === goal.id
    const hasLinked = tasks.some(t => t.goal_id === goal.id)
    const linkedCount = tasks.filter(t => t.goal_id === goal.id).length
    const linkedCompleted = tasks.filter(t => t.goal_id === goal.id && t.status === 'completed').length
    const displayProgress = hasLinked 
      ? Math.round((linkedCompleted / linkedCount) * 100) 
      : (goal.progress || 0)

    // ── THIN STRIP LAYOUT FOR COMPLETED & FAILED MISSIONS ──
    if (isCompleted || isFailed) {
      const dateStr = goal.completed_at 
        ? new Date(goal.completed_at).toLocaleDateString('en-US', { month: 'short', day: 'numeric' }) 
        : (goal.updated_at ? new Date(goal.updated_at).toLocaleDateString('en-US', { month: 'short', day: 'numeric' }) : null)

      return (
        <motion.div
          key={goal.id}
          layout
          initial={{ opacity: 0, y: 10 }}
          animate={{ opacity: 1, y: 0 }}
          exit={{ opacity: 0, scale: 0.95 }}
          className="col-span-1"
        >
          <div className={`p-3 rounded-lg border transition-all ${
            isCompleted ? 'bg-success/5 border-success/30 hover:border-success/60' : 'bg-danger/5 border-danger/30 hover:border-danger/60'
          }`}>
            <div 
              onClick={() => setExpandedGoal(isExpanded ? null : goal.id)}
              className="flex items-center justify-between gap-3 cursor-pointer select-none"
            >
              <div className="flex items-center gap-2.5 min-w-0 flex-1">
                <span className={`shrink-0 w-5 h-5 rounded-full flex items-center justify-center text-xs font-bold ${
                  isCompleted ? 'bg-success/20 text-success' : 'bg-danger/20 text-danger'
                }`}>
                  {isCompleted ? <Check size={12} strokeWidth={3} /> : <X size={12} strokeWidth={3} />}
                </span>
                <span className={`font-mono text-sm font-semibold truncate ${isCompleted ? 'text-muted line-through opacity-80' : 'text-danger line-through'}`}>
                  {goal.title}
                </span>
              </div>

              <div className="flex items-center gap-2 shrink-0">
                {dateStr && (
                  <span className="font-mono text-[10px] text-muted hidden sm:inline">
                    {isCompleted ? `COMPLETED ${dateStr}` : `FAILED ${dateStr}`}
                  </span>
                )}
                <span className={`font-mono text-[9px] font-bold px-2 py-0.5 rounded border uppercase ${
                  isCompleted ? 'bg-success/10 text-success border-success/30' : 'bg-danger/10 text-danger border-danger/30'
                }`}>
                  {isCompleted ? 'DONE' : 'FAILED'}
                </span>
                <button type="button" className="p-1 text-muted hover:text-primary transition-colors">
                  {isExpanded ? <ChevronUp size={16} /> : <ChevronDown size={16} />}
                </button>
              </div>
            </div>

            {/* Expanded Details */}
            <AnimatePresence>
              {isExpanded && (() => {
                const { cleanDesc, completionNote: itemCompNote, failureNote: itemFailNote } = parseTaskNotes(goal.description)
                return (
                  <motion.div initial={{ height: 0, opacity: 0 }} animate={{ height: 'auto', opacity: 1 }} exit={{ height: 0, opacity: 0 }} className="overflow-hidden">
                    <div className="mt-3 pt-3 border-t border-border-color/40 flex flex-col gap-3 font-mono text-xs">
                      {cleanDesc && (
                        <p className="text-secondary whitespace-pre-wrap">{cleanDesc}</p>
                      )}

                      {itemCompNote && (
                        <div className="p-3 rounded-lg border border-success/40 bg-success/10 font-mono text-xs my-1">
                          <div className="text-success font-bold uppercase tracking-wider text-[10px] mb-1 flex items-center gap-1.5">
                            <CheckCircle2 size={13} /> Mission Accomplishment Reflection:
                          </div>
                          <div className="text-primary whitespace-pre-wrap">{itemCompNote}</div>
                        </div>
                      )}

                      {itemFailNote && (
                        <div className="p-3 rounded-lg border border-danger/40 bg-danger/10 font-mono text-xs my-1">
                          <div className="text-danger font-bold uppercase tracking-wider text-[10px] mb-1 flex items-center gap-1.5">
                            <AlertTriangle size={13} /> Reason for Failure:
                          </div>
                          <div className="text-primary whitespace-pre-wrap">{itemFailNote}</div>
                        </div>
                      )}

                      <div className="flex flex-wrap items-center justify-between gap-2 text-[10px] text-muted pt-1">
                        <div>
                          <span className="uppercase">TYPE: {goal.type?.replace('_', ' ')}</span>
                          {goal.category && <span className="ml-3 uppercase">CAT: {goal.category}</span>}
                          {goal.created_at && <span className="ml-3 text-info">DEPLOYED: {new Date(goal.created_at).toLocaleDateString('en-US', { month: 'short', day: 'numeric', year: 'numeric' })}</span>}
                          {goal.completed_at && <span className="ml-3 text-success font-semibold">COMPLETED: {new Date(goal.completed_at).toLocaleDateString('en-US', { month: 'short', day: 'numeric', year: 'numeric' })}</span>}
                        </div>
                        <div className="flex items-center gap-2">
                          {isCompleted && (
                            <button type="button" onClick={(e) => { e.stopPropagation(); undoCompleteGoal(goal.id); }} className="btn btn-ghost btn-xs text-info flex items-center gap-1 font-mono">
                              <RotateCcw size={12} /> RE-OPEN MISSION
                            </button>
                          )}
                          {!isCompleted && (
                            <button type="button" onClick={(e) => { e.stopPropagation(); undoFailMission(goal.id); }} className="btn btn-ghost btn-xs text-info flex items-center gap-1 font-mono">
                              <RotateCcw size={12} /> RESTORE MISSION
                            </button>
                          )}
                          <button type="button" onClick={(e) => { e.stopPropagation(); handleDeleteGoal(goal); }} className="btn btn-ghost btn-xs text-danger p-1" title="Delete">
                            <Trash2 size={13} />
                          </button>
                        </div>
                      </div>
                    </div>
                  </motion.div>
                )
              })()}
            </AnimatePresence>
          </div>
        </motion.div>
      )
    }

    const deadline = goal.target_date || goal.due_date || goal.deadline
    const cleanDeadline = deadline ? deadline.substring(0, 10) : null
    const todayStr = getLocalDateStr()
    const isOverdue = !isCompleted && !isFailed && !isPaused && cleanDeadline && cleanDeadline < todayStr
    let daysOverdue = 0
    let penaltyDeduction = 0
    
    // XP math
    const xpMap = {
      main_quest: 100,
      side_quest: 50,
      weekly: 30,
      long_term: 200
    }
    const baseXP = xpMap[goal.type] || 50
    let netXP = baseXP

    if (isOverdue && cleanDeadline) {
      const [tY, tM, tD] = todayStr.split('-').map(Number)
      const [dY, dM, dD] = cleanDeadline.split('-').map(Number)
      daysOverdue = Math.max(1, Math.round((Date.UTC(tY, tM - 1, tD) - Date.UTC(dY, dM - 1, dD)) / (1000 * 60 * 60 * 24)))
      penaltyDeduction = daysOverdue * 5
      netXP = Math.max(0, baseXP - penaltyDeduction)
    }

    // ── CLEAN CARD LAYOUT FOR ACTIVE MISSIONS ──
    return (
      <motion.div
        key={goal.id}
        layout
        initial={{ opacity: 0, y: 20 }}
        animate={{ opacity: 1, y: 0 }}
        exit={{ opacity: 0, scale: 0.95 }}
        transition={{ delay: i * 0.05 }}
      >
        <HudPanel glow={activeTab === 'main' && !isPaused} scanLine={activeTab === 'main' && !isPaused} className={isPaused ? 'opacity-50' : ''}>
          
          {/* Header Tag Row: Flex wrap ensures tags NEVER collide or overlap */}
          <div className="flex flex-wrap items-center justify-between gap-2 mb-3 pb-2 border-b border-border-color">
            <div className="flex flex-wrap items-center gap-1.5 min-w-0">
              <span className={`px-2 py-0.5 rounded text-[9px] font-mono font-semibold uppercase tracking-wider ${
                isPaused ? 'bg-secondary text-muted border border-border-color' : 'bg-amber/10 text-amber border border-amber/30'
              }`}>
                {isPaused ? 'PAUSED' : goal.type.replace('_', ' ')}
              </span>

              <span className="px-2 py-0.5 rounded text-[9px] font-mono font-semibold uppercase tracking-wider border" 
                    style={{ color: DIFFICULTY_CONFIG[goal.difficulty || 'HARD'].color, borderColor: `${DIFFICULTY_CONFIG[goal.difficulty || 'HARD'].color}40`, background: `${DIFFICULTY_CONFIG[goal.difficulty || 'HARD'].color}10` }}>
                {DIFFICULTY_CONFIG[goal.difficulty || 'HARD'].label}
              </span>

              {isOverdue && (
                <span className="px-2 py-0.5 rounded text-[9px] font-mono font-bold uppercase tracking-wider bg-danger/15 text-danger border border-danger/40 flex items-center gap-1 shrink-0 animate-pulse">
                  <AlertTriangle size={10} /> {daysOverdue}D OVERDUE (-{penaltyDeduction} XP)
                </span>
              )}

              {goal.category && (
                <span className="px-2 py-0.5 rounded text-[9px] font-mono uppercase text-muted bg-bg-primary border border-border-color">
                  {goal.category}
                </span>
              )}
            </div>
            
            {/* Top-Right Control Buttons */}
            <div className="flex items-center gap-1 opacity-80 sm:opacity-60 hover:opacity-100 transition-opacity">
              <button type="button" onClick={(e) => { e.stopPropagation(); togglePauseGoal(goal.id, goal.status); }} className="btn btn-ghost p-1.5" title={isPaused ? 'Resume' : 'Pause'}>
                {isPaused ? <Play size={14} /> : <Pause size={14} />}
              </button>
              <button type="button" onClick={(e) => { e.stopPropagation(); startEdit(goal); }} className="btn btn-ghost p-1.5 hover:text-amber" title="Edit">
                <Edit2 size={14} />
              </button>
              <button type="button" onClick={(e) => { e.stopPropagation(); handleDeleteGoal(goal); }} className="btn btn-ghost p-1.5 hover:text-danger" title="Delete">
                <Trash2 size={14} />
              </button>
            </div>
          </div>
          
          {/* Content */}
          {isEditing ? (
            <div className="flex-col gap-3 mb-4" onClick={(e) => e.stopPropagation()}>
              <input type="text" className="input font-mono text-lg py-1 border-amber" value={editForm.title} onChange={e=>setEditForm({...editForm, title: e.target.value})} />
              <textarea className="textarea font-mono text-sm py-1" value={editForm.description} onChange={e=>setEditForm({...editForm, description: e.target.value})} rows={2} />
              <div className="grid-2 gap-3 mt-3">
                <div>
                  <label className="font-mono text-xs text-muted mb-1 block">DIFFICULTY</label>
                  <select className="select font-mono text-sm py-1" value={editForm.difficulty} onChange={e=>setEditForm({...editForm, difficulty: e.target.value})}>
                    <option value="EASY">EASY</option>
                    <option value="MEDIUM">MEDIUM</option>
                    <option value="HARD">HARD</option>
                    <option value="EXTREME">EXTREME</option>
                  </select>
                </div>
                <div>
                  <label className="font-mono text-xs text-muted mb-1 block">DEADLINE</label>
                  <input type="date" className="input font-mono text-sm py-1" value={editForm.deadline || ''} onChange={e=>setEditForm({...editForm, deadline: e.target.value})} />
                </div>
              </div>
              <div className="grid-2 gap-3 mt-3">
                <div>
                  <label className="font-mono text-xs text-muted mb-1 block">CLASSIFICATION</label>
                  <select className="select font-mono text-sm py-1" value={editForm.type} onChange={e=>setEditForm({...editForm, type: e.target.value})}>
                    <option value="main_quest">PRIMARY MISSION</option>
                    <option value="side_quest">SIDE OPERATION</option>
                    <option value="weekly">WEEKLY TARGET</option>
                    <option value="long_term">LONG RANGE GOAL</option>
                  </select>
                </div>
                <div>
                  <label className="font-mono text-xs text-muted mb-1 block">CATEGORY</label>
                  <select className="select font-mono text-sm py-1" value={editForm.category} onChange={e=>setEditForm({...editForm, category: e.target.value})}>
                    <option value="personal">PERSONAL MISSION</option>
                    <option value="business">BEYOND TATVA (BUSINESS)</option>
                    <option value="health">FITNESS / HEALTH</option>
                    <option value="learning">LEARNING / SKILLS</option>
                    <option value="other">OTHER</option>
                  </select>
                </div>
                {editForm.category === 'other' && (
                  <div className="col-span-2 sm:col-span-1">
                    <label className="font-mono text-xs text-muted mb-1 block">CUSTOM CATEGORY</label>
                    <input type="text" className="input font-mono text-sm py-1" placeholder="e.g. Finance" value={editForm.customCategory} onChange={e=>setEditForm({...editForm, customCategory: e.target.value})} />
                  </div>
                )}
              </div>
              <div className="flex justify-end gap-2 mt-2">
                <button type="button" onClick={() => saveEdit(goal.id)} className="btn btn-primary btn-sm">SAVE</button>
                <button type="button" onClick={() => setEditingId(null)} className="btn btn-ghost btn-sm">CANCEL</button>
              </div>
            </div>
          ) : (
            <div onClick={() => setExpandedGoal(isExpanded ? null : goal.id)} className="cursor-pointer group">
              <div className="flex-between">
                <h3 className="font-display text-2xl uppercase tracking-wide text-primary group-hover:text-amber transition-colors">
                  {goal.title}
                </h3>
                {isExpanded ? <ChevronUp size={16} className="text-muted" /> : <ChevronDown size={16} className="text-muted" />}
              </div>
              {goal.description && (
                <p 
                  className={`text-sm text-secondary mt-2 font-mono cursor-pointer overflow-hidden transition-all ${isExpanded ? 'whitespace-pre-wrap' : 'whitespace-normal line-clamp-2'}`}
                  onClick={(e) => {
                     e.stopPropagation();
                     setExpandedGoal(isExpanded ? null : goal.id);
                  }}
                  title={isExpanded ? "Click to collapse" : "Click to expand"}
                >
                  {goal.description}
                </p>
              )}
            </div>
          )}
          
          {/* Progress Bar Preview on Main Card */}
          <div className="mt-3" onClick={() => setExpandedGoal(isExpanded ? null : goal.id)}>
            <TacticalProgress value={displayProgress} color={isPaused ? 'var(--text-muted)' : 'var(--accent-primary)'} label="COMPLETION" />
          </div>
          
          {/* Expanded Dropdown Accordion: Progress Slider & Milestones */}
          <AnimatePresence>
            {isExpanded && !isEditing && (
              <motion.div 
                initial={{ height: 0, opacity: 0 }} 
                animate={{ height: 'auto', opacity: 1 }} 
                exit={{ height: 0, opacity: 0 }} 
                className="overflow-hidden"
              >
                <div className="mt-4 pt-4 border-t border-border-color flex flex-col gap-4">
                  {/* Dynamic / Manual Progress Slider */}
                  <div onClick={(e) => e.stopPropagation()} className="bg-bg-primary/60 p-3 rounded-lg border border-border-color/60">
                    <div className="flex-between mb-2">
                      <label className="font-mono text-xs text-amber font-semibold">
                        {hasLinked ? `DYNAMIC PROGRESS (LINKED OPS): ${displayProgress}%` : `MANUAL PROGRESS SLIDER: ${displayProgress}%`}
                      </label>
                      <span className="font-mono text-xs font-bold text-primary">{displayProgress}%</span>
                    </div>
                    <input 
                      type="range" 
                      min="0" max="100" 
                      value={displayProgress} 
                      onChange={(e) => !hasLinked && updateProgress(goal.id, parseInt(e.target.value))}
                      className={`w-full ${hasLinked ? 'accent-success opacity-50 cursor-not-allowed' : 'accent-amber-500'}`}
                      disabled={hasLinked}
                    />
                    {hasLinked && (
                      <span className="font-mono text-[10px] text-muted mt-1 block">
                        Progress automatically calculates from linked milestones below.
                      </span>
                    )}
                  </div>

                  {/* Linked Milestones */}
                  {tasks.filter(t => t.goal_id === goal.id).length > 0 && (
                    <div className="pt-2 border-t border-border-color" onClick={(e) => e.stopPropagation()}>
                      <label className="font-mono text-xs text-info mb-2 block font-semibold">MISSION MILESTONES (LINKED OPS)</label>
                      <div className="flex flex-col gap-2">
                        {tasks.filter(t => t.goal_id === goal.id).map(task => {
                          const isCompleted = task.status === 'completed'
                          return (
                            <div key={task.id} className={`flex items-center gap-3 p-2 rounded border ${isCompleted ? 'bg-success/5 border-success/30' : 'bg-tertiary border-border-color'}`}>
                              <button 
                                type="button"
                                onClick={(e) => { e.stopPropagation(); if (!isCompleted) completeOperation(task.id) }}
                                className={`${isCompleted ? 'text-success cursor-default' : 'text-muted hover:text-amber'}`}
                                disabled={isCompleted}
                              >
                                {isCompleted ? <CheckSquare size={16} /> : <Square size={16} />}
                              </button>
                              <span className={`font-mono text-sm flex-1 ${isCompleted ? 'text-muted line-through' : 'text-primary'}`}>
                                {task.title}
                              </span>
                              <button type="button" onClick={(e) => { e.stopPropagation(); deleteTask(task.id) }} className="text-muted hover:text-danger p-1 opacity-50 hover:opacity-100 transition-opacity" title="Delete Linked Operation">
                                <Trash2 size={14} />
                              </button>
                            </div>
                          )
                        })}
                      </div>
                    </div>
                  )}
                </div>
              </motion.div>
            )}
          </AnimatePresence>

          {/* Bottom Primary Action Bar */}
          <div className="flex flex-wrap items-center justify-between gap-3 pt-3 mt-3 border-t border-border-color" onClick={(e) => e.stopPropagation()}>
            <div className="flex flex-col gap-1">
              {goal.created_at && (
                <span className="font-mono text-xs text-info flex items-center gap-1">
                  <Clock size={12} /> DEPLOYED: {new Date(goal.created_at).toLocaleDateString('en-US', { month: 'short', day: 'numeric', year: 'numeric' })}
                </span>
              )}
              {cleanDeadline && (
                <span className={`font-mono text-xs flex items-center gap-1 ${isOverdue ? 'text-danger font-bold' : 'text-muted'}`}>
                  <Clock size={12} /> DEADLINE: {cleanDeadline}
                </span>
              )}
              <div className="font-mono text-[10px] mt-0.5">
                {isOverdue ? (
                  <span className="flex items-center gap-1.5 font-bold">
                    <span className="text-muted line-through">+{baseXP} XP</span>
                    <span className="text-danger">+{netXP} XP (NET)</span>
                  </span>
                ) : (
                  <span className="text-success font-semibold">+{baseXP} XP</span>
                )}
              </div>
            </div>
            
            <div className="flex items-center gap-2 w-full sm:w-auto justify-end">
              <button 
                type="button" 
                onClick={(e) => { e.stopPropagation(); handleCompleteGoal(goal); }} 
                className="btn btn-primary btn-sm flex-1 sm:flex-none flex items-center justify-center gap-1.5 font-bold"
              >
                <Check size={14} strokeWidth={2.5} /> COMPLETE MISSION
              </button>
              <button 
                type="button" 
                onClick={(e) => { e.stopPropagation(); failGoal(goal); }} 
                className="btn btn-ghost btn-sm text-danger flex items-center justify-center gap-1 font-mono"
              >
                <X size={14} /> FAIL
              </button>
            </div>
          </div>

        </HudPanel>
      </motion.div>
    )
  }

  if (error) {
    return (
      <AppShell>
        <div className="flex-center h-full flex-col gap-4 text-center">
          <AlertTriangle size={48} className="text-danger mb-2" />
          <h2 className="font-display text-xl text-danger uppercase tracking-widest">SYSTEM ERROR</h2>
          <p className="font-mono text-sm text-muted max-w-md">{error}</p>
          <button type="button" onClick={() => fetchGoals()} className="btn btn-primary mt-4">RETRY CONNECTION</button>
        </div>
      </AppShell>
    )
  }

  if (loading) return (
    <AppShell>
      <div className="flex-center h-full flex-col gap-2">
        <span className="typewriter-text">LOADING MISSIONS...</span>
        <span className="font-mono text-xs text-cyan-400 font-bold tracking-widest uppercase animate-pulse flex items-center gap-1.5">
          <span>❄️</span> WINTER IS COMING <span>❄️</span>
        </span>
      </div>
    </AppShell>
  )

  return (
    <AppShell>
      <div className="page-container narrow">
        <header className="page-header flex-between">
          <div>
            <h1 className="page-title">MISSIONS</h1>
            <p className="page-subtitle font-mono uppercase text-xs text-amber glow-amber">Strategic objectives and long-term targets.</p>
          </div>
          <button className="btn btn-primary btn-sm flex items-center gap-2 tracking-widest" onClick={() => setShowForm(true)}>
            <Plus size={16} /> NEW MISSION
          </button>
        </header>

        <div className="tab-list mb-8 hide-scrollbar" style={{ overflowX: 'auto', whiteSpace: 'nowrap', display: 'flex', flexWrap: 'nowrap', WebkitOverflowScrolling: 'touch' }}>
          {TABS.map(tab => {
            const Icon = tab.icon
            return (
              <button 
                key={tab.id}
                className={`tab-item flex items-center gap-2 ${activeTab === tab.id ? 'active' : ''}`}
                onClick={() => setActiveTab(tab.id)}
              >
                <Icon size={14} />
                {tab.label}
                <span className="badge ml-1" style={{ fontSize: '9px' }}>{tab.items.length}</span>
              </button>
            )
          })}
        </div>

        {(activeTab === 'completed' || activeTab === 'failed') ? (
          <div className="flex flex-col gap-6">
            {Object.keys(groupArchivedGoals(activeData)).length === 0 ? (
              <div className="text-center py-16">
                <div className="font-mono text-sm text-muted mb-4">
                  {activeTab === 'completed' ? 'NO COMPLETED MISSIONS YET.' : 'NO FAILED MISSIONS YET.'}
                </div>
                <button type='button' onClick={() => setShowForm(true)} className="btn btn-primary btn-sm">DEPLOY MISSION</button>
              </div>
            ) : (
              Object.entries(groupArchivedGoals(activeData)).map(([monthLabel, { total, subheadings }]) => (
                <div key={monthLabel} className="mb-4">
                  <div className="flex items-center gap-2 p-3 rounded-sm bg-bg-secondary border border-border-color mb-4">
                    <Clock size={14} className="text-amber" />
                    <span className="font-mono text-xs uppercase tracking-widest font-bold text-amber">{monthLabel}</span>
                    <span className="font-mono text-[9px] text-muted ml-auto font-bold">({total} {total === 1 ? 'MISSION' : 'MISSIONS'})</span>
                  </div>

                  {Object.entries(subheadings).map(([subheading, subheadingGoals]) => (
                    <div key={subheading} className="mb-5 pl-2 sm:pl-4 border-l-2 border-border-color">
                      <div className="flex items-center gap-2 mb-3">
                        <Target size={11} className="text-info" />
                        <span className="font-mono text-[10px] uppercase tracking-widest font-bold text-info">{subheading}</span>
                        <span className="font-mono text-[9px] text-muted">({subheadingGoals.length})</span>
                      </div>
                      <div className="flex flex-col gap-4">
                        <AnimatePresence mode="popLayout">
                          {subheadingGoals.map((goal, i) => renderGoalCard(goal, i))}
                        </AnimatePresence>
                      </div>
                    </div>
                  ))}
                </div>
              ))
            )}
          </div>
        ) : (
          <div className="flex flex-col gap-6">
            <AnimatePresence mode="popLayout">
              {activeData.map((goal, i) => renderGoalCard(goal, i))}
            </AnimatePresence>
            {activeData.length === 0 && (
              <div className="text-center py-16">
                <div className="font-mono text-sm text-muted mb-4">
                  NO MISSIONS IN THIS CATEGORY.
                </div>
                <button type='button' onClick={() => setShowForm(true)} className="btn btn-primary btn-sm">DEPLOY MISSION</button>
              </div>
            )}
          </div>
        )}

        {/* Modal Form */}
        <AnimatePresence>
          {showForm && (
            <div className="modal-overlay">
              <motion.div initial={{ opacity: 0, y: 50 }} animate={{ opacity: 1, y: 0 }} exit={{ opacity: 0, y: 50 }} className="w-full sm:w-auto p-4">
                <HudPanel className="modal-content">
                  <div className="font-display text-xl uppercase text-amber mb-4 border-b border-border-color pb-2 flex items-center gap-2"><Target size={18} /> Initialize Mission</div>
                  <form onSubmit={handleAdd} className="flex-col gap-4">
                    <div>
                      <label className="font-mono text-xs text-muted mb-1 block">MISSION TITLE</label>
                      <input type="text" className="input" value={formData.title} onChange={e=>setFormData({...formData, title: e.target.value})} required autoFocus />
                    </div>
                    <div>
                      <label className="font-mono text-xs text-muted mb-1 block">CLASSIFICATION</label>
                      <select className="select font-mono" value={formData.type} onChange={e=>setFormData({...formData, type: e.target.value})}>
                        <option value="main_quest">PRIMARY MISSION</option>
                        <option value="side_quest">SIDE OPERATION</option>
                        <option value="weekly">WEEKLY TARGET</option>
                        <option value="long_term">LONG RANGE GOAL</option>
                      </select>
                    </div>
                    <div>
                      <label className="font-mono text-xs text-muted mb-1 block">DIFFICULTY</label>
                      <select className="select font-mono" value={formData.difficulty} onChange={e=>setFormData({...formData, difficulty: e.target.value})}>
                        <option value="EASY">EASY</option>
                        <option value="MEDIUM">MEDIUM</option>
                        <option value="HARD">HARD</option>
                        <option value="EXTREME">EXTREME</option>
                      </select>
                    </div>
                    <div>
                      <label className="font-mono text-xs text-muted mb-1 block">CATEGORY</label>
                      <select className="select font-mono w-full" value={formData.category} onChange={e=>setFormData({...formData, category: e.target.value})}>
                        <option value="personal">PERSONAL MISSION</option>
                        <option value="business">BEYOND TATVA (BUSINESS)</option>
                        <option value="health">FITNESS / HEALTH</option>
                        <option value="learning">LEARNING / SKILLS</option>
                        <option value="other">OTHER</option>
                      </select>
                    </div>
                    {formData.category === 'other' && (
                      <div>
                        <label className="font-mono text-xs text-muted mb-1 block">CUSTOM CATEGORY</label>
                        <input type="text" className="input" placeholder="e.g. Finance, Family" value={formData.customCategory} onChange={e=>setFormData({...formData, customCategory: e.target.value})} />
                      </div>
                    )}
                    <div>
                      <label className="font-mono text-xs text-muted mb-1 block">
                        {formData.type === 'long_term' ? 'STRICT DEADLINE (REQUIRED)' : 'DEADLINE (OPTIONAL)'}
                      </label>
                      <input type="date" className="input" value={formData.deadline} onChange={e=>setFormData({...formData, deadline: e.target.value})} required={formData.type === 'long_term'} />
                    </div>
                    <div>
                      <label className="font-mono text-xs text-muted mb-1 block">BRIEFING (OPTIONAL)</label>
                      <textarea className="textarea" value={formData.description} onChange={e=>setFormData({...formData, description: e.target.value})} />
                    </div>
                    <div className="flex gap-2 mt-4">
                      <button type="submit" className="btn btn-primary flex-1">DEPLOY</button>
                      <button type="button" className="btn btn-ghost" onClick={() => setShowForm(false)}>ABORT</button>
                    </div>
                  </form>
                </HudPanel>
              </motion.div>
            </div>
          )}
        </AnimatePresence>

        {/* MISSION ACCOMPLISHED REPORT MODAL */}
        <AnimatePresence>
          {proofModal.show && proofModal.goal && (
            <div className="modal-overlay">
              <motion.div initial={{ opacity: 0, y: 50 }} animate={{ opacity: 1, y: 0 }} exit={{ opacity: 0, y: 50 }} className="w-full sm:w-auto p-4">
                <HudPanel glow label="MISSION ACCOMPLISHED" className="modal-content w-full max-w-lg border-success">
                  <div className="p-4 flex flex-col gap-4">
                    <div>
                      <span className="font-mono text-[10px] text-muted uppercase block">MISSION TITLE</span>
                      <p className="font-mono text-base font-bold text-primary">{proofModal.goal.title}</p>
                      
                      {(() => {
                        const deadline = proofModal.goal.target_date || proofModal.goal.due_date || proofModal.goal.deadline
                        const cleanDeadline = deadline ? deadline.substring(0, 10) : null
                        const todayStr = getLocalDateStr()
                        const isGoalOverdue = cleanDeadline && cleanDeadline < todayStr
                        if (!isGoalOverdue) return null

                        const [tY, tM, tD] = todayStr.split('-').map(Number)
                        const [dY, dM, dD] = cleanDeadline.split('-').map(Number)
                        const daysOverdue = Math.max(1, Math.round((Date.UTC(tY, tM - 1, tD) - Date.UTC(dY, dM - 1, dD)) / (1000 * 60 * 60 * 24)))
                        const xpMap = { main_quest: 100, side_quest: 50, weekly: 30, long_term: 200 }
                        const baseXP = xpMap[proofModal.goal.type] || 50
                        const penalty = daysOverdue * 5
                        const netXP = Math.max(0, baseXP - penalty)

                        return (
                          <div className="mt-2 p-2.5 rounded-lg bg-danger/10 border border-danger/30 font-mono text-xs flex items-center justify-between text-danger">
                            <span className="flex items-center gap-1.5 font-bold">
                              <AlertTriangle size={13} /> {daysOverdue}D OVERDUE PENALTY
                            </span>
                            <span>-{penalty} XP (Net: +{netXP} XP)</span>
                          </div>
                        )
                      })()}
                    </div>

                    <div>
                      <label className="font-mono text-xs text-amber font-semibold mb-1 block">
                        WHAT WAS ACCOMPLISHED? (ACCOMPLISHMENT REFLECTION / NOTES)
                      </label>
                      <textarea 
                        className="textarea font-mono text-xs w-full p-2.5 bg-bg-primary border border-border-color focus:border-success focus:outline-none" 
                        rows={3}
                        placeholder="Describe key outcomes, milestones achieved, deliverables..."
                        value={proofModal.note} 
                        onChange={(e) => setProofModal({ ...proofModal, note: e.target.value })} 
                        autoFocus 
                      />
                    </div>

                    <div>
                      <label className="font-mono text-xs text-muted mb-1 block">ATTACH PROOF LINK / IMAGE URL (OPTIONAL)</label>
                      <input 
                        type="url" 
                        className="input font-mono text-xs w-full px-3 py-2 bg-bg-primary border border-border-color" 
                        value={proofModal.url} 
                        onChange={(e) => setProofModal({ ...proofModal, url: e.target.value })} 
                        placeholder="https://..." 
                      />
                    </div>
                    
                    <div className="flex flex-col gap-2 mt-2">
                      <button className="btn btn-primary w-full py-2.5 font-bold flex items-center justify-center gap-2" onClick={() => submitMissionCompletion(false)}>
                        <Check size={16} /> CONFIRM & LOG MISSION
                      </button>
                      <button className="btn btn-ghost btn-xs text-muted font-mono" onClick={() => submitMissionCompletion(true)}>
                        QUICK COMPLETE (SKIP NOTES)
                      </button>
                    </div>
                  </div>
                </HudPanel>
              </motion.div>
            </div>
          )}
        </AnimatePresence>

        {/* MISSION FAILURE REASON MODAL */}
        <AnimatePresence>
          {failMissionModal.show && failMissionModal.goal && (
            <div className="modal-overlay">
              <motion.div initial={{ opacity: 0, y: 50 }} animate={{ opacity: 1, y: 0 }} exit={{ opacity: 0, y: 50 }} className="w-full sm:w-auto p-4">
                <HudPanel label="FAIL MISSION" className="modal-content w-full max-w-md border-danger">
                  <div className="p-4 flex flex-col gap-4">
                    <div>
                      <span className="font-mono text-[10px] text-muted uppercase block">MISSION TITLE</span>
                      <p className="font-mono text-base font-bold text-primary">{failMissionModal.goal.title}</p>
                      <p className="font-mono text-xs text-danger mt-1">XP penalty will be applied based on mission difficulty.</p>
                    </div>

                    <div>
                      <label className="font-mono text-xs text-secondary font-semibold mb-1 block">REASON FOR FAILURE / LESSONS (OPTIONAL)</label>
                      <textarea 
                        className="textarea font-mono text-xs w-full p-2.5 bg-bg-primary border border-border-color focus:border-danger focus:outline-none" 
                        rows={3}
                        placeholder="Why was this mission failed or aborted? Key lessons or bottlenecks..."
                        value={failMissionModal.reason} 
                        onChange={(e) => setFailMissionModal({ ...failMissionModal, reason: e.target.value })} 
                        autoFocus 
                      />
                    </div>

                    <div className="flex justify-end gap-3 mt-2">
                      <button className="btn btn-ghost font-mono" onClick={() => setFailMissionModal({ show: false, goal: null, reason: '' })}>CANCEL</button>
                      <button className="btn btn-primary bg-danger hover:bg-danger/80 border-danger font-bold flex items-center gap-1.5" onClick={submitMissionFailure}>
                        <X size={16} /> CONFIRM FAILURE (-XP)
                      </button>
                    </div>
                  </div>
                </HudPanel>
              </motion.div>
            </div>
          )}
        </AnimatePresence>
        
        <ConfirmModal {...confirmModal} />
      </div>
    </AppShell>
  )
}

'use client'

import { useState, useEffect } from 'react'
import { motion, AnimatePresence } from 'framer-motion'
import AppShell from '@/components/layout/AppShell'
import HudPanel from '@/components/ui/HudPanel'
import { useOS } from '@/lib/context/OSContext'
import { createClient } from '@/lib/supabase/client'
import { useAuth } from '@/lib/hooks/useAuth'
import { getLocalDateStr, formatDate, getStartOfWeek, getEndOfWeek, getDebriefSortTime } from '@/lib/utils/dates'
import { evaluateProtocolAutoFail } from '@/lib/utils/protocolAutoFail'
import {
  BookOpen, Smile, Frown, Meh, Save, Zap, Flame, ShieldAlert,
  CalendarDays, Trophy, CheckSquare, Target, ArrowRight, AlertTriangle,
  Pencil, ChevronLeft, ChevronRight, RotateCcw, X
} from 'lucide-react'

const MOODS = [
  { id: 'excellent', emoji: '🔥', color: 'var(--amber)' },
  { id: 'good', emoji: '😊', color: 'var(--success)' },
  { id: 'neutral', emoji: '😐', color: 'var(--info)' },
  { id: 'bad', emoji: '🙁', color: 'var(--warning)' },
  { id: 'exhausted', emoji: '😫', color: 'var(--danger)' }
]

function RenderDebrief({ text }) {
  if (!text) return null
  const sections = text.split('### ').filter(s => s.trim())
  return (
    <div className="space-y-6">
      {sections.map((sec, idx) => {
        const lines = sec.split('\n')
        const header = lines[0].trim()
        const body = lines.slice(1).join('\n').trim()

        let color = 'text-primary'
        if (header.includes('What went well')) color = 'text-success'
        if (header.includes('Bottlenecks')) color = 'text-danger'
        if (header.includes('Priorities')) color = 'text-info'

        return (
          <div key={idx} className="space-y-2">
            <h4 className={`font-mono text-sm font-bold uppercase tracking-wider ${color}`}>
              {header}
            </h4>
            <div className="font-mono text-xs text-muted whitespace-pre-wrap leading-relaxed pl-3 border-l-2 border-border-color">
              {body}
            </div>
          </div>
        )
      })}
    </div>
  )
}

export default function JournalPage() {
  const { journal: { entries = [], loading = false, saveEntry, clearJournal } = {} } = useOS() || {}
  const { user } = useAuth()

  useEffect(() => {
    if (user?.id) {
      evaluateProtocolAutoFail(user.id)
    }
  }, [user])

  const [activeTab, setActiveTab] = useState('daily')

  useEffect(() => {
    if (typeof window !== 'undefined') {
      const params = new URLSearchParams(window.location.search)
      if (params.get('tab') === 'weekly') {
        setActiveTab('weekly')
      }
    }
  }, [])

  // ─── DAILY JOURNAL STATE ───
  const [content, setContent] = useState('')
  const [mood, setMood] = useState('')
  const [saving, setSaving] = useState(false)
  const [showHistory, setShowHistory] = useState(false)
  const [expandedArchive, setExpandedArchive] = useState(null)
  const [entryDate, setEntryDate] = useState('')

  // ─── WEEKLY DEBRIEF STATE ───
  const [loadingStats, setLoadingStats] = useState(true)
  const [stats, setStats] = useState({ xp: 0, tasks: 0, habits: 0, missions: 0 })
  const [wins, setWins] = useState('')
  const [fails, setFails] = useState('')
  const [nextGoal1, setNextGoal1] = useState('')
  const [nextGoal2, setNextGoal2] = useState('')
  const [nextGoal3, setNextGoal3] = useState('')
  const [savingDebrief, setSavingDebrief] = useState(false)
  const [dateRange, setDateRange] = useState({ start: '', end: '' })
  const [showDebriefHistory, setShowDebriefHistory] = useState(false)
  const [historyLogs, setHistoryLogs] = useState([])
  const [expandedDebrief, setExpandedDebrief] = useState(null)

  // Past Week Navigation & Edit State for Weekly Debriefs
  const [debriefWeekOffset, setDebriefWeekOffset] = useState(0)
  const [editingDebriefLog, setEditingDebriefLog] = useState(null)

  const parseDebriefContent = (description = '') => {
    let winsText = ''
    let failsText = ''
    let goal1 = ''
    let goal2 = ''
    let goal3 = ''

    const winsIdx = description.indexOf('### What went well?')
    const failsIdx = description.indexOf('### Bottlenecks & Fails')
    const goalsIdx = description.indexOf('### Priorities for Next Week')

    if (winsIdx !== -1) {
      const endIdx = failsIdx !== -1 ? failsIdx : (goalsIdx !== -1 ? goalsIdx : description.length)
      winsText = description.substring(winsIdx + '### What went well?'.length, endIdx).trim()
    }

    if (failsIdx !== -1) {
      const endIdx = goalsIdx !== -1 ? goalsIdx : description.length
      failsText = description.substring(failsIdx + '### Bottlenecks & Fails'.length, endIdx).trim()
    }

    if (goalsIdx !== -1) {
      const goalsText = description.substring(goalsIdx + '### Priorities for Next Week'.length).trim()
      const lines = goalsText.split('\n').map(l => l.replace(/^\d+[\.\)]\s*/, '').replace(/\[DONE\]|\[FAILED\]/g, '').trim()).filter(Boolean)
      if (lines[0]) goal1 = lines[0]
      if (lines[1]) goal2 = lines[1]
      if (lines[2]) goal3 = lines[2]
    }

    return { wins: winsText, fails: failsText, goal1, goal2, goal3 }
  }

  const handleStartEditDebrief = (log) => {
    setEditingDebriefLog(log)
    const parsed = parseDebriefContent(log.description)
    setWins(parsed.wins)
    setFails(parsed.fails)
    setNextGoal1(parsed.goal1)
    setNextGoal2(parsed.goal2)
    setNextGoal3(parsed.goal3)
    setShowDebriefHistory(false)
  }

  const handleCancelEditDebrief = () => {
    setEditingDebriefLog(null)
    setWins('')
    setFails('')
    setNextGoal1('')
    setNextGoal2('')
    setNextGoal3('')
  }

  const getWordCount = (str) => {
    if (!str || !str.trim()) return 0
    return str.trim().split(/\s+/).length
  }

  useEffect(() => { setEntryDate(getLocalDateStr()) }, [])

  useEffect(() => {
    if (editingDebriefLog) return
    const targetDate = new Date()
    targetDate.setDate(targetDate.getDate() + (debriefWeekOffset * 7))
    const startOfWeek = getStartOfWeek(targetDate)
    const endOfWeek = getEndOfWeek(targetDate)
    const startStr = getLocalDateStr(startOfWeek)
    const endStr = getLocalDateStr(endOfWeek)
    setDateRange({ start: formatDate(startStr, 'MMM DD'), end: formatDate(endStr, 'MMM DD') })
  }, [debriefWeekOffset, editingDebriefLog])

  useEffect(() => {
    if (!user || activeTab !== 'weekly') return

    // Synchronously read cached debrief history for 0ms delay
    try {
      const cached = localStorage.getItem(`lokios_debrief_history_${user.id}`)
      if (cached) {
        setHistoryLogs(JSON.parse(cached))
      }
    } catch (e) {}

    const supabase = createClient()
    const today = new Date()
    const startOfWeek = getStartOfWeek(today)
    const endOfWeek = getEndOfWeek(today)
    const startStr = getLocalDateStr(startOfWeek)
    const endStr = getLocalDateStr(endOfWeek)

    Promise.all([
      supabase.from('xp_history').select('amount').eq('user_id', user.id).gte('created_at', startStr).lte('created_at', endStr + 'T23:59:59.999Z'),
      supabase.from('habit_logs').select('status').eq('user_id', user.id).gte('date', startStr).lte('date', endStr).eq('status', 'completed'),
      supabase.from('tasks').select('id').eq('user_id', user.id).gte('completed_at', startStr).lte('completed_at', endStr + 'T23:59:59.999Z').eq('status', 'completed'),
      supabase.from('goals').select('id').eq('user_id', user.id).gte('completed_at', startStr).lte('completed_at', endStr + 'T23:59:59.999Z').eq('status', 'completed'),
      supabase.from('work_logs').select('*').eq('user_id', user.id).ilike('title', 'Weekly Debrief%').order('created_at', { ascending: false })
    ]).then(([xpRes, habitRes, taskRes, goalRes, historyRes]) => {
      setStats({
        xp: (xpRes.data || []).reduce((s, l) => s + l.amount, 0),
        habits: (habitRes.data || []).length,
        tasks: (taskRes.data || []).length,
        missions: (goalRes.data || []).length
      })
      if (historyRes.data) {
        setHistoryLogs(prev => {
          const map = new Map()
          // Add local cached entries first
          prev.forEach(l => map.set(l.title || l.id, l))
          // Add Supabase entries
          historyRes.data.forEach(l => map.set(l.title || l.id, l))
          const merged = Array.from(map.values()).sort((a, b) => {
            const timeA = getDebriefSortTime(a)
            const timeB = getDebriefSortTime(b)
            if (timeA !== timeB) return timeB - timeA
            return (b.created_at || '').localeCompare(a.created_at || '')
          })
          if (typeof window !== 'undefined') {
            localStorage.setItem(`lokios_debrief_history_${user.id}`, JSON.stringify(merged))
          }
          return merged
        })
      }
      setLoadingStats(false)
    })
  }, [user, activeTab])

  const handleSaveJournal = async (e) => {
    e.preventDefault()
    if (!mood) { alert('Please select a mood vector.'); return }
    if (!content.trim()) { alert('Please enter your journal reflection.'); return }
    setSaving(true)
    const success = await saveEntry({ content, mood, date: entryDate })
    setSaving(false)
    if (success) { setContent(''); setMood(''); setShowHistory(true) }
  }

  const handleSaveDebrief = async (e) => {
    e.preventDefault()
    if (!user || savingDebrief) return
    const goalsList = [nextGoal1, nextGoal2, nextGoal3].filter(g => typeof g === 'string' && g.trim())
    if (!wins.trim() || !fails.trim() || goalsList.length === 0) { 
      alert('Please fill out wins, fails, and at least 1 Next Week Priority Goal.')
      return 
    }
    setSavingDebrief(true)
    const supabase = createClient()
    const todayStr = getLocalDateStr(new Date())
    const formattedGoals = goalsList.map((g, i) => `${i + 1}. ${g.trim()}`).join('\n')
    const formattedContent = `### What went well?\n${wins}\n\n### Bottlenecks & Fails\n${fails}\n\n### Priorities for Next Week\n${formattedGoals}`
    
    const targetDate = new Date()
    targetDate.setDate(targetDate.getDate() + (debriefWeekOffset * 7))
    const startOfWeek = getStartOfWeek(targetDate)
    const endOfWeek = getEndOfWeek(targetDate)
    const startStr = getLocalDateStr(startOfWeek)
    const endStr = getLocalDateStr(endOfWeek)
    const rangeStart = dateRange.start || formatDate(startStr, 'MMM DD')
    const rangeEnd = dateRange.end || formatDate(endStr, 'MMM DD')
    const debriefTitle = editingDebriefLog ? editingDebriefLog.title : `Weekly Debrief: ${rangeStart} - ${rangeEnd}`
    const cycleEndDateStr = getLocalDateStr(endOfWeek)

    const logPayload = {
      user_id: user.id,
      title: debriefTitle,
      type: 'project_work',
      description: formattedContent,
      date: editingDebriefLog?.date || cycleEndDateStr,
      created_at: editingDebriefLog?.created_at || new Date().toISOString(),
      updated_at: new Date().toISOString()
    }

    try {
      // 1. Locate existing debrief record if updating
      let targetId = editingDebriefLog && !editingDebriefLog.id.toString().startsWith('debrief_') ? editingDebriefLog.id : null
      
      if (!targetId) {
        // Query by exact title or matching week range
        const { data: existingLogs } = await supabase
          .from('work_logs')
          .select('id, title, date')
          .eq('user_id', user.id)
          .or(`title.eq.${debriefTitle},title.ilike.%${rangeStart}%${rangeEnd}%`)
          .limit(1)
        if (existingLogs && existingLogs.length > 0) {
          targetId = existingLogs[0].id
        }
      }

      if (!targetId) {
        // Also query by date where title is a weekly debrief
        const { data: existingByDate } = await supabase
          .from('work_logs')
          .select('id, title, date')
          .eq('user_id', user.id)
          .eq('date', logPayload.date)
          .ilike('title', 'Weekly Debrief%')
          .limit(1)
        if (existingByDate && existingByDate.length > 0) {
          targetId = existingByDate[0].id
        }
      }

      let savedRecord = null

      if (targetId) {
        const { data: updatedData, error: updateErr } = await supabase
          .from('work_logs')
          .update({
            description: formattedContent,
            title: debriefTitle,
            type: 'project_work',
            date: logPayload.date,
            updated_at: new Date().toISOString()
          })
          .eq('id', targetId)
          .select()

        if (updateErr) throw updateErr
        savedRecord = updatedData?.[0] || { ...logPayload, id: targetId }
      } else {
        const { data: insertedData, error: insertErr } = await supabase
          .from('work_logs')
          .insert([{
            user_id: user.id,
            title: debriefTitle,
            type: 'project_work',
            description: formattedContent,
            date: logPayload.date
          }])
          .select()

        if (insertErr) {
          // If collision with unique constraint on date
          if (insertErr.code === '23505' || String(insertErr.message).includes('work_logs_user_date_key')) {
            const { data: rowOnDate } = await supabase
              .from('work_logs')
              .select('id, title')
              .eq('user_id', user.id)
              .eq('date', logPayload.date)
              .limit(1)

            if (rowOnDate && rowOnDate.length > 0 && String(rowOnDate[0].title).toLowerCase().startsWith('weekly debrief')) {
              const { data: upd, error: updErr } = await supabase
                .from('work_logs')
                .update({
                  title: debriefTitle,
                  type: 'project_work',
                  description: formattedContent,
                  updated_at: new Date().toISOString()
                })
                .eq('id', rowOnDate[0].id)
                .select()
              if (updErr) throw updErr
              savedRecord = upd?.[0]
            } else {
              throw new Error(`Unique constraint conflict on date (${logPayload.date}). Please run fix_weekly_debrief_and_work_logs.sql in Supabase SQL editor to drop work_logs_user_date_key so work sessions and debriefs can coexist on Sundays! Details: ${insertErr.message}`)
            }
          } else {
            throw insertErr
          }
        } else if (insertedData && insertedData.length > 0) {
          savedRecord = insertedData[0]
        } else {
          savedRecord = logPayload
        }
      }

      // 2. Deploy priority goals to tasks table for Next Week (due end of next week)
      const targetDateObj = new Date(targetDate)
      targetDateObj.setDate(targetDateObj.getDate() + 7)
      const nextWeekEndStr = getLocalDateStr(getEndOfWeek(targetDateObj))

      // Clean up stale pending weekly_goal tasks
      try {
        await supabase
          .from('tasks')
          .delete()
          .eq('user_id', user.id)
          .eq('category', 'weekly_goal')
          .eq('status', 'pending')
      } catch (delErr) {
        console.warn('Error clearing old weekly goals:', delErr)
      }

      for (const goalText of goalsList) {
        const cleanTitle = typeof goalText === 'string' ? goalText.trim() : String(goalText)
        if (!cleanTitle) continue
        const { error: taskErr } = await supabase.from('tasks').insert([{
          user_id: user.id,
          title: cleanTitle,
          type: 'custom',
          category: 'weekly_goal',
          due_date: nextWeekEndStr,
          status: 'pending',
          description: '[Weekly Goal] Priority for Next Week (from Weekly Debrief)'
        }])
        if (taskErr) console.warn('Task insert warning:', taskErr)
      }

      // 3. Immediately update local state & localStorage cache for 0ms delay
      const finalItem = savedRecord || { ...logPayload, id: 'debrief_' + Date.now() }
      setHistoryLogs(prev => {
        const next = [finalItem, ...prev.filter(l => l.id !== finalItem.id && l.title !== debriefTitle)]
        next.sort((a, b) => {
          const timeA = getDebriefSortTime(a)
          const timeB = getDebriefSortTime(b)
          if (timeA !== timeB) return timeB - timeA
          return (b.created_at || '').localeCompare(a.created_at || '')
        })
        if (typeof window !== 'undefined') {
          localStorage.setItem(`lokios_debrief_history_${user.id}`, JSON.stringify(next))
          const cacheKey = `lokios_dashboard_recon_${user.id}_${todayStr}`
          try {
            const existingCache = localStorage.getItem(cacheKey)
            const parsed = existingCache ? JSON.parse(existingCache) : {}
            parsed.latestDebrief = next[0]
            localStorage.setItem(cacheKey, JSON.stringify(parsed))
          } catch (errCache) {}
        }
        return next
      })

      // 4. Reset form only after successful persistence
      setWins('')
      setFails('')
      setNextGoal1('')
      setNextGoal2('')
      setNextGoal3('')
      setEditingDebriefLog(null)
      setShowDebriefHistory(true)
    } catch (err) {
      console.error('Failed to save debrief:', err)
      alert(`Failed to save Weekly Debrief: ${err.message || err.details || 'Unknown error'}\n\nYour inputs were preserved.`)
    } finally { 
      setSavingDebrief(false) 
    }
  }

  const isFullEntry = content.length >= 100 && mood

  return (
    <AppShell>
      <div className="max-w-4xl mx-auto space-y-6">

        {/* Header */}
        <header className="mb-6 flex items-start justify-between flex-wrap gap-4">
          <div>
            <h1 className="font-display text-4xl text-primary uppercase tracking-widest flex items-center gap-3">
              <BookOpen size={32} className="text-amber" />
              Journal
            </h1>
            <p className="font-mono text-muted text-sm uppercase tracking-widest mt-2">
              {activeTab === 'daily' ? 'Mental State & Reflection Archive' : `${dateRange.start} — ${dateRange.end}`}
            </p>
          </div>

          {/* Tab Switcher */}
          <div className="flex border border-border-color overflow-hidden">
            {[
              { id: 'daily', icon: BookOpen, label: 'DAILY LOG' },
              { id: 'weekly', icon: CalendarDays, label: 'WEEKLY DEBRIEF' }
            ].map(tab => (
              <button
                key={tab.id}
                onClick={() => setActiveTab(tab.id)}
                className="flex items-center gap-2 px-4 py-2 font-mono text-[10px] uppercase tracking-widest transition-all"
                style={{
                  background: activeTab === tab.id ? 'var(--accent-primary)' : 'transparent',
                  color: activeTab === tab.id ? '#0a0a0a' : 'var(--text-muted)',
                  borderRight: tab.id === 'daily' ? '1px solid var(--border-color)' : 'none'
                }}
              >
                <tab.icon size={12} />
                {tab.label}
              </button>
            ))}
          </div>
        </header>

        {/* ─── DAILY LOG TAB ─── */}
        {activeTab === 'daily' && (
          <motion.div initial={{ opacity: 0, y: 8 }} animate={{ opacity: 1, y: 0 }}>
            <div className="flex justify-end gap-2 mb-4">
              <button onClick={() => setShowHistory(!showHistory)} className="btn btn-ghost border border-border-color">
                {showHistory ? 'VIEW TODAY' : 'VIEW ARCHIVES'}
              </button>
            </div>

            {loading ? (
              <div className="flex-center py-12"><span className="typewriter-text text-amber">DECRYPTING ARCHIVES...</span></div>
            ) : !showHistory ? (
              <motion.div initial={{ opacity: 0, y: 10 }} animate={{ opacity: 1, y: 0 }}>
                <HudPanel label="NEW LOG">
                  <form onSubmit={handleSaveJournal} className="space-y-6">
                    <div>
                      <label className="font-mono text-xs text-muted uppercase tracking-widest mb-3 block">Log Date</label>
                      <input type="date" required value={entryDate} onChange={e => setEntryDate(e.target.value)}
                        style={{ colorScheme: 'dark' }}
                        className="w-full bg-bg-tertiary border border-border-color rounded p-3 font-mono text-primary text-sm focus:border-amber focus:outline-none transition-colors cursor-pointer" />
                    </div>
                    <div>
                      <label className="font-mono text-xs text-muted uppercase tracking-widest mb-3 block">Mental State Vector</label>
                      <div className="flex flex-wrap gap-3">
                        {MOODS.map(m => {
                          const isSelected = mood === m.id
                          return (
                            <button 
                              key={m.id} 
                              type="button" 
                              onClick={() => setMood(m.id)}
                              className="relative flex items-center justify-center w-14 h-14 rounded-2xl text-2xl border-2 transition-all active:scale-95 cursor-pointer"
                              style={{
                                borderColor: isSelected ? m.color : 'rgba(255, 255, 255, 0.1)',
                                backgroundColor: isSelected ? 'rgba(255, 255, 255, 0.12)' : 'rgba(15, 20, 30, 0.6)',
                                boxShadow: isSelected ? `0 0 16px ${m.color}88, inset 0 0 10px ${m.color}44` : 'none',
                                transform: isSelected ? 'scale(1.12)' : 'scale(1)',
                                opacity: isSelected ? 1 : 0.55
                              }}
                            >
                              <span>{m.emoji}</span>
                              {isSelected && (
                                <span 
                                  className="absolute -top-1 -right-1 w-4 h-4 rounded-full flex items-center justify-center text-[9px] font-bold text-black shadow"
                                  style={{ backgroundColor: m.color }}
                                >
                                  ✓
                                </span>
                              )}
                            </button>
                          )
                        })}
                      </div>
                    </div>
                    <div>
                      <label className="font-mono text-xs text-muted uppercase tracking-widest mb-3 block">
                        Reflection Log
                      </label>
                      <textarea value={content} onChange={e => setContent(e.target.value)}
                        placeholder="Document your thoughts, struggles, and victories today..."
                        className="input w-full min-h-[300px] p-4 resize-y font-mono text-sm leading-relaxed" />
                    </div>
                    <div className="flex-between border-t border-border-color pt-4">
                      <div className="flex items-center gap-2">
                        <Zap size={16} className="text-amber" />
                        <span className="font-mono text-xs text-muted">
                          ARCHIVE: <span className="text-primary font-bold">DAILY REFLECTION</span>
                        </span>
                      </div>
                      <button type="submit" disabled={saving} className="btn btn-primary btn-lg flex items-center gap-2">
                        <Save size={18} />{saving ? 'ENCRYPTING...' : 'SEAL LOG'}
                      </button>
                    </div>
                  </form>
                </HudPanel>
              </motion.div>
            ) : (
              <motion.div initial={{ opacity: 0, y: 10 }} animate={{ opacity: 1, y: 0 }} className="space-y-4">
                {entries.length === 0 ? (
                  <div className="p-8 text-center text-muted font-mono text-sm border border-border-color bg-tertiary">NO JOURNAL ARCHIVES FOUND.</div>
                ) : (
                  entries.map((entry, index) => {
                    const moodObj = MOODS.find(m => m.id === entry.mood) || MOODS[2]
                    const dayNumber = entries.length - index
                    return (
                      <HudPanel key={entry.id} className="cursor-pointer" onClick={() => setExpandedArchive(expandedArchive === entry.id ? null : entry.id)}>
                        <div className={`flex-between ${expandedArchive === entry.id ? 'mb-4 border-b border-border-color pb-2' : ''}`}>
                          <div className="flex items-center gap-3">
                            <span className="font-display text-lg text-primary tracking-widest">DAY {dayNumber}</span>
                            <span className="font-mono text-sm text-amber opacity-80">{entry.date}</span>
                          </div>
                          <div className="flex items-center justify-center text-base px-2.5 py-1 rounded border"
                            style={{ color: moodObj.color, borderColor: moodObj.color, backgroundColor: `${moodObj.color}15` }}>
                            <span>{moodObj.emoji}</span>
                          </div>
                        </div>
                        {expandedArchive === entry.id && (
                          <motion.div initial={{ height: 0, opacity: 0 }} animate={{ height: 'auto', opacity: 1 }}
                            className="font-mono text-secondary whitespace-pre-wrap text-sm">
                            {entry.content || entry.what_did_i_do || entry.reflection || entry.description || '—'}
                          </motion.div>
                        )}
                      </HudPanel>
                    )
                  })
                )}
              </motion.div>
            )}
          </motion.div>
        )}

        {/* ─── WEEKLY DEBRIEF TAB ─── */}
        {activeTab === 'weekly' && (
          <motion.div initial={{ opacity: 0, y: 8 }} animate={{ opacity: 1, y: 0 }} className="space-y-6">
            <div className="flex justify-end">
              <button onClick={() => setShowDebriefHistory(!showDebriefHistory)} className="btn btn-ghost border border-border-color">
                {showDebriefHistory ? 'VIEW THIS WEEK' : 'VIEW ARCHIVES'}
              </button>
            </div>

            {!showDebriefHistory ? (
              <>
                {/* Stats Row */}
                <div className="grid grid-cols-2 md:grid-cols-4 gap-4">
                  {[
                    { icon: Trophy, color: 'amber', label: 'XP Earned', val: loadingStats ? '...' : `+${stats.xp}` },
                    { icon: Target, color: 'success', label: 'Missions Done', val: loadingStats ? '...' : stats.missions },
                    { icon: CheckSquare, color: 'primary', label: 'Ops Completed', val: loadingStats ? '...' : stats.tasks },
                    { icon: Flame, color: 'info', label: 'Habits Done', val: loadingStats ? '...' : stats.habits }
                  ].map(s => (
                    <HudPanel key={s.label}>
                      <div className="flex items-center gap-4">
                        <div className={`p-3 bg-${s.color}/10 rounded-lg text-${s.color}`}>
                          <s.icon size={24} />
                        </div>
                        <div>
                          <span className="font-mono text-xs text-muted uppercase tracking-widest block">{s.label}</span>
                          <span className="font-display text-2xl text-primary">{s.val}</span>
                        </div>
                      </div>
                    </HudPanel>
                  ))}
                </div>

                {/* Form */}
                <HudPanel label="WEEKLY DEBRIEF">
                  {/* EDITING BANNER */}
                  {editingDebriefLog && (
                    <div className="p-3 bg-amber/15 border border-amber/40 rounded-xl flex items-center justify-between font-mono text-xs text-amber mb-4">
                      <span className="font-bold flex items-center gap-2">
                        <Pencil size={14} /> EDITING: {editingDebriefLog.title}
                      </span>
                      <button 
                        type="button" 
                        onClick={handleCancelEditDebrief} 
                        className="px-2.5 py-1 rounded bg-black/40 text-white hover:bg-black/60 font-bold text-[10px] uppercase border border-white/10"
                      >
                        CANCEL EDIT
                      </button>
                    </div>
                  )}

                  {/* WEEK NAVIGATION BAR */}
                  <div className="flex items-center justify-between gap-2 p-2 rounded-xl bg-black/40 border border-white/10 font-mono text-xs mb-4">
                    <button
                      type="button"
                      onClick={() => { setEditingDebriefLog(null); setDebriefWeekOffset(w => w - 1); }}
                      className="flex items-center gap-1 px-3 py-1 rounded-lg border border-white/15 bg-white/5 hover:bg-white/10 text-white font-bold text-[11px] uppercase transition-all"
                    >
                      <ChevronLeft size={13} />
                      <span>PREV WEEK</span>
                    </button>

                    <div className="flex items-center gap-2">
                      <CalendarDays size={14} className="text-amber" />
                      <span className="font-bold text-amber text-[11px] tracking-wider uppercase">
                        {dateRange.start} – {dateRange.end} {debriefWeekOffset === 0 ? '(THIS WEEK)' : ''}
                      </span>
                    </div>

                    <button
                      type="button"
                      onClick={() => { setEditingDebriefLog(null); setDebriefWeekOffset(w => Math.min(0, w + 1)); }}
                      disabled={debriefWeekOffset >= 0}
                      className="flex items-center gap-1 px-3 py-1 rounded-lg border border-white/15 bg-white/5 hover:bg-white/10 text-white font-bold text-[11px] uppercase transition-all disabled:opacity-30 disabled:cursor-not-allowed"
                    >
                      <span>NEXT WEEK</span>
                      <ChevronRight size={13} />
                    </button>
                  </div>

                  <form onSubmit={handleSaveDebrief} className="space-y-6">
                    {/* Section 1: Wins */}
                    <div>
                      <label className="font-mono text-xs uppercase tracking-widest mb-2 block text-success">What went well this week?</label>
                      <textarea value={wins} onChange={e => setWins(e.target.value)} placeholder="Document your victories, breakthroughs, and wins..."
                        className="input w-full min-h-[120px] resize-y font-mono text-sm leading-relaxed" />
                    </div>

                    {/* Section 2: Fails */}
                    <div>
                      <label className="font-mono text-xs uppercase tracking-widest mb-2 block text-danger">Bottlenecks & Fails</label>
                      <textarea value={fails} onChange={e => setFails(e.target.value)} placeholder="What held you back? Where did you fall short?"
                        className="input w-full min-h-[120px] resize-y font-mono text-sm leading-relaxed" />
                    </div>

                    {/* Section 3: 3 Goal Bars */}
                    <div className="space-y-3 pt-2">
                      <div className="flex items-center justify-between">
                        <label className="font-mono text-xs uppercase tracking-widest block text-info font-bold">Priorities for Next Week</label>
                        <span className="font-mono text-[9px] text-muted uppercase">MAX 20 WORDS PER GOAL</span>
                      </div>
                      <p className="font-mono text-xs text-muted">Enter up to 3 key goals for next week. These will deploy to your Command Center as finishable operations!</p>
                      
                      {[
                        { id: 1, val: nextGoal1, set: setNextGoal1, placeholder: "Goal #1 (e.g., Ship landing page redesign & test payment link)" },
                        { id: 2, val: nextGoal2, set: setNextGoal2, placeholder: "Goal #2 (e.g., Close 3 client proposals and conduct demo calls)" },
                        { id: 3, val: nextGoal3, set: setNextGoal3, placeholder: "Goal #3 (e.g., Complete 5 workouts and stick to 8h sleep target)" },
                      ].map((item) => {
                        const words = getWordCount(item.val)
                        return (
                          <div key={item.id} className="space-y-1">
                            <div className="flex items-center justify-between">
                              <span className="font-mono text-[10px] text-amber font-bold uppercase tracking-widest">PRIORITY GOAL #{item.id}</span>
                              <span className={`font-mono text-[9px] ${words >= 20 ? 'text-danger font-bold' : 'text-muted'}`}>({words}/20 words)</span>
                            </div>
                            <input 
                              type="text"
                              className="input w-full font-mono text-xs py-2 px-3 bg-bg-primary border border-border-color focus:border-amber rounded text-primary"
                              placeholder={item.placeholder}
                              value={item.val || ''}
                              onChange={e => item.set(e.target.value)}
                            />
                          </div>
                        )
                      })}
                    </div>
                    <div className="flex-between border-t border-border-color pt-4">
                      <div className="flex items-center gap-2">
                        <Zap size={16} className="text-amber" />
                        <span className="font-mono text-xs text-muted">PROTOCOL: <span className="text-primary font-bold">WEEKLY RETROSPECTIVE</span></span>
                      </div>
                      <button type="submit" disabled={savingDebrief} className="btn btn-primary btn-lg flex items-center gap-2">
                        <Save size={18} />{savingDebrief ? 'SAVING...' : (editingDebriefLog ? 'UPDATE DEBRIEF' : 'SEAL DEBRIEF')}
                      </button>
                    </div>
                  </form>
                </HudPanel>
              </>
            ) : (
              <div className="space-y-4">
                {historyLogs.length === 0 ? (
                  <div className="p-8 text-center text-muted font-mono text-sm border border-border-color">NO DEBRIEF ARCHIVES FOUND.</div>
                ) : (
                  historyLogs.map(log => (
                    <HudPanel key={log.id} className="cursor-pointer" onClick={() => setExpandedDebrief(expandedDebrief === log.id ? null : log.id)}>
                      <div className={`flex items-center justify-between gap-3 ${expandedDebrief === log.id ? 'mb-4 border-b border-border-color pb-2' : ''}`}>
                        <div>
                          <span className="font-display text-base text-primary tracking-widest block">{log.title}</span>
                          <span className="font-mono text-xs text-muted">{log.date}</span>
                        </div>
                        <button
                          type="button"
                          onClick={(e) => {
                            e.stopPropagation()
                            handleStartEditDebrief(log)
                          }}
                          className="flex items-center gap-1.5 px-3 py-1.5 rounded-lg bg-amber/15 border border-amber/40 hover:bg-amber/30 text-amber font-mono text-[10px] font-bold uppercase transition-all shrink-0"
                        >
                          <Pencil size={12} />
                          <span>EDIT DEBRIEF</span>
                        </button>
                      </div>
                      {expandedDebrief === log.id && (
                        <motion.div initial={{ height: 0, opacity: 0 }} animate={{ height: 'auto', opacity: 1 }}>
                          <RenderDebrief text={log.description} />
                        </motion.div>
                      )}
                    </HudPanel>
                  ))
                )}
              </div>
            )}
          </motion.div>
        )}
      </div>
    </AppShell>
  )
}

'use client'

import { useState, useEffect } from 'react'
import { useRouter } from 'next/navigation'
import { createClient } from '@/lib/supabase/client'
import { Shield, Mail, Lock, ArrowRight, Loader2 } from 'lucide-react'
import { motion } from 'framer-motion'
import TypewriterText from '@/components/ui/TypewriterText'

const AUTH_PILLARS = [
  { value: '1', label: 'Private console' },
  { value: '2', label: 'Focus tools' },
  { value: '3', label: 'Execution loops' },
]

export default function Login() {
  const [isLogin, setIsLogin] = useState(true)
  const [email, setEmail] = useState('')
  const [password, setPassword] = useState('')
  const [loading, setLoading] = useState(false)
  const [error, setError] = useState(null)
  const router = useRouter()

  useEffect(() => {
    // Check for auth error in URL
    const params = new URLSearchParams(window.location.search)
    if (params.get('error')) {
      setError('Authentication failed. Please try again.')
    }

    // Check if already logged in
    const checkUser = async () => {
      const supabase = createClient()
      const { data: { user } } = await supabase.auth.getUser()
      if (user) router.push('/dashboard')
    }
    checkUser()
  }, [router])

  const handleAuth = async (e) => {
    e.preventDefault()
    setLoading(true)
    setError(null)
    const supabase = createClient()

    try {
      if (isLogin) {
        const { error } = await supabase.auth.signInWithPassword({ email, password })
        if (error) throw error
        router.push('/dashboard')
      } else {
        const { error } = await supabase.auth.signUp({
          email,
          password,
          options: { data: { username: email.split('@')[0] } }
        })
        if (error) throw error
        // Auto sign-in logic depends on Supabase email confirmation settings
        // Currently the user has auto-confirm enabled, so they should be logged in
        router.push('/dashboard')
      }
    } catch (err) {
      setError(err.message)
    } finally {
      setLoading(false)
    }
  }

  const handleGoogleLogin = async () => {
    try {
      const supabase = createClient()
      const { error } = await supabase.auth.signInWithOAuth({
        provider: 'google',
        options: {
          redirectTo: `${window.location.origin}/auth/callback`
        }
      })
      if (error) throw error
    } catch (err) {
      setError(err.message)
    }
  }

  return (
    <div className="auth-shell">
      <div className="auth-grid">
        <motion.section
          className="auth-intro glass-panel-strong"
          initial={{ opacity: 0, y: 16 }}
          animate={{ opacity: 1, y: 0 }}
          transition={{ duration: 0.5 }}
        >
          <div>
            <p className="auth-kicker">Private command surface</p>
            <h1>ChiragOS</h1>
            <p className="auth-lede">
              A focused operating system for planning the day, protecting attention, and turning intent into execution.
            </p>
          </div>

          <div className="auth-metrics">
            {AUTH_PILLARS.map((item) => (
              <div key={item.label} className="auth-metric">
                <span className="auth-metric-value">0{item.value}</span>
                <span className="auth-metric-label">{item.label}</span>
              </div>
            ))}
          </div>

          <div className="auth-note">Focused by design. No extra noise.</div>
        </motion.section>

        <motion.div
          className="hud-panel hud-glow auth-card"
          initial={{ opacity: 0, scale: 0.96 }}
          animate={{ opacity: 1, scale: 1 }}
          transition={{ duration: 0.5, delay: 0.08 }}
        >
          <div className="scan-line" />

          <div className="auth-card-header">
            <div className="auth-card-icon">
              <Shield size={22} color="var(--accent-primary)" />
            </div>
            <div>
              <p className="auth-kicker">Secure entry</p>
              <h2 className="auth-card-title">Access the console</h2>
              <TypewriterText
                text="Initializing command center..."
                speed={42}
                className="auth-subtitle"
              />
            </div>
          </div>

          <div className="auth-tabs">
            <button
              onClick={() => { setIsLogin(true); setError(null); }}
              className={`auth-tab ${isLogin ? 'active' : ''}`}
              type="button"
            >
              Sign in
            </button>
            <button
              onClick={() => { setIsLogin(false); setError(null); }}
              className={`auth-tab ${!isLogin ? 'active' : ''}`}
              type="button"
            >
              Create account
            </button>
          </div>

          {error && (
            <div className="auth-error">
              [ERROR]: {error}
            </div>
          )}

          <form onSubmit={handleAuth} className="auth-form">
            <label className="auth-field">
              <Mail size={16} className="auth-field-icon" />
              <input
                type="email"
                placeholder="operator@email.com"
                className="input font-mono text-sm"
                value={email}
                onChange={(e) => setEmail(e.target.value)}
                required
              />
            </label>

            <label className="auth-field">
              <Lock size={16} className="auth-field-icon" />
              <input
                type="password"
                placeholder="access code"
                className="input font-mono text-sm"
                value={password}
                onChange={(e) => setPassword(e.target.value)}
                required
              />
            </label>

            <button type="submit" className="btn btn-primary btn-full auth-remote" disabled={loading}>
              {loading ? (
                <Loader2 size={18} className="animate-spin" />
              ) : (
                <>
                  {isLogin ? 'Initialize login' : 'Create profile'}
                  <ArrowRight size={16} />
                </>
              )}
            </button>
          </form>

          <div className="auth-divider">
            <span>Or continue with</span>
          </div>

          <button
            onClick={handleGoogleLogin}
            type="button"
            className="btn btn-secondary btn-full font-display tracking-wide"
          >
            Google OAuth
          </button>
        </motion.div>
      </div>
    </div>
  )
}

import { notFound } from 'next/navigation'
import { createClient } from '@/lib/supabase/server'
import { getRankForXp, calculateLevel } from '@/lib/utils/xp'

export async function generateMetadata({ params }) {
  const supabase = await createClient()
  const { data: profile } = await supabase.from('portfolio_summary').select('*').eq('public_portfolio_slug', params.slug).single()

  if (!profile) return { title: 'Not Found' }

  return {
    title: `${profile.full_name || profile.username}'s Portfolio`,
    description: profile.portfolio_headline,
  }
}

export default async function PublicPortfolio({ params }) {
  const supabase = await createClient()
  const { data: profile } = await supabase.from('portfolio_summary').select('*').eq('public_portfolio_slug', params.slug).single()

  if (!profile) {
    notFound()
  }

  // Fetch public portfolio data
  const [workRes, projectsRes, skillsRes] = await Promise.all([
    supabase.from('work_logs').select('*').eq('user_id', profile.id).eq('is_public', true).order('date', { ascending: false }),
    supabase.from('projects').select('*').eq('user_id', profile.id).eq('is_public', true).order('created_at', { ascending: false }),
    supabase.from('skills').select('*').eq('user_id', profile.id).eq('is_public', true).order('level', { ascending: false })
  ])

  const workLogs = workRes.data || []
  const projects = projectsRes.data || []
  const skills = skillsRes.data || []
  const rank = getRankForXp(profile.total_xp || 0)

  return (
    <div className="portfolio-public" style={{ minHeight: '100vh', background: 'var(--bg-primary)', color: 'var(--text-primary)', paddingBottom: 'var(--space-20)' }}>
      {/* Hero */}
      <header style={{ padding: 'var(--space-12) var(--space-6)', textAlign: 'center', borderBottom: '1px solid var(--border-color)', background: `linear-gradient(to bottom, ${rank.color}10, transparent)` }}>
        <div style={{ maxWidth: '800px', margin: '0 auto' }}>
          <div style={{ width: '120px', height: '120px', borderRadius: '50%', background: 'var(--bg-tertiary)', margin: '0 auto var(--space-6)', overflow: 'hidden' }}>
            {profile.avatar_url ? <img src={profile.avatar_url} alt="Avatar" style={{ width: '100%', height: '100%', objectFit: 'cover' }} /> : <span style={{ fontSize: '48px', lineHeight: '120px' }}>👤</span>}
          </div>
          <h1 style={{ fontSize: 'var(--text-4xl-size)', marginBottom: 'var(--space-2)' }}>{profile.full_name || profile.username}</h1>
          <p style={{ fontSize: 'var(--text-xl-size)', color: 'var(--text-secondary)', marginBottom: 'var(--space-4)' }}>{profile.portfolio_headline}</p>

          <div style={{ display: 'flex', justifyContent: 'center', gap: 'var(--space-4)', flexWrap: 'wrap' }}>
            <span className="badge" style={{ background: rank.color, color: '#fff', fontSize: 'var(--text-sm-size)', padding: 'var(--space-2) var(--space-4)' }}>{rank.icon} {rank.name} • Lvl {calculateLevel(profile.total_xp || 0)}</span>
          </div>
        </div>
      </header>

      <main className="page-container narrow" style={{ marginTop: 'var(--space-10)' }}>
        {/* About */}
        {profile.portfolio_about && (
          <section style={{ marginBottom: 'var(--space-12)' }}>
            <h2 style={{ fontSize: 'var(--text-2xl-size)', marginBottom: 'var(--space-4)', color: 'var(--text-primary)' }}>About</h2>
            <p style={{ fontSize: 'var(--text-lg-size)', color: 'var(--text-secondary)', whiteSpace: 'pre-wrap' }}>{profile.portfolio_about}</p>
          </section>
        )}

        {/* Skills */}
        {skills.length > 0 && (
          <section style={{ marginBottom: 'var(--space-12)' }}>
            <h2 style={{ fontSize: 'var(--text-2xl-size)', marginBottom: 'var(--space-6)', color: 'var(--text-primary)' }}>Skills</h2>
            <div className="grid-auto">
              {skills.map(skill => (
                <div key={skill.id} className="card card-flat" style={{ padding: 'var(--space-4)', display: 'flex', alignItems: 'center', gap: 'var(--space-4)' }}>
                  <div style={{ fontSize: '24px' }}>{skill.icon || '🎯'}</div>
                  <div style={{ flex: 1 }}>
                    <div style={{ fontWeight: 600 }}>{skill.name}</div>
                    <div style={{ fontSize: 'var(--text-xs)', color: 'var(--text-muted)' }}>{skill.category}</div>
                  </div>
                </div>
              ))}
            </div>
          </section>
        )}

        {/* Projects */}
        {projects.length > 0 && (
          <section style={{ marginBottom: 'var(--space-12)' }}>
            <h2 style={{ fontSize: 'var(--text-2xl-size)', marginBottom: 'var(--space-6)', color: 'var(--text-primary)' }}>Projects</h2>
            <div className="grid-2">
              {projects.map(proj => (
                <div key={proj.id} className="card" style={{ display: 'flex', flexDirection: 'column' }}>
                  <h3 style={{ fontSize: 'var(--text-xl-size)', marginBottom: 'var(--space-2)' }}>{proj.title}</h3>
                  <p style={{ color: 'var(--text-secondary)', marginBottom: 'var(--space-4)', flex: 1 }}>{proj.description || proj.tagline}</p>
                  <div style={{ display: 'flex', gap: 'var(--space-3)' }}>
                    {proj.live_url && <a href={proj.live_url} target="_blank" rel="noopener noreferrer" className="btn btn-primary btn-sm">Visit Site</a>}
                    {proj.github_url && <a href={proj.github_url} target="_blank" rel="noopener noreferrer" className="btn btn-secondary btn-sm">GitHub</a>}
                  </div>
                </div>
              ))}
            </div>
          </section>
        )}

        {/* Timeline */}
        {workLogs.length > 0 && (
          <section>
            <h2 style={{ fontSize: 'var(--text-2xl-size)', marginBottom: 'var(--space-6)', color: 'var(--text-primary)' }}>Timeline</h2>
            <div style={{ borderLeft: '2px solid var(--border-color)', marginLeft: 'var(--space-4)', paddingLeft: 'var(--space-6)', display: 'flex', flexDirection: 'column', gap: 'var(--space-8)' }}>
              {workLogs.map(log => (
                <div key={log.id} style={{ position: 'relative' }}>
                  <div style={{ position: 'absolute', width: '14px', height: '14px', borderRadius: '50%', background: 'var(--accent-primary)', left: 'calc(-var(--space-6) - 9px)', top: '6px' }}></div>
                  <div style={{ fontSize: 'var(--text-sm-size)', color: 'var(--accent-primary)', fontWeight: 600, marginBottom: 'var(--space-1)' }}>{new Date(log.date).toLocaleDateString(undefined, { month: 'long', year: 'numeric' })}</div>
                  <h3 style={{ fontSize: 'var(--text-lg-size)', marginBottom: 'var(--space-2)' }}>{log.title}</h3>
                  <p style={{ color: 'var(--text-secondary)' }}>{log.description}</p>
                </div>
              ))}
            </div>
          </section>
        )}
      </main>
    </div>
  )
}

'use client'

import { useState, useEffect, useMemo } from 'react'
import AppShell from '@/components/layout/AppShell'
import HudPanel from '@/components/ui/HudPanel'
import { getLocalDateStr, getDebriefSortTime } from '@/lib/utils/dates'
import { createClient } from '@/lib/supabase/client'
import { useAuth } from '@/lib/hooks/useAuth'
import { useProfile } from '@/lib/hooks/useProfile'
import { useOS } from '@/lib/context/OSContext'
import { calculateLevel, getRankForXp } from '@/lib/utils/xp'
import { motion, AnimatePresence } from 'framer-motion'
import { 
  Briefcase, Code, Terminal, Database, Shield, Plus, ExternalLink, 
  Image as ImageIcon, Link as LinkIcon, Edit2, Save, FileText, Clock, 
  ChevronDown, ChevronUp, Trash2, BookOpen, Star, Sparkles, Search, Filter, Book,
  Check, CheckSquare, Trophy, Printer, RefreshCw, Target, Flame
} from 'lucide-react'

export default function ProofOfWork() {
  const { user } = useAuth()
  const { profile } = useProfile()
  const { xp: { awardXP, deductXP } = {} } = useOS() || {}

  // Active tab: 'timeline' | 'reviews' | 'books' | 'projects' | 'resume'
  const [activeTab, setActiveTab] = useState('timeline')
  const [expandedReview, setExpandedReview] = useState(null)
  const [expandedLogId, setExpandedLogId] = useState(null)
  const [expandedBookId, setExpandedBookId] = useState(null)
  const [showAllResumeLogs, setShowAllResumeLogs] = useState(false)

  // Dynamic Level & Rank Calculations
  const userXp = profile?.total_xp || 0
  const dynamicLevel = calculateLevel(userXp)
  const dynamicRank = getRankForXp(userXp)

  // DATA STATES - declared before useMemo to prevent TDZ crash
  const [goals, setGoals] = useState([])

  const completedMissions = useMemo(() => {
    return goals.filter(g => g.status === 'completed' || g.completed_at)
  }, [goals])

  const ongoingMissions = useMemo(() => {
    return goals.filter(g => g.status !== 'completed' && !g.completed_at && g.status !== 'cancelled')
  }, [goals])

  // Executive Resume Bullet Point Parser (Strips raw markdown section headers)
  const parseResumeHighlights = (description) => {
    if (!description) return []
    const cleanText = description.replace(/\r\n/g, '\n')
    const highlights = []

    const isSectionHeader = (str) => {
      if (!str || str.trim().length < 4) return true
      const lower = str.toLowerCase().replace(/[^a-z0-9 ]/g, '').trim()
      if (
        lower === 'what went well' || 
        lower === 'priorities for next week' || 
        lower === 'bottlenecks  fails' || 
        lower === 'bottlenecks fails' || 
        lower === 'priorities'
      ) return true
      if (str.trim().startsWith('###')) return true
      return false
    }

    // Extract What Went Well / Achievements
    const wentWellMatch = cleanText.match(/###\s*What went well\??([\s\S]*?)(?=###|$)/i)
    if (wentWellMatch && wentWellMatch[1]) {
      const points = wentWellMatch[1]
        .split(/\n+/)
        .map(s => s.replace(/^###\s*/, '').replace(/^\d+[\.\)]\s*/, '').replace(/^[\-\*\•]\s*/, '').trim())
        .filter(s => !isSectionHeader(s))
      highlights.push(...points)
    }

    // Extract Priorities / Key Wins
    const prioritiesMatch = cleanText.match(/###\s*Priorities for Next Week([\s\S]*?)(?=###|$)/i)
    if (prioritiesMatch && prioritiesMatch[1]) {
      const points = prioritiesMatch[1]
        .split(/\n+/)
        .map(s => s.replace(/^###\s*/, '').replace(/^\d+[\.\)]\s*/, '').replace(/^[\-\*\•]\s*/, '').replace(/\[DONE\]/g, '').replace(/\[FAILED\]/g, '').trim())
        .filter(s => !isSectionHeader(s))
      highlights.push(...points)
    }

    // Fallback: If no markdown section headers found
    if (highlights.length === 0) {
      const cleanLines = cleanText
        .split(/\n+/)
        .map(s => s.replace(/^###\s*/, '').replace(/^\d+[\.\)]\s*/, '').replace(/^[\-\*\•]\s*/, '').trim())
        .filter(s => !isSectionHeader(s))
      return cleanLines.slice(0, 5)
    }

    return Array.from(new Set(highlights)).filter(s => !isSectionHeader(s)).slice(0, 6)
  }

  useEffect(() => {
    const params = new URLSearchParams(window.location.search)
    if (params.get('tab')) {
      setActiveTab(params.get('tab'))
    }
  }, [])

  // DATA STATES
  const [logs, setLogs] = useState([])
  const [projects, setProjects] = useState([])
  const [books, setBooks] = useState([])
  // (goals state already declared above)
  const [loading, setLoading] = useState(true)

  const [editingId, setEditingId] = useState(null)
  const [newMediaUrl, setNewMediaUrl] = useState('')

  // Edit Log State
  const [editingLogId, setEditingLogId] = useState(null)
  const [editLogForm, setEditLogForm] = useState({})

  // New Log Form State
  const [showAddLog, setShowAddLog] = useState(false)
  const [newLog, setNewLog] = useState({ title: '', description: '', type: 'project_work', duration: '', duration_unit: 'hours', mediaUrl: '' })

  // New Project Form State
  const [showAddProject, setShowAddProject] = useState(false)
  const [newProj, setNewProj] = useState({ title: '', description: '', status: 'active', tech_stack: '' })

  // BOOKS COMPLETED STATE
  const [showAddBook, setShowAddBook] = useState(false)
  const [bookSearch, setBookSearch] = useState('')
  const [bookCategoryFilter, setBookCategoryFilter] = useState('all')
  const [xpToast, setXpToast] = useState(null)

  const [newBook, setNewBook] = useState({
    title: '',
    author: '',
    category: 'Business',
    rating: 5,
    date_completed: getLocalDateStr(),
    cover_url: '',
    takeaways: ''
  })

  const [editingBookId, setEditingBookId] = useState(null)
  const [editBookForm, setEditBookForm] = useState({})

  useEffect(() => {
    if (!user) return
    fetchData()
  }, [user])

  const fetchData = async () => {
    const supabase = createClient()
    try {
      const [logsRes, workHoursRes, projRes, booksRes, goalsRes] = await Promise.all([
        supabase.from('work_logs').select('*').eq('user_id', user.id).order('date', { ascending: false }),
        supabase.from('work_hours_logs').select('*').eq('user_id', user.id).order('date', { ascending: false }),
        supabase.from('projects').select('*').eq('user_id', user.id).order('created_at', { ascending: false }),
        supabase.from('books_completed').select('*').eq('user_id', user.id).order('date_completed', { ascending: false }),
        supabase.from('goals').select('*').eq('user_id', user.id).order('created_at', { ascending: false })
      ])

      let combinedLogs = logsRes.data || []
      if (workHoursRes.data && workHoursRes.data.length > 0) {
        const mappedHours = workHoursRes.data.map(h => ({
          id: `wh_${h.id}`,
          title: `Work Session (${h.work_type || 'General'}: ${h.hours}h)`,
          description: h.notes || `Logged ${h.hours}h focused work. Focused: ${h.focused_hours || h.hours}h, Beyond Tatva: ${h.beyond_tatva_hours || 0}h.`,
          type: 'project_work',
          date: h.date,
          created_at: h.created_at
        }))
        
        const map = new Map()
        combinedLogs.forEach(l => map.set(l.id, l))
        mappedHours.forEach(h => {
          if (!map.has(h.id)) map.set(h.id, h)
        })
        combinedLogs = Array.from(map.values()).sort((a, b) => (b.date || '').localeCompare(a.date || ''))
      }

      setLogs(combinedLogs)
      if (projRes.data) setProjects(projRes.data)
      if (goalsRes.data) setGoals(goalsRes.data)
      
      if (booksRes.data) {
        setBooks(booksRes.data)
        if (typeof window !== 'undefined') localStorage.setItem('lokios_books_completed_cache', JSON.stringify(booksRes.data))
      } else if (typeof window !== 'undefined') {
        const cached = localStorage.getItem('lokios_books_completed_cache')
        if (cached) setBooks(JSON.parse(cached))
      }
    } catch (err) {
      if (typeof window !== 'undefined') {
        const cached = localStorage.getItem('lokios_books_completed_cache')
        if (cached) setBooks(JSON.parse(cached))
      }
    } finally {
      setLoading(false)
    }
  }

  // LOG HANDLERS
  const startEditLog = (log) => {
    setEditingLogId(log.id)
    setEditLogForm({
      title: log.title || '',
      type: log.type || 'other',
      description: log.description || '',
      duration: log.duration_hours || '',
      duration_unit: 'hours'
    })
  }

  const saveEditLog = async (id) => {
    const supabase = createClient()
    await supabase.from('work_logs').update({
      title: editLogForm.title,
      type: editLogForm.type,
      description: editLogForm.description,
      duration_hours: editLogForm.duration ? parseFloat(editLogForm.duration) * (editLogForm.duration_unit === 'days' ? 24 : 1) : null
    }).eq('id', id)
    setEditingLogId(null)
    fetchData()
  }

  const handleDeleteLog = async (id) => {
    if (confirm("Are you sure you want to delete this work log?")) {
      const supabase = createClient()
      await supabase.from('work_logs').delete().eq('id', id)
      setLogs(prev => prev.filter(l => l.id !== id))
      deductXP(2, 'work_log', id, 'Deleted Work Log')
    }
  }

  const handleAddMedia = async (logId, currentMedia) => {
    if (!newMediaUrl.trim()) return
    const supabase = createClient()
    const updatedMedia = [...(currentMedia || []), newMediaUrl]
    
    const { error } = await supabase.from('work_logs').update({ media_urls: updatedMedia }).eq('id', logId)
    if (!error) {
      setLogs(prev => prev.map(l => l.id === logId ? { ...l, media_urls: updatedMedia } : l))
      setNewMediaUrl('')
      setEditingId(null)
    }
  }

  const handleCreateLog = async (e) => {
    e.preventDefault()
    if (!newLog.title.trim()) return
    const supabase = createClient()
    const parsedDuration = newLog.duration ? parseFloat(newLog.duration) : null
    const duration_hours = parsedDuration ? (newLog.duration_unit === 'days' ? parsedDuration * 24 : parsedDuration) : null

    const payload = {
      user_id: user.id,
      title: newLog.title,
      description: newLog.description,
      type: newLog.type,
      duration_hours: duration_hours,
      date: getLocalDateStr()
    }

    if (newLog.mediaUrl.trim()) {
      payload.media_urls = [newLog.mediaUrl.trim()]
    }

    const { data, error } = await supabase.from('work_logs').insert([payload]).select()
    
    if (error) {
      alert(`UPLOAD FAILED: ${error.message}\n\nPlease let the AI know what this error says!`)
      return
    }

    if (data) {
      setLogs([data[0], ...logs])
      setShowAddLog(false)
      setNewLog({ title: '', description: '', type: 'project_work', duration: '', duration_unit: 'hours', mediaUrl: '' })
    }
  }

  const [editingProjectId, setEditingProjectId] = useState(null)
  const [editProjForm, setEditProjForm] = useState({})

  const handleCreateProject = async (e) => {
    e.preventDefault()
    if (!newProj.title.trim()) return
    const supabase = createClient()
    const { data, error } = await supabase.from('projects').insert([{
      user_id: user.id,
      title: newProj.title,
      description: newProj.description,
      status: newProj.status,
      tech_stack: newProj.tech_stack.split(',').map(s => s.trim()).filter(Boolean)
    }]).select()
    
    if (data) {
      setProjects([data[0], ...projects])
      setShowAddProject(false)
      setNewProj({ title: '', description: '', status: 'active', tech_stack: '' })
    }
  }

  const startEditProject = (proj) => {
    setEditingProjectId(proj.id)
    setEditProjForm({
      title: proj.title || '',
      description: proj.description || '',
      status: proj.status || 'active',
      tech_stack: Array.isArray(proj.tech_stack) ? proj.tech_stack.join(', ') : (proj.tech_stack || '')
    })
  }

  const saveEditProject = async (id) => {
    const supabase = createClient()
    const updatedStack = (editProjForm.tech_stack || '').split(',').map(s => s.trim()).filter(Boolean)
    const payload = {
      title: editProjForm.title,
      description: editProjForm.description,
      status: editProjForm.status,
      tech_stack: updatedStack
    }

    await supabase.from('projects').update(payload).eq('id', id)
    setProjects(prev => prev.map(p => p.id === id ? { ...p, ...payload } : p))
    setEditingProjectId(null)
  }

  const handleDeleteProject = async (id, title) => {
    if (confirm(`Are you sure you want to delete project "${title || 'this project'}"?`)) {
      const supabase = createClient()
      await supabase.from('projects').delete().eq('id', id)
      setProjects(prev => prev.filter(p => p.id !== id))
    }
  }

  // ----------------------------------------------------
  // BOOK HANDLERS (+10 XP REWARD PER COMPLETED BOOK)
  // ----------------------------------------------------
  const handleCreateBook = async (e) => {
    e.preventDefault()
    if (!newBook.title.trim() || !user) return

    const payload = {
      user_id: user.id,
      title: newBook.title.trim(),
      author: newBook.author.trim() || 'Unknown Author',
      category: newBook.category || 'Business',
      rating: parseInt(newBook.rating) || 5,
      date_completed: newBook.date_completed || getLocalDateStr(),
      cover_url: newBook.cover_url.trim() || '',
      takeaways: newBook.takeaways.trim() || ''
    }

    const updated = [payload, ...books].sort((a, b) => (b.date_completed || '').localeCompare(a.date_completed || ''))
    setBooks(updated)
    if (typeof window !== 'undefined') localStorage.setItem('lokios_books_completed_cache', JSON.stringify(updated))

    try {
      const supabase = createClient()
      await supabase.from('books_completed').insert([payload])
    } catch (err) {}

    setXpToast(`\u2713 Book Logged: "${payload.title}"`)
    setTimeout(() => setXpToast(null), 3500)

    setShowAddBook(false)
    setNewBook({
      title: '',
      author: '',
      category: 'Business',
      rating: 5,
      date_completed: getLocalDateStr(),
      cover_url: '',
      takeaways: ''
    })
  }

  const startEditBook = (book) => {
    setEditingBookId(book.id || book.title)
    setEditBookForm({
      title: book.title || '',
      author: book.author || '',
      category: book.category || 'Business',
      rating: book.rating || 5,
      date_completed: book.date_completed || getLocalDateStr(),
      cover_url: book.cover_url || '',
      takeaways: book.takeaways || ''
    })
  }

  const saveEditBook = async (bookId) => {
    const updatedBooks = books.map(b => {
      if ((b.id && b.id === bookId) || b.title === editBookForm.title) {
        return { ...b, ...editBookForm }
      }
      return b
    })

    setBooks(updatedBooks)
    if (typeof window !== 'undefined') localStorage.setItem('lokios_books_completed_cache', JSON.stringify(updatedBooks))

    try {
      const supabase = createClient()
      if (bookId) {
        await supabase.from('books_completed').update(editBookForm).eq('id', bookId)
      }
    } catch (err) {}

    setEditingBookId(null)
  }

  const handleDeleteBook = async (bookId, title) => {
    if (confirm(`Are you sure you want to remove "${title}" from your completed books archive?`)) {
      const filtered = books.filter(b => (b.id ? b.id !== bookId : b.title !== title))
      setBooks(filtered)
      if (typeof window !== 'undefined') localStorage.setItem('lokios_books_completed_cache', JSON.stringify(filtered))

      try {
        if (bookId) {
          const supabase = createClient()
          await supabase.from('books_completed').delete().eq('id', bookId)
        }
      } catch (err) {}

      setXpToast(`Book Removed: "${title}"`)
      setTimeout(() => setXpToast(null), 3500)
    }
  }

  // Filtered books
  const filteredBooks = useMemo(() => {
    return books.filter(b => {
      const matchesSearch = (b.title || '').toLowerCase().includes(bookSearch.toLowerCase()) ||
                            (b.author || '').toLowerCase().includes(bookSearch.toLowerCase()) ||
                            (b.takeaways || '').toLowerCase().includes(bookSearch.toLowerCase())
      const matchesCategory = bookCategoryFilter === 'all' || (b.category || 'Business').toLowerCase() === bookCategoryFilter.toLowerCase()
      return matchesSearch && matchesCategory
    })
  }, [books, bookSearch, bookCategoryFilter])

  // Book stats
  const avgBookRating = useMemo(() => {
    if (books.length === 0) return '0.0'
    const sum = books.reduce((acc, b) => acc + (parseInt(b.rating) || 5), 0)
    return (sum / books.length).toFixed(1)
  }, [books])

  if (loading) return (
    <AppShell>
      <div className="flex-center h-full flex-col gap-2">
        <span className="typewriter-text">ACCESSING ARCHIVES...</span>
        <span className="font-mono text-xs text-cyan-400 font-bold tracking-widest uppercase animate-pulse flex items-center gap-1.5">
          <span>❄️</span> WINTER IS COMING <span>❄️</span>
        </span>
      </div>
    </AppShell>
  )

  return (
    <AppShell>
      {/* Floating XP Toast */}
      <AnimatePresence>
        {xpToast && (
          <motion.div
            initial={{ opacity: 0, y: -20 }}
            animate={{ opacity: 1, y: 0 }}
            exit={{ opacity: 0, y: -20 }}
            className="fixed top-4 right-4 sm:top-6 sm:right-6 z-[99999] bg-amber text-black font-mono font-bold text-xs px-4 py-2 rounded-xl shadow-2xl flex items-center gap-2 border border-amber/40"
          >
            <Sparkles size={15} />
            <span>{xpToast}</span>
          </motion.div>
        )}
      </AnimatePresence>

      <div className="page-container max-w-5xl">
        <header className="page-header flex-between flex-wrap gap-4">
          <div>
            <h1 className="page-title flex items-center gap-3"><Terminal className="text-amber" /> PORTFOLIO ENGINE</h1>
            <p className="page-subtitle">Proof of work, books completed, project history, and auto-generated resume.</p>
          </div>
        </header>

        {/* TABS */}
        <div className="tab-list mb-6">
          <button className={`tab-item ${activeTab === 'timeline' ? 'active tab-active' : ''}`} onClick={() => setActiveTab('timeline')}>
            TIMELINE LOGS
          </button>
          <button className={`tab-item ${activeTab === 'reviews' ? 'active tab-active' : ''}`} onClick={() => setActiveTab('reviews')}>
            WEEKLY REVIEWS
          </button>
          <button className={`tab-item ${activeTab === 'books' ? 'active tab-active' : ''}`} onClick={() => setActiveTab('books')}>
            BOOKS COMPLETED ({books.length})
          </button>
          <button className={`tab-item ${activeTab === 'projects' ? 'active tab-active' : ''}`} onClick={() => setActiveTab('projects')}>
            PROJECTS
          </button>
          <button className={`tab-item ${activeTab === 'resume' ? 'active tab-active' : ''}`} onClick={() => setActiveTab('resume')}>
            RESUME (AUTO-GEN)
          </button>
        </div>

        {/* TIMELINE TAB */}
        {activeTab === 'timeline' && (
          <div className="flex-col gap-6">
            <div className="flex justify-end">
              <button className="btn btn-primary btn-sm flex items-center gap-2" onClick={() => setShowAddLog(!showAddLog)}>
                <Plus size={16} /> ADD LOG
              </button>
            </div>

            <AnimatePresence>
              {showAddLog && (
                <motion.div initial={{ opacity: 0, height: 0 }} animate={{ opacity: 1, height: 'auto' }} exit={{ opacity: 0, height: 0 }} className="overflow-hidden">
                  <HudPanel label="NEW WORK LOG" className="border-amber mb-6">
                    <form onSubmit={handleCreateLog} className="grid grid-cols-1 md:grid-cols-2 gap-4">
                      <div>
                        <label className="font-mono text-xs text-muted mb-1 block">TITLE</label>
                        <input type="text" className="input font-mono text-sm" value={newLog.title} onChange={e => setNewLog({...newLog, title: e.target.value})} required />
                      </div>
                      <div>
                        <label className="font-mono text-xs text-muted mb-1 block">TYPE</label>
                        <select className="select font-mono text-sm" value={newLog.type} onChange={e => setNewLog({...newLog, type: e.target.value})}>
                          <option value="project_work">PROJECT WORK</option>
                          <option value="content">CONTENT CREATION</option>
                          <option value="meeting">MEETING / SALES</option>
                          <option value="learning">LEARNING</option>
                          <option value="other">OTHER</option>
                        </select>
                      </div>
                      <div className="md:col-span-2">
                        <label className="font-mono text-xs text-muted mb-1 block">DESCRIPTION</label>
                        <textarea className="textarea font-mono text-sm h-20" value={newLog.description} onChange={e => setNewLog({...newLog, description: e.target.value})} />
                      </div>
                      <div>
                        <label className="font-mono text-xs text-muted mb-1 block">DURATION</label>
                        <div className="flex gap-2">
                          <input type="text" inputMode="decimal" className="input font-mono text-sm" style={{ flex: 1, minWidth: '60px' }} value={newLog.duration} onChange={e => setNewLog({...newLog, duration: e.target.value})} placeholder="0" />
                          <select className="select font-mono text-sm" style={{ width: '120px', flexShrink: 0 }} value={newLog.duration_unit} onChange={e => setNewLog({...newLog, duration_unit: e.target.value})}>
                            <option value="hours">HOURS</option>
                            <option value="days">DAYS</option>
                          </select>
                        </div>
                      </div>
                      <div>
                        <label className="font-mono text-xs text-muted mb-1 block">ATTACH LINK / IMAGE URL</label>
                        <input type="url" className="input font-mono text-sm" value={newLog.mediaUrl} onChange={e => setNewLog({...newLog, mediaUrl: e.target.value})} placeholder="https://..." />
                      </div>
                      <div className="flex items-end justify-end md:col-span-2 mt-2">
                        <button type="submit" className="btn btn-primary w-full md:w-auto">SAVE LOG</button>
                      </div>
                    </form>
                  </HudPanel>
                </motion.div>
              )}
            </AnimatePresence>

            <div className="flex-col gap-0 border-l border-border-strong ml-4 pl-6 relative">
              {logs.filter(l => !l.title?.startsWith('Weekly Debrief')).map((log) => (
                <div key={log.id} className="relative pb-8 group">
                  <div className="absolute -left-[29px] top-1 w-3 h-3 rounded-full bg-border-color border border-border-strong group-hover:bg-amber transition-colors z-10" />
                  
                  <div className="bg-tertiary border border-border-color p-4 hover:border-amber transition-colors">
                    {editingLogId === log.id ? (
                      <div className="flex-col gap-3">
                        <input type="text" className="input font-mono text-sm py-1" value={editLogForm.title} onChange={e=>setEditLogForm({...editLogForm, title: e.target.value})} />
                        <select className="select font-mono text-sm py-1" value={editLogForm.type} onChange={e=>setEditLogForm({...editLogForm, type: e.target.value})}>
                          <option value="project_work">PROJECT WORK</option>
                          <option value="content">CONTENT CREATION</option>
                          <option value="meeting">MEETING / SALES</option>
                          <option value="learning">LEARNING</option>
                          <option value="other">OTHER</option>
                        </select>
                        <textarea className="textarea font-mono text-sm py-1" value={editLogForm.description} onChange={e=>setEditLogForm({...editLogForm, description: e.target.value})} rows={2} />
                        <div className="flex gap-2">
                          <input type="text" inputMode="decimal" className="input font-mono text-sm py-1" style={{ flex: 1, minWidth: '60px' }} value={editLogForm.duration} onChange={e => setEditLogForm({...editLogForm, duration: e.target.value})} placeholder="Duration" />
                          <select className="select font-mono text-sm py-1" style={{ width: '120px', flexShrink: 0 }} value={editLogForm.duration_unit} onChange={e => setEditLogForm({...editLogForm, duration_unit: e.target.value})}>
                            <option value="hours">HOURS</option>
                            <option value="days">DAYS</option>
                          </select>
                        </div>
                        <div className="flex justify-end gap-2 mt-2">
                          <button onClick={() => saveEditLog(log.id)} className="btn btn-primary btn-sm">SAVE</button>
                          <button onClick={() => setEditingLogId(null)} className="btn btn-ghost btn-sm">CANCEL</button>
                        </div>
                      </div>
                    ) : (
                      <>
                        <div 
                          onClick={() => setExpandedLogId(expandedLogId === log.id ? null : log.id)}
                          className="cursor-pointer select-none"
                        >
                          <div className="flex-between mb-2">
                            <span className="font-mono text-xs text-amber font-semibold">{String(log.date || '')}</span>
                            <span className="badge">{String(log.type || 'OTHER').replace('_', ' ').toUpperCase()}</span>
                          </div>
                          
                          <div className="flex items-center justify-between gap-3">
                            <h3 className="font-display text-xl uppercase tracking-wider text-primary break-words flex-1">{log.title}</h3>
                            <button type="button" className="p-1 text-muted hover:text-primary transition-colors shrink-0">
                              {expandedLogId === log.id ? <ChevronUp size={18} /> : <ChevronDown size={18} />}
                            </button>
                          </div>

                          <div className="font-mono text-[10px] text-muted flex items-center gap-3 mt-2">
                            <span className="flex items-center gap-1">
                              <Clock size={10} />
                              {log.duration_hours ? (log.duration_hours >= 24 && log.duration_hours % 24 === 0 ? `${log.duration_hours / 24} DAYS` : `${log.duration_hours} HOURS`) : 'NO DURATION LOGGED'}
                            </span>
                            {Array.isArray(log.media_urls) && log.media_urls.length > 0 && (
                              <span className="text-amber font-semibold">[{log.media_urls.length} PROOF ATTACHED]</span>
                            )}
                          </div>
                        </div>

                        {/* Expanded Accordion */}
                        <AnimatePresence>
                          {expandedLogId === log.id && (
                            <motion.div initial={{ height: 0, opacity: 0 }} animate={{ height: 'auto', opacity: 1 }} exit={{ height: 0, opacity: 0 }} className="overflow-hidden">
                              <div className="mt-4 pt-3 border-t border-border-color flex flex-col gap-3 font-mono text-xs">
                                {log.description && (
                                  <p className="text-secondary whitespace-pre-wrap leading-relaxed">{log.description}</p>
                                )}
                                
                                {Array.isArray(log.media_urls) && log.media_urls.length > 0 && (
                                  <div className="flex flex-wrap gap-2 mt-1">
                                    {log.media_urls.map((url, idx) => (
                                      <a key={idx} href={url} target="_blank" rel="noopener noreferrer" className="flex items-center gap-1 font-mono text-[10px] text-amber hover:text-primary transition-colors bg-bg-primary border border-amber/40 px-2 py-1 rounded">
                                        <ExternalLink size={10} /> PROOF {idx + 1}
                                      </a>
                                    ))}
                                  </div>
                                )}

                                <div className="flex justify-between items-center border-t border-border-color/60 pt-3 mt-2">
                                  <div className="flex gap-3">
                                    <button onClick={() => startEditLog(log)} className="font-mono text-[10px] text-muted hover:text-amber flex items-center gap-1">
                                      <Edit2 size={10} /> EDIT LOG
                                    </button>
                                    <button onClick={() => setEditingId(editingId === log.id ? null : log.id)} className="font-mono text-[10px] text-muted hover:text-primary flex items-center gap-1">
                                      <Plus size={10} /> ADD PROOF
                                    </button>
                                  </div>
                                  <button onClick={() => handleDeleteLog(log.id)} className="font-mono text-[10px] text-danger hover:text-danger/80 flex items-center gap-1">
                                    <Trash2 size={10} /> DELETE
                                  </button>
                                </div>

                                {editingId === log.id && (
                                  <div className="mt-2 flex gap-2">
                                    <input type="url" placeholder="https://..." className="input font-mono text-xs flex-1 py-1" value={newMediaUrl} onChange={e => setNewMediaUrl(e.target.value)} />
                                    <button onClick={() => handleAddMedia(log.id, log.media_urls)} className="btn btn-primary btn-sm flex items-center gap-1">
                                      <Save size={12} /> SAVE
                                    </button>
                                  </div>
                                )}
                              </div>
                            </motion.div>
                          )}
                        </AnimatePresence>
                      </>
                    )}
                  </div>
                </div>
              ))}
              {logs.filter(l => !l.title?.startsWith('Weekly Debrief')).length === 0 && <div className="font-mono text-sm text-muted py-8">NO WORK LOGS ARCHIVED.</div>}
            </div>
          </div>
        )}

        {/* WEEKLY REVIEWS TAB */}
        {activeTab === 'reviews' && (
          <div className="flex-col gap-6">
            <div className="flex-col gap-0 border-l border-border-strong ml-4 pl-6 relative">
              {logs.filter(l => l.title?.startsWith('Weekly Debrief')).sort((a, b) => getDebriefSortTime(b) - getDebriefSortTime(a)).map((log, idx, arr) => (
                <div key={log.id} className="relative pb-8 group">
                  <div className="absolute -left-[29px] top-1 w-3 h-3 rounded-full bg-border-color border border-border-strong group-hover:bg-amber transition-colors z-10" />
                  
                  <div className="bg-tertiary border border-border-color p-4 hover:border-amber transition-colors cursor-pointer" onClick={() => setExpandedReview(expandedReview === log.id ? null : log.id)}>
                    <div className="flex-between mb-2">
                      <span className="font-mono text-xs text-amber">{String(log.date || '')}</span>
                      <span className="badge badge-amber">WEEKLY DEBRIEF</span>
                    </div>
                    
                    <h3 className="font-display text-xl uppercase tracking-wider text-primary mb-0">WEEK {arr.length - idx}</h3>
                    
                    {expandedReview === log.id && (
                      <motion.div initial={{ height: 0, opacity: 0 }} animate={{ height: 'auto', opacity: 1 }} className="mt-4 border-t border-border-color pt-4">
                        <h4 className="font-display text-lg uppercase tracking-wider text-secondary mb-4">{log.title}</h4>
                        {log.description && (
                          <div className="prose prose-invert prose-sm max-w-none font-mono text-sm text-secondary">
                            {log.description.split('\n').map((line, i) => {
                              if (line.startsWith('### ')) {
                                return <h4 key={i} className="text-amber mt-4 mb-2 font-display tracking-widest uppercase">{line.replace('### ', '')}</h4>
                              }
                              return <div key={i} className="min-h-[1.5em]">{line}</div>
                            })}
                          </div>
                        )}
                      </motion.div>
                    )}
                  </div>
                </div>
              ))}
              {logs.filter(l => l.title?.startsWith('Weekly Debrief')).length === 0 && <div className="font-mono text-sm text-muted py-8">NO WEEKLY REVIEWS ARCHIVED YET.</div>}
            </div>
          </div>
        )}

        {/* ========================================================================= */}
        {/* BOOKS COMPLETED TAB */}
        {/* ========================================================================= */}
        {activeTab === 'books' && (
          <div className="space-y-6">
            {/* STATS HEADER */}
            <div className="grid grid-cols-1 sm:grid-cols-3 gap-3">
              <HudPanel className="p-4 flex items-center justify-between">
                <div>
                  <span className="font-mono text-[10px] text-muted uppercase block">BOOKS READ</span>
                  <span className="font-display text-2xl text-amber font-bold">{books.length}</span>
                </div>
                <BookOpen size={24} className="text-amber opacity-60" />
              </HudPanel>

              <HudPanel className="p-4 flex items-center justify-between">
                <div>
                  <span className="font-mono text-[10px] text-muted uppercase block">AVG RATING</span>
                  <span className="font-display text-2xl text-warning font-bold">{avgBookRating} ⭐</span>
                </div>
                <Star size={24} className="text-warning opacity-60" />
              </HudPanel>

              <HudPanel className="p-4 flex items-center justify-between">
                <div>
                  <span className="font-mono text-[10px] text-muted uppercase block">KNOWLEDGE ARCHIVE</span>
                  <span className="font-display text-2xl text-success font-bold">{books.length} READ</span>
                </div>
                <Sparkles size={24} className="text-success opacity-60" />
              </HudPanel>
            </div>

            {/* CONTROLS BAR: SEARCH, FILTER, ADD BOOK */}
            <div className="flex flex-col sm:flex-row items-stretch sm:items-center justify-between gap-3 p-3 bg-tertiary border border-border-color rounded-xl">
              <div className="flex flex-1 items-center gap-2 bg-secondary border border-border-color rounded-lg px-3 py-1.5" style={{ background: '#121520' }}>
                <Search size={14} className="text-muted flex-shrink-0" />
                <input
                  type="text"
                  placeholder="Search books, authors, notes..."
                  value={bookSearch}
                  onChange={(e) => setBookSearch(e.target.value)}
                  className="w-full bg-transparent font-mono text-xs text-primary focus:outline-none placeholder:text-muted"
                />
              </div>

              <div className="flex items-center gap-2">
                <select
                  value={bookCategoryFilter}
                  onChange={(e) => setBookCategoryFilter(e.target.value)}
                  className="bg-secondary border border-border-color rounded-lg px-3 py-1.5 font-mono text-xs text-primary focus:outline-none"
                  style={{ background: '#121520', color: '#fff' }}
                >
                  <option value="all">ALL GENRES</option>
                  <option value="Business">Business / Startup</option>
                  <option value="Philosophy">Philosophy / Mindset</option>
                  <option value="Technical">Technical / Skills</option>
                  <option value="Biography">Biography / History</option>
                  <option value="Fiction">Fiction</option>
                  <option value="Other">Other</option>
                </select>

                <button
                  type="button"
                  onClick={() => setShowAddBook(!showAddBook)}
                  className="flex items-center justify-center gap-2 px-4 py-2 bg-amber hover:bg-amber-hover text-black font-mono text-xs font-bold uppercase rounded-lg shadow-md transition-all shrink-0 active:scale-95"
                >
                  <Plus size={16} />
                  <span>ADD BOOK</span>
                </button>
              </div>
            </div>

            {/* ADD BOOK FORM MODAL */}
            <AnimatePresence>
              {showAddBook && (
                <motion.div initial={{ opacity: 0, height: 0 }} animate={{ opacity: 1, height: 'auto' }} exit={{ opacity: 0, height: 0 }} className="overflow-hidden">
                  <HudPanel label="LOG COMPLETED BOOK" className="border-amber p-5 space-y-4">
                    <form onSubmit={handleCreateBook} className="space-y-4">
                      <div className="grid grid-cols-1 sm:grid-cols-2 gap-4">
                        <div>
                          <label className="font-mono text-xs text-amber uppercase font-bold block mb-1">Book Title *</label>
                          <input
                            type="text"
                            required
                            placeholder="e.g. Atomic Habits"
                            value={newBook.title}
                            onChange={(e) => setNewBook({ ...newBook, title: e.target.value })}
                            className="w-full bg-secondary border border-border-color rounded-lg p-2.5 font-mono text-sm text-primary focus:outline-none focus:border-amber"
                            style={{ background: '#141824', color: '#fff' }}
                          />
                        </div>

                        <div>
                          <label className="font-mono text-xs text-muted uppercase font-bold block mb-1">Author</label>
                          <input
                            type="text"
                            placeholder="e.g. James Clear"
                            value={newBook.author}
                            onChange={(e) => setNewBook({ ...newBook, author: e.target.value })}
                            className="w-full bg-secondary border border-border-color rounded-lg p-2.5 font-mono text-sm text-primary focus:outline-none focus:border-amber"
                            style={{ background: '#141824', color: '#fff' }}
                          />
                        </div>
                      </div>

                      <div className="grid grid-cols-1 sm:grid-cols-3 gap-4">
                        <div>
                          <label className="font-mono text-xs text-muted uppercase font-bold block mb-1">Genre / Category</label>
                          <select
                            value={newBook.category}
                            onChange={(e) => setNewBook({ ...newBook, category: e.target.value })}
                            className="w-full bg-secondary border border-border-color rounded-lg p-2.5 font-mono text-xs text-primary focus:outline-none focus:border-amber"
                            style={{ background: '#141824', color: '#fff' }}
                          >
                            <option value="Business">Business / Startup</option>
                            <option value="Philosophy">Philosophy / Mindset</option>
                            <option value="Technical">Technical / Skills</option>
                            <option value="Biography">Biography / History</option>
                            <option value="Fiction">Fiction</option>
                            <option value="Other">Other</option>
                          </select>
                        </div>

                        <div>
                          <label className="font-mono text-xs text-muted uppercase font-bold block mb-1">Rating</label>
                          <select
                            value={newBook.rating}
                            onChange={(e) => setNewBook({ ...newBook, rating: parseInt(e.target.value) })}
                            className="w-full bg-secondary border border-border-color rounded-lg p-2.5 font-mono text-xs text-warning font-bold focus:outline-none focus:border-amber"
                            style={{ background: '#141824' }}
                          >
                            <option value={5}>⭐⭐⭐⭐⭐ (5/5 Exceptional)</option>
                            <option value={4}>⭐⭐⭐⭐ (4/5 Great)</option>
                            <option value={3}>⭐⭐⭐ (3/5 Good)</option>
                            <option value={2}>⭐⭐ (2/5 Average)</option>
                            <option value={1}>⭐ (1/5 Poor)</option>
                          </select>
                        </div>

                        <div>
                          <label className="font-mono text-xs text-muted uppercase font-bold block mb-1">Completion Date</label>
                          <input
                            type="date"
                            value={newBook.date_completed}
                            onChange={(e) => setNewBook({ ...newBook, date_completed: e.target.value })}
                            className="w-full bg-secondary border border-border-color rounded-lg p-2 font-mono text-xs text-primary focus:outline-none focus:border-amber"
                            style={{ background: '#141824', color: '#fff' }}
                          />
                        </div>
                      </div>

                      <div>
                        <label className="font-mono text-xs text-muted uppercase font-bold block mb-1">Cover Image URL (Optional)</label>
                        <input
                          type="url"
                          placeholder="https://..."
                          value={newBook.cover_url}
                          onChange={(e) => setNewBook({ ...newBook, cover_url: e.target.value })}
                          className="w-full bg-secondary border border-border-color rounded-lg p-2.5 font-mono text-xs text-primary focus:outline-none focus:border-amber"
                          style={{ background: '#141824', color: '#fff' }}
                        />
                      </div>

                      <div>
                        <label className="font-mono text-xs text-muted uppercase font-bold block mb-1">Key Takeaways & Summary</label>
                        <textarea
                          rows={3}
                          placeholder="Main lessons, action items, or core concepts..."
                          value={newBook.takeaways}
                          onChange={(e) => setNewBook({ ...newBook, takeaways: e.target.value })}
                          className="w-full bg-secondary border border-border-color rounded-xl p-3 font-mono text-xs text-primary focus:outline-none focus:border-amber"
                          style={{ background: '#141824', color: '#fff' }}
                        />
                      </div>

                      <div className="flex justify-end gap-3 pt-2">
                        <button
                          type="button"
                          onClick={() => setShowAddBook(false)}
                          className="px-4 py-2 bg-secondary border border-border-color rounded-xl font-mono text-xs text-muted hover:text-primary transition-colors"
                        >
                          Cancel
                        </button>
                        <button
                          type="submit"
                          className="px-5 py-2 bg-amber hover:bg-amber-hover text-black font-mono text-xs font-bold uppercase rounded-xl shadow-md transition-all active:scale-95 flex items-center gap-2"
                        >
                          <Save size={15} />
                          <span>Save Book</span>
                        </button>
                      </div>
                    </form>
                  </HudPanel>
                </motion.div>
              )}
            </AnimatePresence>

            {/* BOOKS GRID ARCHIVE */}
            {filteredBooks.length === 0 ? (
              <div className="font-mono text-sm text-muted text-center py-12 bg-tertiary border border-border-color rounded-xl">
                NO BOOKS FOUND IN ARCHIVE.
              </div>
            ) : (
              <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                {filteredBooks.map((book, idx) => {
                  const isEditing = editingBookId === (book.id || book.title)
                  const isExpanded = expandedBookId === (book.id || book.title)

                  return (
                    <div
                      key={book.id || idx}
                      className="p-4 rounded-xl bg-tertiary border border-border-color hover:border-amber/60 transition-all flex flex-col justify-between space-y-3 group"
                    >
                      {isEditing ? (
                        <div className="space-y-3">
                          <input
                            type="text"
                            value={editBookForm.title}
                            onChange={(e) => setEditBookForm({ ...editBookForm, title: e.target.value })}
                            className="w-full bg-secondary border border-border-color rounded p-2 font-mono text-xs text-primary"
                          />
                          <input
                            type="text"
                            value={editBookForm.author}
                            onChange={(e) => setEditBookForm({ ...editBookForm, author: e.target.value })}
                            className="w-full bg-secondary border border-border-color rounded p-2 font-mono text-xs text-primary"
                          />
                          <textarea
                            rows={3}
                            value={editBookForm.takeaways}
                            onChange={(e) => setEditBookForm({ ...editBookForm, takeaways: e.target.value })}
                            className="w-full bg-secondary border border-border-color rounded p-2 font-mono text-xs text-primary"
                          />
                          <div className="flex justify-end gap-2">
                            <button
                              onClick={() => saveEditBook(book.id)}
                              className="px-3 py-1 bg-amber text-black font-mono text-xs font-bold rounded"
                            >
                              Save
                            </button>
                            <button
                              onClick={() => setEditingBookId(null)}
                              className="px-3 py-1 bg-secondary text-muted font-mono text-xs rounded"
                            >
                              Cancel
                            </button>
                          </div>
                        </div>
                      ) : (
                        <>
                          <div className="flex items-start gap-3">
                            {/* Book Cover Preview or Stylized Book Spine */}
                            {book.cover_url ? (
                              <img
                                src={book.cover_url}
                                alt={book.title}
                                className="w-14 h-20 object-cover rounded-lg border border-border-color shadow-sm shrink-0"
                              />
                            ) : (
                              <div className="w-14 h-20 rounded-lg bg-amber/10 border border-amber/30 flex flex-col items-center justify-center p-1 text-center shrink-0">
                                <Book size={20} className="text-amber mb-1" />
                                <span className="font-mono text-[8px] text-amber font-bold leading-tight truncate max-w-full">
                                  {book.category}
                                </span>
                              </div>
                            )}

                            <div className="flex-1 min-w-0">
                              <div className="flex items-center justify-between gap-2">
                                <span className="font-mono text-[10px] text-amber font-bold uppercase">
                                  {book.category || 'Business'}
                                </span>
                                <span className="font-mono text-[10px] text-muted">
                                  {book.date_completed}
                                </span>
                              </div>

                              <h3 className="font-display text-base uppercase tracking-wider text-primary truncate mt-0.5">
                                {book.title}
                              </h3>
                              <p className="font-mono text-xs text-secondary italic truncate">
                                by {book.author || 'Unknown'}
                              </p>

                              {/* Star Rating Display */}
                              <div className="flex items-center gap-1 mt-1.5 text-warning font-mono text-xs font-bold">
                                {'★'.repeat(book.rating || 5)}{'☆'.repeat(5 - (book.rating || 5))}
                                <span className="text-muted text-[10px] ml-1">({book.rating || 5}/5)</span>
                              </div>
                            </div>
                          </div>

                          {/* Key Takeaways & Expand Accordion */}
                          {book.takeaways && (
                            <div className="pt-2 border-t border-border-subtle/50">
                              <div
                                onClick={() => setExpandedBookId(isExpanded ? null : (book.id || book.title))}
                                className="flex items-center justify-between cursor-pointer text-muted hover:text-primary transition-colors font-mono text-[10px] uppercase font-bold"
                              >
                                <span>Key Takeaways & Notes</span>
                                {isExpanded ? <ChevronUp size={14} /> : <ChevronDown size={14} />}
                              </div>

                              <AnimatePresence>
                                {isExpanded && (
                                  <motion.div
                                    initial={{ height: 0, opacity: 0 }}
                                    animate={{ height: 'auto', opacity: 1 }}
                                    exit={{ height: 0, opacity: 0 }}
                                    className="overflow-hidden"
                                  >
                                    <p className="font-mono text-xs text-secondary whitespace-pre-wrap leading-relaxed mt-2 p-2.5 rounded bg-secondary/40 border border-border-subtle">
                                      {book.takeaways}
                                    </p>
                                  </motion.div>
                                )}
                              </AnimatePresence>
                            </div>
                          )}

                          {/* Card Actions */}
                          <div className="flex items-center justify-between pt-2 border-t border-border-subtle/40">
                            <div className="flex items-center gap-2 font-mono text-[10px]">
                              <button
                                type="button"
                                onClick={() => startEditBook(book)}
                                className="text-muted hover:text-amber transition-colors flex items-center gap-1"
                              >
                                <Edit2 size={10} /> EDIT
                              </button>
                            </div>

                            <button
                              type="button"
                              onClick={() => handleDeleteBook(book.id, book.title)}
                              className="text-danger/70 hover:text-danger transition-colors font-mono text-[10px] flex items-center gap-1"
                            >
                              <Trash2 size={10} /> DELETE
                            </button>
                          </div>
                        </>
                      )}
                    </div>
                  )
                })}
              </div>
            )}
          </div>
        )}

        {/* PROJECTS TAB */}
        {activeTab === 'projects' && (
          <div className="flex-col gap-6">
            <div className="flex justify-end">
              <button className="btn btn-primary btn-sm flex items-center gap-2" onClick={() => setShowAddProject(!showAddProject)}>
                <Plus size={16} /> ADD PROJECT
              </button>
            </div>

            <AnimatePresence>
              {showAddProject && (
                <motion.div initial={{ opacity: 0, height: 0 }} animate={{ opacity: 1, height: 'auto' }} exit={{ opacity: 0, height: 0 }} className="overflow-hidden">
                  <HudPanel label="NEW PROJECT" className="border-info mb-6">
                    <form onSubmit={handleCreateProject} className="grid grid-cols-1 md:grid-cols-2 gap-4">
                      <div>
                        <label className="font-mono text-xs text-muted mb-1 block">PROJECT TITLE</label>
                        <input type="text" className="input font-mono text-sm" value={newProj.title} onChange={e => setNewProj({...newProj, title: e.target.value})} required />
                      </div>
                      <div>
                        <label className="font-mono text-xs text-muted mb-1 block">STATUS</label>
                        <select className="select font-mono text-sm" value={newProj.status} onChange={e => setNewProj({...newProj, status: e.target.value})}>
                          <option value="idea">IDEA</option>
                          <option value="active">ACTIVE</option>
                          <option value="paused">PAUSED</option>
                          <option value="completed">COMPLETED</option>
                        </select>
                      </div>
                      <div className="md:col-span-2">
                        <label className="font-mono text-xs text-muted mb-1 block">DESCRIPTION</label>
                        <textarea className="textarea font-mono text-sm h-20" value={newProj.description} onChange={e => setNewProj({...newProj, description: e.target.value})} />
                      </div>
                      <div className="md:col-span-2">
                        <label className="font-mono text-xs text-muted mb-1 block">TECH STACK / SKILLS (COMMA SEPARATED)</label>
                        <input type="text" className="input font-mono text-sm" value={newProj.tech_stack} onChange={e => setNewProj({...newProj, tech_stack: e.target.value})} placeholder="React, Node.js, Marketing..." />
                      </div>
                      <div className="md:col-span-2 flex justify-end">
                        <button type="submit" className="btn btn-primary w-full md:w-auto">SAVE PROJECT</button>
                      </div>
                    </form>
                  </HudPanel>
                </motion.div>
              )}
            </AnimatePresence>

            <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
              {projects.map((proj) => {
                const isEditing = editingProjectId === proj.id
                return (
                  <div key={proj.id} className="bg-tertiary border border-border-color p-5 hover:border-info transition-colors flex flex-col justify-between h-full group rounded-xl">
                    {isEditing ? (
                      <form onSubmit={(e) => { e.preventDefault(); saveEditProject(proj.id); }} className="space-y-3">
                        <div>
                          <label className="font-mono text-[10px] text-amber uppercase font-bold block mb-1">Project Title</label>
                          <input
                            type="text"
                            className="input w-full font-mono text-xs py-1.5 px-2 bg-bg-primary border border-border-color"
                            value={editProjForm.title}
                            onChange={e => setEditProjForm({ ...editProjForm, title: e.target.value })}
                            required
                          />
                        </div>
                        <div>
                          <label className="font-mono text-[10px] text-amber uppercase font-bold block mb-1">Status</label>
                          <select
                            className="select w-full font-mono text-xs py-1.5 px-2 bg-bg-primary border border-border-color"
                            value={editProjForm.status}
                            onChange={e => setEditProjForm({ ...editProjForm, status: e.target.value })}
                          >
                            <option value="idea">IDEA</option>
                            <option value="active">ACTIVE</option>
                            <option value="paused">PAUSED</option>
                            <option value="completed">COMPLETED</option>
                          </select>
                        </div>
                        <div>
                          <label className="font-mono text-[10px] text-amber uppercase font-bold block mb-1">Description</label>
                          <textarea
                            className="textarea w-full font-mono text-xs py-1.5 px-2 bg-bg-primary border border-border-color h-16"
                            value={editProjForm.description}
                            onChange={e => setEditProjForm({ ...editProjForm, description: e.target.value })}
                          />
                        </div>
                        <div>
                          <label className="font-mono text-[10px] text-amber uppercase font-bold block mb-1">Tech Stack (comma separated)</label>
                          <input
                            type="text"
                            className="input w-full font-mono text-xs py-1.5 px-2 bg-bg-primary border border-border-color"
                            value={editProjForm.tech_stack}
                            onChange={e => setEditProjForm({ ...editProjForm, tech_stack: e.target.value })}
                          />
                        </div>
                        <div className="flex items-center gap-2 pt-1">
                          <button type="submit" className="btn btn-primary btn-xs font-mono font-bold flex items-center gap-1">
                            <Save size={12} /> SAVE
                          </button>
                          <button
                            type="button"
                            onClick={() => setEditingProjectId(null)}
                            className="btn btn-secondary btn-xs font-mono font-bold text-muted"
                          >
                            CANCEL
                          </button>
                        </div>
                      </form>
                    ) : (
                      <>
                        <div>
                          <div className="flex items-center justify-between gap-2 mb-3">
                            <h3 className="font-display text-2xl uppercase tracking-wider text-primary group-hover:text-info transition-colors">{proj.title}</h3>
                            <span className={`badge ${proj.status === 'active' ? 'badge-amber' : proj.status === 'completed' ? 'badge-success' : 'badge-ghost'}`}>
                              {String(proj.status || 'UNKNOWN').toUpperCase()}
                            </span>
                          </div>
                          <p className="font-mono text-sm text-secondary mb-4">{proj.description}</p>
                        </div>

                        <div className="space-y-3 mt-auto pt-3 border-t border-border-subtle/50">
                          {Array.isArray(proj.tech_stack) && proj.tech_stack.length > 0 && (
                            <div className="flex flex-wrap gap-1.5">
                              {proj.tech_stack.map((tech, idx) => (
                                <span key={idx} className="font-mono text-[10px] text-muted bg-bg-primary px-2 py-0.5 border border-border-strong rounded">
                                  {tech}
                                </span>
                              ))}
                            </div>
                          )}

                          <div className="flex items-center justify-between pt-2 border-t border-border-subtle/40 font-mono text-[10px]">
                            <button
                              type="button"
                              onClick={() => startEditProject(proj)}
                              className="text-muted hover:text-amber transition-colors flex items-center gap-1 font-bold"
                            >
                              <Edit2 size={11} /> EDIT PROJECT
                            </button>
                            <button
                              type="button"
                              onClick={() => handleDeleteProject(proj.id, proj.title)}
                              className="text-danger/70 hover:text-danger transition-colors flex items-center gap-1 font-bold"
                            >
                              <Trash2 size={11} /> DELETE
                            </button>
                          </div>
                        </div>
                      </>
                    )}
                  </div>
                )
              })}
              {projects.length === 0 && <div className="font-mono text-sm text-muted col-span-2 py-8 text-center border border-dashed border-border-color rounded-xl">NO PROJECTS ARCHIVED YET.</div>}
            </div>
          </div>
        )}

        {/* RESUME TAB (EXECUTIVE MASTER RESUME) */}
        {activeTab === 'resume' && (
          <div className="space-y-6">
            {/* Executive Action Bar (Hidden when printing PDF) */}
            <div className="flex flex-wrap items-center justify-between gap-3 p-4 bg-tertiary border border-border-color rounded-2xl print:hidden">
              <div className="flex items-center gap-2">
                <Sparkles size={16} className="text-amber" />
                <span className="font-display text-xs uppercase tracking-widest text-primary font-bold">
                  EXECUTIVE PORTFOLIO RESUME
                </span>
                <span className="font-mono text-[10px] text-muted hidden sm:inline">
                  • Real-time Live Sync
                </span>
              </div>

              <div className="flex items-center gap-2.5">
                <button
                  type="button"
                  onClick={() => setShowAllResumeLogs(!showAllResumeLogs)}
                  className="px-3 py-1.5 rounded-lg border border-border-color bg-secondary hover:bg-hover text-secondary font-mono text-xs uppercase font-semibold transition-colors"
                >
                  {showAllResumeLogs ? 'Show Compact View' : `Show All (${logs.length} Weeks)`}
                </button>

                <button
                  type="button"
                  onClick={async () => {
                    setLoading(true)
                    await fetchData()
                    setXpToast('✨ Live Executive Resume Re-Generated with Latest Intel')
                    setTimeout(() => setXpToast(null), 3500)
                  }}
                  className="px-3.5 py-2 rounded-lg border border-amber/40 bg-amber/15 hover:bg-amber/30 text-amber font-mono text-xs uppercase font-bold transition-all flex items-center gap-1.5"
                  title="Re-aggregate all projects, debriefs, and work sessions into resume"
                >
                  <RefreshCw size={13} className={loading ? "animate-spin" : ""} />
                  <span>RE-GENERATE RESUME</span>
                </button>

                <button
                  type="button"
                  onClick={() => window.print()}
                  className="btn btn-primary btn-sm flex items-center gap-2 px-4 py-2 font-mono text-xs font-bold"
                >
                  <Printer size={14} /> EXPORT / PRINT PDF
                </button>
              </div>
            </div>

            {/* Resume Main Document Card */}
            <HudPanel className="bg-bg-primary border-amber/50 print:border-none p-6 sm:p-10 space-y-8 max-w-4xl mx-auto shadow-2xl">
              
              {/* Operator Identity Header */}
              <div className="text-center border-b border-border-color pb-8 space-y-3">
                <div className="font-mono text-[10px] uppercase tracking-widest text-amber font-bold">
                  SAGA OPERATOR DOSSIER
                </div>
                <h1 className="font-display text-4xl sm:text-5xl uppercase tracking-widest text-primary font-bold">
                  {profile?.full_name || 'CHIRAG SHETTY'}
                </h1>
                <p className="font-mono text-xs sm:text-sm text-amber uppercase tracking-widest font-semibold">
                  FOUNDER & OPERATOR • SYSTEM ARCHITECT
                </p>

                <div className="flex flex-wrap items-center justify-center gap-3 pt-2 font-mono text-xs text-muted">
                  <span className="px-3 py-1 rounded-full bg-secondary border border-border-color font-bold" style={{ color: dynamicRank.color }}>
                    {dynamicRank.name}
                  </span>
                  <span>•</span>
                  <span className="text-cyan font-bold">LEVEL {dynamicLevel}</span>
                  <span>•</span>
                  <span className="text-amber font-bold">{userXp.toLocaleString()} XP</span>
                  <span>•</span>
                  <span className="text-success font-bold">{dynamicRank.code} RANK</span>
                </div>
              </div>

              {/* KPI Metrics Summary Grid */}
              <div className="grid grid-cols-2 sm:grid-cols-4 gap-3 font-mono text-xs text-center">
                <div className="p-3 rounded-xl bg-tertiary border border-border-subtle">
                  <span className="text-muted text-[9px] uppercase tracking-wider block font-bold mb-1">Discipline Level</span>
                  <span className="text-cyan font-display text-xl font-bold">LVL {dynamicLevel}</span>
                </div>
                <div className="p-3 rounded-xl bg-tertiary border border-border-subtle">
                  <span className="text-muted text-[9px] uppercase tracking-wider block font-bold mb-1">Total XP Earned</span>
                  <span className="text-amber font-display text-xl font-bold">{userXp.toLocaleString()}</span>
                </div>
                <div className="p-3 rounded-xl bg-tertiary border border-border-subtle">
                  <span className="text-muted text-[9px] uppercase tracking-wider block font-bold mb-1">Missions Completed</span>
                  <span className="text-success font-display text-xl font-bold">{completedMissions.length} Finished</span>
                </div>
                <div className="p-3 rounded-xl bg-tertiary border border-border-subtle">
                  <span className="text-muted text-[9px] uppercase tracking-wider block font-bold mb-1">Active Missions</span>
                  <span className="text-info font-display text-xl font-bold">{ongoingMissions.length} Ongoing</span>
                </div>
              </div>

              {/* Core Competencies & Skills */}
              <div className="space-y-3">
                <h2 className="font-display text-lg uppercase tracking-wider text-amber border-b border-border-color pb-2 flex items-center gap-2">
                  <Terminal size={18} /> CORE COMPETENCIES & DISCIPLINE PILLARS
                </h2>
                <div className="flex flex-wrap gap-2 font-mono text-xs">
                  {[
                    'Video Production & Post-Editing', 'Premiere Pro & AutoCut',
                    'System Architecture & Full-Stack JS', 'Next.js & Supabase Engine',
                    'Content Operations & Directing', 'High-Focus Deep Execution',
                    'Weekly Debriefing & Iteration', 'Productivity OS Architecture'
                  ].map((skill, idx) => (
                    <span key={idx} className="px-3 py-1 rounded-lg bg-tertiary border border-border-color text-primary font-semibold">
                      {skill}
                    </span>
                  ))}
                </div>
              </div>

              {/* OPERATIONAL MISSIONS & STRATEGIC GOALS (COMPLETED & ONGOING) */}
              <div className="space-y-4">
                <div className="flex items-center justify-between border-b border-border-color pb-2">
                  <h2 className="font-display text-lg uppercase tracking-wider text-amber flex items-center gap-2">
                    <Target size={18} /> OPERATIONAL MISSIONS & STRATEGIC GOALS
                  </h2>
                  <span className="font-mono text-[10px] text-muted">
                    {completedMissions.length} Completed • {ongoingMissions.length} Ongoing
                  </span>
                </div>

                {/* Section A: Active & Ongoing Missions */}
                {ongoingMissions.length > 0 && (
                  <div className="space-y-2.5">
                    <h3 className="font-mono text-xs font-bold uppercase tracking-widest text-info flex items-center gap-2">
                      <Flame size={14} /> ACTIVE & ONGOING MISSIONS ({ongoingMissions.length})
                    </h3>
                    <div className="grid grid-cols-1 md:grid-cols-2 gap-3 font-mono text-xs">
                      {ongoingMissions.map(g => (
                        <div key={g.id} className="p-3.5 rounded-xl bg-tertiary border border-info/30 flex flex-col justify-between space-y-2">
                          <div className="space-y-1">
                            <div className="flex items-center justify-between gap-2">
                              <span className="text-primary font-bold text-sm leading-snug">{g.title}</span>
                              <span className="font-mono text-[9px] text-info font-bold px-2 py-0.5 rounded bg-info/10 border border-info/30 uppercase shrink-0">ONGOING</span>
                            </div>
                            {g.description && <p className="text-muted text-xs line-clamp-2">{g.description}</p>}
                          </div>
                          <div className="flex items-center justify-between text-[10px] text-muted uppercase pt-1 border-t border-border-subtle/50">
                            <span className="text-amber font-semibold">{g.type ? g.type.replace('_', ' ') : 'MISSION'}</span>
                            {g.target_date && <span>Target: {g.target_date}</span>}
                          </div>
                        </div>
                      ))}
                    </div>
                  </div>
                )}

                {/* Section B: Completed Missions */}
                {completedMissions.length > 0 && (
                  <div className="space-y-2.5 pt-2">
                    <h3 className="font-mono text-xs font-bold uppercase tracking-widest text-success flex items-center gap-2">
                      <Trophy size={14} /> COMPLETED MISSIONS & KEY MILESTONES ({completedMissions.length})
                    </h3>
                    <div className="grid grid-cols-1 md:grid-cols-2 gap-3 font-mono text-xs">
                      {completedMissions.map(g => (
                        <div key={g.id} className="p-3.5 rounded-xl bg-tertiary border border-success/30 flex flex-col justify-between space-y-2">
                          <div className="space-y-1">
                            <div className="flex items-center justify-between gap-2">
                              <span className="text-primary font-bold text-sm leading-snug">{g.title}</span>
                              <span className="font-mono text-[9px] text-success font-bold px-2 py-0.5 rounded bg-success/10 border border-success/30 uppercase shrink-0">✓ COMPLETED</span>
                            </div>
                            {g.description && <p className="text-secondary text-xs line-clamp-2">{g.description}</p>}
                          </div>
                          <div className="flex items-center justify-between text-[10px] text-muted uppercase pt-1 border-t border-border-subtle/50">
                            <span className="text-amber font-semibold">{g.type ? g.type.replace('_', ' ') : 'MISSION'}</span>
                            {g.completed_at && <span className="text-success">Achieved: {g.completed_at.slice(0, 10)}</span>}
                          </div>
                        </div>
                      ))}
                    </div>
                  </div>
                )}

                {ongoingMissions.length === 0 && completedMissions.length === 0 && (
                  <p className="font-mono text-xs text-muted text-center py-6">No strategic missions logged yet.</p>
                )}
              </div>

              {/* Literature & Knowledge Intake (Books Completed) */}
              {books.length > 0 && (
                <div className="space-y-3">
                  <h2 className="font-display text-lg uppercase tracking-wider text-amber border-b border-border-color pb-2 flex items-center gap-2">
                    <BookOpen size={18} /> LITERATURE & KNOWLEDGE INTAKE ({books.length})
                  </h2>
                  <div className="grid grid-cols-1 md:grid-cols-2 gap-3 font-mono text-xs">
                    {books.map((b, i) => (
                      <div key={i} className="p-3.5 rounded-xl bg-tertiary border border-border-color space-y-1">
                        <div className="text-primary font-bold uppercase">{b.title}</div>
                        <div className="text-muted text-[10px]">by {b.author || 'Unknown'} • <span className="text-cyan">{b.category}</span></div>
                        <div className="text-amber font-bold text-[11px] pt-1">
                          {'★'.repeat(b.rating || 5)} <span className="text-muted text-[10px] font-normal ml-1">({b.date_completed})</span>
                        </div>
                      </div>
                    ))}
                  </div>
                </div>
              )}

              {/* Key Systems & Projects */}
              <div className="space-y-3">
                <h2 className="font-display text-lg uppercase tracking-wider text-amber border-b border-border-color pb-2 flex items-center gap-2">
                  <Database size={18} /> SHIPPED PROJECTS & SYSTEM BUILD-OUTS
                </h2>
                <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                  {projects.map(proj => (
                    <div key={proj.id} className="p-4 rounded-xl border border-border-color bg-tertiary space-y-2">
                      <div className="flex items-center justify-between">
                        <h3 className="font-mono text-sm text-primary font-bold uppercase">{proj.title}</h3>
                        <span className="font-mono text-[9px] text-success uppercase px-2 py-0.5 rounded bg-success/10 border border-success/30">
                          {proj.status || 'ACTIVE'}
                        </span>
                      </div>
                      <p className="font-mono text-xs text-secondary leading-relaxed">{proj.description}</p>
                      {Array.isArray(proj.tech_stack) && proj.tech_stack.length > 0 && (
                        <div className="flex flex-wrap gap-1 pt-1">
                          {proj.tech_stack.map((t, i) => (
                            <span key={i} className="font-mono text-[9px] bg-bg-primary px-2 py-0.5 border border-border-strong text-muted rounded">
                              {t}
                            </span>
                          ))}
                        </div>
                      )}
                    </div>
                  ))}
                  {projects.length === 0 && <p className="font-mono text-xs text-muted">Awaiting project data.</p>}
                </div>
              </div>

              {/* Resume Footer */}
              <div className="border-t border-border-color pt-6 flex flex-wrap items-center justify-between gap-4 font-mono text-[10px] text-muted">
                <div>AUTHENTICATED DOSSIER • GENERATED BY CHIRAG OS EXECUTIVE ENGINE</div>
                <div className="flex items-center gap-3">
                  <span>CONFIDENTIAL</span>
                  <span>•</span>
                  <span>{new Date().toLocaleDateString('en-US', { year: 'numeric', month: 'short', day: 'numeric' })}</span>
                </div>
              </div>

            </HudPanel>
          </div>
        )}

      </div>
    </AppShell>
  )
}

'use client'

import { useState, useEffect } from 'react'
import AppShell from '@/components/layout/AppShell'
import HudPanel from '@/components/ui/HudPanel'
import { createClient } from '@/lib/supabase/client'
import { useAuth } from '@/lib/hooks/useAuth'
import { useHabits } from '@/lib/hooks/useHabits'
import { motion, AnimatePresence } from 'framer-motion'
import { Shield, Brain, Zap, Target, Award, CheckCircle, Crosshair, TrendingUp, Search, Calendar, Flame, Lock, Unlock, Play, Pause, AlertTriangle, ChevronRight, ChevronDown, ChevronUp, X, Edit2, Trash2, Plus, Smartphone, Settings, BarChart2, Briefcase, Heart, BookOpen, User as UserIcon, LogOut, Sun, Moon, Cpu, Coffee, Activity, ArrowRight, ShieldAlert, Navigation, Layers, Link as LinkIcon, Database, ArrowUpCircle, Eye, Skull, Rocket, Sparkles, Dumbbell, Swords } from 'lucide-react'
import { QUEST_CATEGORIES } from '@/lib/constants'
import { getLocalDateStr } from '@/lib/utils/dates'
import { syncWarRoomDailyEvaluator } from '@/lib/utils/warRoomSync'

// ── DEFAULT BLUEPRINT DATA ──
const DEFAULT_BLUEPRINT = {
  identity: 'Founder, Builder, AI Educator, Marketer, Operator, Lifelong Learner',
  mission: 'Build Beyond Tatva into a leading AI education platform that helps students use AI effectively while creating financial freedom, meaningful impact, and long term personal growth.',
  motives: `I do not want to spend my life working on goals chosen by other people.\n\nI want to build something valuable that improves the lives of students and creates opportunities for myself and my family.\n\nBeyond Tatva is more than a business. It is proof that I can turn ideas into reality.`,
  strengths: ['Fast learner', 'Curious about technology', 'Willing to experiment', 'Strong interest in AI', 'Creative thinker'],
  weaknesses: ['Phone addiction', 'Inconsistent execution', 'Overplanning', 'Starting too many projects', 'Difficulty focusing on one priority'],
  values_list: ['No quitting Beyond Tatva', 'Workout at least 3 times per week', 'Maintain personal hygiene', 'Daily learning', 'Journal regularly'],
  future_vision: `Build Beyond Tatva into a recognized education company.\n\nGenerate sustainable income exceeding ₹5 lakh per month.`
}

const DEFAULT_BATTLES = [
  { name: 'Phone Addiction', hp: 80, severity: 'high', notes: 'Primary discipline threat.', linked_habits: [] },
  { name: 'Porn Consumption', hp: 90, severity: 'high', notes: 'Drain on discipline and self-respect.', linked_habits: [] },
  { name: 'Inconsistent Execution', hp: 70, severity: 'high', notes: 'Starting strong, dropping off.', linked_habits: [] }
]

export default function OperatorDashboard() {
  const { user } = useAuth()
  const { habits } = useHabits()
  const [loading, setLoading] = useState(true)
  const [blueprint, setBlueprint] = useState(null)
  const [saving, setSaving] = useState(false)
  const [editMode, setEditMode] = useState(false)
  
  const [openSections, setOpenSections] = useState({
    identity: false,
    mission: false,
    endgame: false,
    warroom: true,
    advantages: false,
    vulnerabilities: false,
    code: false
  })

  const toggleSection = (key) => {
    setOpenSections(prev => ({ ...prev, [key]: !prev[key] }))
  }
  
  const [battles, setBattles] = useState(DEFAULT_BATTLES)
  const [showAddBattle, setShowAddBattle] = useState(false)
  const [newBattle, setNewBattle] = useState({ name: '', severity: 'medium', notes: '', linked_habits: [], hp: 100 })
  const [todayHabitLogs, setTodayHabitLogs] = useState([])
  const [todayScreenTime, setTodayScreenTime] = useState(null)
  const [selectedBattleIntel, setSelectedBattleIntel] = useState(null)

  const [form, setForm] = useState({
    identity: DEFAULT_BLUEPRINT.identity,
    mission: DEFAULT_BLUEPRINT.mission,
    motives: DEFAULT_BLUEPRINT.motives,
    values_list: DEFAULT_BLUEPRINT.values_list.join('\n'),
    weaknesses: DEFAULT_BLUEPRINT.weaknesses.join('\n'),
    strengths: DEFAULT_BLUEPRINT.strengths.join('\n'),
    future_vision: DEFAULT_BLUEPRINT.future_vision
  })

  useEffect(() => {
    if (!user) return
    fetchBlueprint()

    const handleBattlesUpdated = (e) => {
      if (e.detail && Array.isArray(e.detail)) {
        setBattles(e.detail)
      }
    }
    window.addEventListener('lokios_battles_updated', handleBattlesUpdated)
    return () => window.removeEventListener('lokios_battles_updated', handleBattlesUpdated)
  }, [user])

  const fetchBlueprint = async () => {
    const supabase = createClient()
    const evaluatedBattles = await syncWarRoomDailyEvaluator(user.id)

    const { data: rows, error } = await supabase.from('user_blueprints').select('*').eq('user_id', user.id)
    
    if (error) {
      console.error('Error fetching blueprint:', error)
    }

    if (rows && rows.length > 0) {
      const data = rows[0]
      setBlueprint(data)
      setForm({
        identity: data.identity || DEFAULT_BLUEPRINT.identity,
        mission: data.mission || DEFAULT_BLUEPRINT.mission,
        motives: data.motives || DEFAULT_BLUEPRINT.motives,
        values_list: data.values_list ? data.values_list.join('\n') : DEFAULT_BLUEPRINT.values_list.join('\n'),
        weaknesses: data.weaknesses ? data.weaknesses.join('\n') : DEFAULT_BLUEPRINT.weaknesses.join('\n'),
        strengths: data.strengths ? data.strengths.join('\n') : DEFAULT_BLUEPRINT.strengths.join('\n'),
        future_vision: data.future_vision || DEFAULT_BLUEPRINT.future_vision
      })
      if (evaluatedBattles && evaluatedBattles.length > 0) {
        setBattles(evaluatedBattles)
      } else if (data.battles && Array.isArray(data.battles)) {
        const migratedBattles = data.battles.map(b => ({
          name: b.name,
          severity: b.severity,
          notes: b.notes,
          hp: b.hp !== undefined ? b.hp : (b.status === 'defeated' ? 0 : 50),
          linked_habits: b.linked_habits || []
        }))
        setBattles(migratedBattles)
      } else {
        setBattles([])
      }
    } else {
      setBattles(evaluatedBattles || DEFAULT_BATTLES)
    }

    const todayStr = getLocalDateStr(new Date())

    // Fetch today's habit logs for live battle intel
    const { data: hLogs } = await supabase
      .from('habit_logs')
      .select('*')
      .eq('user_id', user.id)
      .eq('date', todayStr)
    setTodayHabitLogs(hLogs || [])

    // Fetch today's screen time log for live battle intel
    const { data: stLogs } = await supabase
      .from('screen_time_logs')
      .select('*')
      .eq('user_id', user.id)
      .eq('date', todayStr)
      .limit(1)
    if (stLogs && stLogs.length > 0) setTodayScreenTime(stLogs[0])

    setLoading(false)
  }

  const handleStrikeBack = async (idx) => {
    if (!user) return
    const updated = [...battles]
    const target = updated[idx]
    if (!target) return

    const oldHp = target.hp ?? 100
    const newHp = Math.max(0, oldHp - 10)
    target.hp = newHp

    if (!target.combat_logs) target.combat_logs = []
    target.combat_logs.unshift({
      date: getLocalDateStr(new Date()),
      action: '⚡ STRIKE BACK EXECUTED',
      hpChange: -10
    })

    let xpAward = 25
    if (newHp === 0 && oldHp > 0) {
      xpAward = 200
    }

    setBattles(updated)

    const supabase = createClient()
    await supabase
      .from('user_blueprints')
      .update({ battles: updated })
      .eq('user_id', user.id)

  }

  const handleSave = async () => {
    setSaving(true)
    const supabase = createClient()

    const payload = {
      user_id: user.id,
      identity: form.identity,
      mission: form.mission,
      motives: form.motives,
      values_list: form.values_list.split('\n').filter(Boolean),
      weaknesses: form.weaknesses.split('\n').filter(Boolean),
      strengths: form.strengths.split('\n').filter(Boolean),
      future_vision: form.future_vision,
      battles: battles
    }

    let result
    if (blueprint) {
      result = await supabase.from('user_blueprints').update(payload).eq('id', blueprint.id)
    } else {
      result = await supabase.from('user_blueprints').insert([payload])
    }

    if (result.error) {
      console.error('Error saving blueprint:', result.error)
      alert('Error saving directives: ' + result.error.message)
    } else {
      await fetchBlueprint()
      setEditMode(false)
    }
    setSaving(false)
  }

  const saveBattlesToDB = async (newBattles) => {
    const supabase = createClient()
    let result
    if (blueprint) {
      result = await supabase.from('user_blueprints').update({ battles: newBattles }).eq('id', blueprint.id)
    } else {
      result = await supabase.from('user_blueprints').insert([{
        user_id: user.id,
        identity: form.identity,
        mission: form.mission,
        motives: form.motives,
        values_list: form.values_list.split('\n').filter(Boolean),
        weaknesses: form.weaknesses.split('\n').filter(Boolean),
        strengths: form.strengths.split('\n').filter(Boolean),
        future_vision: form.future_vision,
        battles: newBattles
      }])
    }

    if (result.error) {
      console.error('Error saving battles:', result.error)
      alert('Error saving war room updates: ' + result.error.message)
    } else {
      await fetchBlueprint()
    }
  }

  const addBattle = async () => {
    if (!newBattle.name.trim()) return
    const currentBattles = await new Promise(resolve => {
      setBattles(prev => {
        const next = [...prev, { ...newBattle }]
        resolve(next)
        return next
      })
    })
    setNewBattle({ name: '', severity: 'medium', notes: '', linked_habits: [], hp: 100 })
    setShowAddBattle(false)
    await saveBattlesToDB(currentBattles)
  }

  const removeBattle = async (idx) => {
    const currentBattles = await new Promise(resolve => {
      setBattles(prev => {
        const next = prev.filter((_, i) => i !== idx)
        resolve(next)
        return next
      })
    })
    await saveBattlesToDB(currentBattles)
  }

  const toggleLinkedHabit = async (battleIdx, habitId) => {
    const currentBattles = await new Promise(resolve => {
      setBattles(prev => {
        const next = prev.map((b, i) => {
          if (i !== battleIdx) return b
          const isLinked = b.linked_habits?.includes(habitId)
          return {
            ...b,
            linked_habits: isLinked 
              ? b.linked_habits.filter(id => id !== habitId)
              : [...(b.linked_habits || []), habitId]
          }
        })
        resolve(next)
        return next
      })
    })
    await saveBattlesToDB(currentBattles)
  }

  if (loading) return (
    <AppShell>
      <div className="flex-center h-full flex-col gap-2">
        <span className="typewriter-text">ACCESSING IDENTITY MATRIX...</span>
        <span className="font-mono text-xs text-cyan-400 font-bold tracking-widest uppercase animate-pulse flex items-center gap-1.5">
          <span>❄️</span> WINTER IS COMING <span>❄️</span>
        </span>
      </div>
    </AppShell>
  )

  const SEVERITY_COLORS = { high: 'var(--danger)', medium: 'var(--warning)', low: 'var(--info)' }

  return (
    <AppShell>
      <div className="page-container full" style={{ padding: 'var(--space-4)', maxWidth: '1600px', margin: '0 auto' }}>
        <header className="page-header flex-between mb-8">
          <div>
            <h1 className="font-display text-4xl font-bold tracking-widest text-primary uppercase">OPERATOR DASHBOARD</h1>
            <p className="font-mono text-xs text-amber tracking-widest uppercase mt-1">Identity Matrix</p>
          </div>
          <div className="flex gap-3">
            <button className={`btn ${editMode ? 'btn-ghost' : 'btn-primary'}`} onClick={() => setEditMode(!editMode)}>
              {editMode ? 'CANCEL' : 'ENTER EDIT MODE'}
            </button>
            {editMode && (
              <button className="btn btn-primary bg-success text-white border-success-subtle hover:bg-success-glow" onClick={handleSave} disabled={saving}>
                {saving ? 'SAVING...' : 'SAVE DIRECTIVES'}
              </button>
            )}
          </div>
        </header>

        <style dangerouslySetInnerHTML={{__html: `
          .operator-grid {
            display: grid;
            grid-template-columns: 1fr;
            gap: var(--space-6);
            align-items: start;
          }
          @media (min-width: 1024px) {
            .operator-grid {
              grid-template-columns: 3fr 5fr 4fr;
            }
          }
        `}} />

        <div className="operator-grid">
          
          {/* ── COLUMN 1: IDENTITY ── */}
          <div className="flex flex-col gap-6">
            <HudPanel glow className="border-info">
              <div 
                onClick={() => toggleSection('identity')}
                className="flex items-center justify-between gap-3 text-info border-b border-border-color pb-2 cursor-pointer select-none"
              >
                <div className="flex items-center gap-2">
                  <UserIcon size={16} /> <span className="font-display text-lg uppercase tracking-widest font-bold">IDENTITY</span>
                </div>
                <div className="flex items-center gap-2">
                  {!openSections.identity && !editMode && (
                    <span className="font-mono text-[10px] text-muted truncate max-w-[140px] hidden sm:inline-block">
                      {form.identity}
                    </span>
                  )}
                  <button type="button" className="p-1 text-muted hover:text-info transition-colors shrink-0">
                    {openSections.identity || editMode ? <ChevronUp size={18} /> : <ChevronDown size={18} />}
                  </button>
                </div>
              </div>
              <AnimatePresence>
                {(openSections.identity || editMode) && (
                  <motion.div initial={{ height: 0, opacity: 0 }} animate={{ height: 'auto', opacity: 1 }} exit={{ height: 0, opacity: 0 }} className="overflow-hidden pt-4">
                    {editMode ? (
                      <textarea className="textarea h-32 font-mono text-xs w-full" value={form.identity} onChange={e => setForm({...form, identity: e.target.value})} />
                    ) : (
                      <div className="font-mono text-sm leading-relaxed text-secondary">{form.identity}</div>
                    )}
                  </motion.div>
                )}
              </AnimatePresence>
            </HudPanel>

            <HudPanel className="border-amber">
              <div 
                onClick={() => toggleSection('mission')}
                className="flex items-center justify-between gap-3 text-amber border-b border-border-color pb-2 cursor-pointer select-none"
              >
                <div className="flex items-center gap-2">
                  <Target size={16} /> <span className="font-display text-lg uppercase tracking-widest font-bold">MISSION</span>
                </div>
                <div className="flex items-center gap-2">
                  {!openSections.mission && !editMode && (
                    <span className="font-mono text-[10px] text-muted truncate max-w-[140px] hidden sm:inline-block">
                      {form.mission}
                    </span>
                  )}
                  <button type="button" className="p-1 text-muted hover:text-amber transition-colors shrink-0">
                    {openSections.mission || editMode ? <ChevronUp size={18} /> : <ChevronDown size={18} />}
                  </button>
                </div>
              </div>
              <AnimatePresence>
                {(openSections.mission || editMode) && (
                  <motion.div initial={{ height: 0, opacity: 0 }} animate={{ height: 'auto', opacity: 1 }} exit={{ height: 0, opacity: 0 }} className="overflow-hidden pt-4">
                    {editMode ? (
                      <textarea className="textarea h-48 font-mono text-xs w-full" value={form.mission} onChange={e => setForm({...form, mission: e.target.value})} />
                    ) : (
                      <div className="font-mono text-sm leading-relaxed text-primary bg-amber/5 p-3 rounded border border-amber/20">{form.mission}</div>
                    )}
                  </motion.div>
                )}
              </AnimatePresence>
            </HudPanel>

            <HudPanel className="border-border-color">
              <div 
                onClick={() => toggleSection('endgame')}
                className="flex items-center justify-between gap-3 text-muted border-b border-border-color pb-2 cursor-pointer select-none"
              >
                <div className="flex items-center gap-2">
                  <Eye size={16} /> <span className="font-display text-lg uppercase tracking-widest font-bold">5-YEAR ENDGAME</span>
                </div>
                <div className="flex items-center gap-2">
                  {!openSections.endgame && !editMode && (
                    <span className="font-mono text-[10px] text-muted truncate max-w-[140px] hidden sm:inline-block">
                      {form.future_vision}
                    </span>
                  )}
                  <button type="button" className="p-1 text-muted hover:text-primary transition-colors shrink-0">
                    {openSections.endgame || editMode ? <ChevronUp size={18} /> : <ChevronDown size={18} />}
                  </button>
                </div>
              </div>
              <AnimatePresence>
                {(openSections.endgame || editMode) && (
                  <motion.div initial={{ height: 0, opacity: 0 }} animate={{ height: 'auto', opacity: 1 }} exit={{ height: 0, opacity: 0 }} className="overflow-hidden pt-4">
                    {editMode ? (
                      <textarea className="textarea h-48 font-mono text-xs w-full" value={form.future_vision} onChange={e => setForm({...form, future_vision: e.target.value})} />
                    ) : (
                      <div className="font-mono text-xs leading-relaxed text-secondary whitespace-pre-wrap">{form.future_vision}</div>
                    )}
                  </motion.div>
                )}
              </AnimatePresence>
            </HudPanel>
          </div>



          {/* ── COLUMN 3: INTEL & SYSTEM SENTINELS ── */}
          <div className="flex flex-col gap-6">
            {/* Known Advantages */}
            <HudPanel className="border-success">
              <div 
                onClick={() => toggleSection('advantages')}
                className="flex items-center justify-between gap-3 text-success border-b border-border-color pb-2 cursor-pointer select-none"
              >
                <div className="flex items-center gap-2">
                  <Shield size={16} /> <span className="font-display text-lg uppercase tracking-widest font-bold">KNOWN ADVANTAGES</span>
                </div>
                <div className="flex items-center gap-2">
                  {!openSections.advantages && !editMode && (
                    <span className="font-mono text-[10px] text-muted truncate max-w-[120px] hidden sm:inline-block">
                      {form.strengths.split('\n').filter(Boolean).length} ADVANTAGES
                    </span>
                  )}
                  <button type="button" className="p-1 text-muted hover:text-success transition-colors shrink-0">
                    {openSections.advantages || editMode ? <ChevronUp size={18} /> : <ChevronDown size={18} />}
                  </button>
                </div>
              </div>
              <AnimatePresence>
                {(openSections.advantages || editMode) && (
                  <motion.div initial={{ height: 0, opacity: 0 }} animate={{ height: 'auto', opacity: 1 }} exit={{ height: 0, opacity: 0 }} className="overflow-hidden pt-4">
                    {editMode ? (
                      <textarea className="textarea h-40 font-mono text-xs w-full" value={form.strengths} onChange={e => setForm({...form, strengths: e.target.value})} />
                    ) : (
                      <ul className="flex flex-col gap-2 font-mono text-xs text-secondary">
                        {form.strengths.split('\n').filter(Boolean).map((s, i) => (
                          <li key={i} className="flex gap-2 p-2 border border-border-color bg-tertiary rounded"><span className="text-success">■</span> {s}</li>
                        ))}
                      </ul>
                    )}
                  </motion.div>
                )}
              </AnimatePresence>
            </HudPanel>

            {/* Vulnerabilities */}
            <HudPanel className="border-danger">
              <div 
                onClick={() => toggleSection('vulnerabilities')}
                className="flex items-center justify-between gap-3 text-danger border-b border-border-color pb-2 cursor-pointer select-none"
              >
                <div className="flex items-center gap-2">
                  <AlertTriangle size={16} /> <span className="font-display text-lg uppercase tracking-widest font-bold">VULNERABILITIES</span>
                </div>
                <div className="flex items-center gap-2">
                  {!openSections.vulnerabilities && !editMode && (
                    <span className="font-mono text-[10px] text-muted truncate max-w-[120px] hidden sm:inline-block">
                      {form.weaknesses.split('\n').filter(Boolean).length} THREATS
                    </span>
                  )}
                  <button type="button" className="p-1 text-muted hover:text-danger transition-colors shrink-0">
                    {openSections.vulnerabilities || editMode ? <ChevronUp size={18} /> : <ChevronDown size={18} />}
                  </button>
                </div>
              </div>
              <AnimatePresence>
                {(openSections.vulnerabilities || editMode) && (
                  <motion.div initial={{ height: 0, opacity: 0 }} animate={{ height: 'auto', opacity: 1 }} exit={{ height: 0, opacity: 0 }} className="overflow-hidden pt-4">
                    {editMode ? (
                      <textarea className="textarea h-40 font-mono text-xs w-full" value={form.weaknesses} onChange={e => setForm({...form, weaknesses: e.target.value})} />
                    ) : (
                      <ul className="flex flex-col gap-2 font-mono text-xs text-secondary">
                        {form.weaknesses.split('\n').filter(Boolean).map((w, i) => (
                          <li key={i} className="flex gap-2 p-2 border border-border-color bg-tertiary rounded"><span className="text-danger">■</span> {w}</li>
                        ))}
                      </ul>
                    )}
                  </motion.div>
                )}
              </AnimatePresence>
            </HudPanel>

            {/* The Code */}
            <HudPanel glow className="border-amber">
              <div 
                onClick={() => toggleSection('code')}
                className="flex items-center justify-between gap-3 text-amber border-b border-border-color pb-2 cursor-pointer select-none"
              >
                <div className="flex items-center gap-2">
                  <Flame size={16} /> <span className="font-display text-lg uppercase tracking-widest font-bold">THE CODE (NON-NEGOTIABLES)</span>
                </div>
                <div className="flex items-center gap-2">
                  {!openSections.code && !editMode && (
                    <span className="font-mono text-[10px] text-muted truncate max-w-[120px] hidden sm:inline-block">
                      {form.values_list.split('\n').filter(Boolean).length} RULES
                    </span>
                  )}
                  <button type="button" className="p-1 text-muted hover:text-amber transition-colors shrink-0">
                    {openSections.code || editMode ? <ChevronUp size={18} /> : <ChevronDown size={18} />}
                  </button>
                </div>
              </div>
              <AnimatePresence>
                {(openSections.code || editMode) && (
                  <motion.div initial={{ height: 0, opacity: 0 }} animate={{ height: 'auto', opacity: 1 }} exit={{ height: 0, opacity: 0 }} className="overflow-hidden pt-4">
                    {editMode ? (
                      <textarea className="textarea h-40 font-mono text-xs w-full" value={form.values_list} onChange={e => setForm({...form, values_list: e.target.value})} />
                    ) : (
                      <ul className="flex flex-col gap-3 font-mono text-xs text-primary">
                        {form.values_list.split('\n').filter(Boolean).map((v, i) => (
                          <li key={i} className="flex gap-2 p-2 border border-border-color bg-tertiary rounded">
                            <span className="text-amber">{String(i+1).padStart(2, '0')}</span> {v}
                          </li>
                        ))}
                      </ul>
                    )}
                  </motion.div>
                )}
              </AnimatePresence>
            </HudPanel>
          </div>

        </div>
      </div>

    </AppShell>
  )
}

