'use client'

import { useState, useEffect } from 'react'

export default function TypewriterText({ text, speed = 40, className = '', onComplete }) {
  const [displayed, setDisplayed] = useState('')
  const [index, setIndex] = useState(0)
  const [complete, setComplete] = useState(false)

  useEffect(() => {
    setDisplayed('')
    setIndex(0)
    setComplete(false)
  }, [text])

  useEffect(() => {
    if (index < text.length) {
      const timer = setTimeout(() => {
        setDisplayed(prev => prev + text[index])
        setIndex(i => i + 1)
      }, speed)
      return () => clearTimeout(timer)
    } else if (!complete && text.length > 0) {
      setComplete(true)
      onComplete?.()
    }
  }, [index, text, speed, complete, onComplete])

  return (
    <span className={`typewriter-text ${className}`} style={{ fontFamily: 'var(--font-mono)' }}>
      {displayed}
      {!complete && <span className="typewriter-cursor">█</span>}
    </span>
  )
}

'use client'

import React, { createContext, useContext, useEffect, useState, useCallback, useMemo, useRef } from 'react'
import { useAuth } from '@/lib/hooks/useAuth'
import { createClient } from '@/lib/supabase/client'
import { getLocalDateStr } from '@/lib/utils/dates'
import { useHabitsInternal } from '@/lib/hooks/useHabitsInternal'
import { useTasksInternal } from '@/lib/hooks/useTasksInternal'
import { useGoalsInternal } from '@/lib/hooks/useGoalsInternal'
import { useXPInternal } from '@/lib/hooks/useXPInternal'
import { useBrainDumpInternal } from '@/lib/hooks/useBrainDumpInternal'
import { useJournalInternal } from '@/lib/hooks/useJournalInternal'
import { useProfileInternal } from '@/lib/hooks/useProfileInternal'
import { useCalendarInternal } from '@/lib/hooks/useCalendarInternal'
import { useCharacterStatsInternal } from '@/lib/hooks/useCharacterStatsInternal'
import { useFocusInternal } from '@/lib/hooks/useFocusInternal'
import { getThemeForXP } from '@/lib/theme/levelTheme'

const OSContext = createContext(null)

export function OSProvider({ children }) {
  const auth = useAuth()
  
  // Initialize all subsystems exactly once at the root level, passing down the single shared auth.user
  const habits = useHabitsInternal(auth.user)
  const tasks = useTasksInternal(auth.user)
  const goals = useGoalsInternal(auth.user)
  const xp = useXPInternal(auth.user)
  const brainDump = useBrainDumpInternal(auth.user)
  const journal = useJournalInternal(auth.user)
  const profile = useProfileInternal(auth.user)
  const calendar = useCalendarInternal(auth.user)
  const characterStats = useCharacterStatsInternal(auth.user)
  const focus = useFocusInternal(auth.user, true)

  const [booting, setBooting] = useState(true)

  // Apply rank-derived visual tokens only. XP remains owned by existing profile/RPC flows.
  useEffect(() => {
    if (typeof document === 'undefined') return
    const theme = getThemeForXP(profile?.profile?.total_xp || 0)
    Object.entries(theme.cssVars).forEach(([name, value]) => document.documentElement.style.setProperty(name, value))
  }, [profile?.profile?.total_xp])

  // Wait for critical systems to load before rendering the OS
  useEffect(() => {
    if (!auth.loading && !profile.loading && !habits.loading && !tasks.loading) {
      setBooting(false)
    }
  }, [auth.loading, profile.loading, habits.loading, tasks.loading])

  // Stable refs so the sync callback always calls the latest functions
  // without causing the useEffect to re-run (infinite loop fix)
  const profileRef = React.useRef(profile)
  const xpRef = React.useRef(xp)
  const habitsRef = React.useRef(habits)
  const tasksRef = React.useRef(tasks)
  useEffect(() => {
    profileRef.current = profile
    xpRef.current = xp
    habitsRef.current = habits
    tasksRef.current = tasks
  }, [profile, xp, habits, tasks])

  // Cross-device sync: Supabase Realtime + window focus/visibility
  useEffect(() => {
    if (!auth?.user?.id) return
    const supabase = createClient()
    const userId = auth.user.id
    
    let syncTimeout = null
    const debouncedSync = () => {
      if (syncTimeout) clearTimeout(syncTimeout)
      syncTimeout = setTimeout(() => {
        profileRef.current?.fetchProfile?.()
        habitsRef.current?.fetchHabits?.()
        tasksRef.current?.fetchTasks?.()
      }, 500)
    }

    let xpSyncTimeout = null
    const debouncedXpSync = () => {
      if (xpSyncTimeout) clearTimeout(xpSyncTimeout)
      xpSyncTimeout = setTimeout(() => {
        profileRef.current?.fetchProfile?.()
        xpRef.current?.fetchMomentum?.()
      }, 300)
    }

    const channel = supabase.channel(`os_sync_${userId}`)
      .on('postgres_changes', { event: '*', schema: 'public', table: 'tasks', filter: `user_id=eq.${userId}` }, debouncedSync)
      .on('postgres_changes', { event: '*', schema: 'public', table: 'work_logs', filter: `user_id=eq.${userId}` }, debouncedSync)
      .on('postgres_changes', { event: '*', schema: 'public', table: 'speaking_logs', filter: `user_id=eq.${userId}` }, debouncedSync)
      .on('postgres_changes', { event: '*', schema: 'public', table: 'work_hours_logs', filter: `user_id=eq.${userId}` }, debouncedSync)
      .on('postgres_changes', { event: '*', schema: 'public', table: 'habits', filter: `user_id=eq.${userId}` }, debouncedSync)
      .on('postgres_changes', { event: '*', schema: 'public', table: 'habit_logs', filter: `user_id=eq.${userId}` }, debouncedSync)
      .on('postgres_changes', { event: '*', schema: 'public', table: 'screen_time_logs', filter: `user_id=eq.${userId}` }, debouncedSync)
      .on('postgres_changes', { event: '*', schema: 'public', table: 'xp_history', filter: `user_id=eq.${userId}` }, (payload) => {
        if (payload.eventType === 'INSERT') {
          xpRef.current?.handleXpRealtime?.(payload)
        }
        debouncedXpSync()
      })
      .on('postgres_changes', { event: '*', schema: 'public', table: 'profiles', filter: `id=eq.${userId}` }, debouncedSync)
      .subscribe()

    const handleVisibility = () => {
      if (document.visibilityState === 'visible') debouncedSync()
    }
    window.addEventListener('focus', debouncedSync)
    document.addEventListener('visibilitychange', handleVisibility)

    return () => {
      if (syncTimeout) clearTimeout(syncTimeout)
      supabase.removeChannel(channel)
      window.removeEventListener('focus', debouncedSync)
      document.removeEventListener('visibilitychange', handleVisibility)
    }
  }, [auth?.user?.id])

  // Cross-Domain Orchestration Methods
  const completeOperation = useCallback(async (taskId, proofUrl = null, completionNote = null) => {
    // 1. Complete the underlying task
    const updatedTask = await tasks.completeTask(taskId, proofUrl, completionNote)

    // 2. If it belongs to a Mission (Goal), automate mission progress
    const task = updatedTask || tasks.tasks.find(t => t.id === taskId)
    if (task && task.goal_id) {
      const goal = goals.goals.find(g => g.id === task.goal_id)
      if (goal && goal.status !== 'completed') {
        const goalTasks = tasks.tasks.filter(t => t.goal_id === task.goal_id)
        const completedGoalTasks = goalTasks.filter(t => t.status === 'completed' || t.id === taskId).length
        const totalGoalTasks = goalTasks.length || 1
        
        const newProgress = Math.min(100, Math.round((completedGoalTasks / totalGoalTasks) * 100))
        await goals.updateProgress(goal.id, newProgress)
      }
    }
    return updatedTask
  }, [tasks, goals, xp])
  
  const deleteOperation = useCallback(async (taskId, revokeXp = true) => {
    const task = tasks.tasks.find(t => t.id === taskId)
    if (!task) return false
    
    const success = await tasks.deleteTask(taskId, revokeXp)
    if (success && task.goal_id) {
      const goal = goals.goals.find(g => g.id === task.goal_id)
      if (goal && goal.status !== 'completed') {
        const goalTasks = tasks.tasks.filter(t => t.goal_id === task.goal_id && t.id !== taskId)
        const completedGoalTasks = goalTasks.filter(t => t.status === 'completed').length
        const totalGoalTasks = goalTasks.length || 1
        
        const newProgress = Math.min(100, Math.round((completedGoalTasks / totalGoalTasks) * 100))
        await goals.updateProgress(goal.id, newProgress)
      }
    }
    if (success) {
      await profile.fetchProfile() // Refresh XP immediately
    }
    return success
  }, [tasks, goals, profile])

  const failOperation = useCallback(async (taskId, failureReason = null) => {
    const result = await tasks.failTask(taskId, failureReason)
    if (result) {
      await profile.fetchProfile() // Refresh XP immediately
    }
    return result
  }, [tasks, profile])

  const undoFailOperation = useCallback(async (taskId) => {
    const result = await tasks.undoFailTask(taskId)
    if (result) {
      await profile.fetchProfile() // Refresh XP immediately
    }
    return result
  }, [tasks, profile])

  const failMission = useCallback(async (goalId) => {
    const result = await goals.failGoal(goalId)
    if (result) {
      await profile.fetchProfile() // Refresh XP immediately
    }
    return result
  }, [goals, profile])

  const deleteMission = useCallback(async (goalId, revokeXp = true) => {
    const result = await goals.deleteGoal(goalId, revokeXp)
    if (result) {
      await profile.fetchProfile() // Refresh XP immediately
    }
    return result
  }, [goals, profile])

  const undoFailMission = useCallback(async (goalId) => {
    const result = await goals.undoFailGoal(goalId)
    if (result) {
      await profile.fetchProfile() // Refresh XP immediately
    }
    return result
  }, [goals, profile])

  const osState = useMemo(() => ({
    auth,
    habits,
    tasks,
    goals,
    focus,
    xp,
    brainDump,
    journal,
    profile,
    calendar,
    characterStats,
    completeOperation,
    deleteOperation,
    failOperation,
    undoFailOperation,
    failMission,
    deleteMission,
    undoFailMission,
  }), [
    auth,
    habits,
    tasks,
    goals,
    focus,
    xp,
    brainDump,
    journal,
    profile,
    calendar,
    characterStats,
    completeOperation,
    deleteOperation,
    failOperation,
    undoFailOperation,
    failMission,
    deleteMission,
    undoFailMission,
  ])

  if (booting) {
    return (
      <div className="winter-boot-screen">
        <div className="winter-boot-grid" aria-hidden="true" />
        <div className="winter-boot-mark">
          <img src="/icons/winter-warrior-logo.png" alt="Winter Arc warrior" />
        </div>
        <div className="winter-boot-kicker">LOKI OS // WINTER ARC</div>
        <div className="winter-boot-title">THE FROST FORGE</div>
        <div className="winter-boot-status"><span /> INITIALIZING FIELD SYSTEMS</div>
      </div>
    )
  }

  return (
    <OSContext.Provider value={osState}>
      {children}
    </OSContext.Provider>
  )
}

export function useOS() {
  const context = useContext(OSContext)
  if (!context) {
    throw new Error('useOS must be used within an OSProvider')
  }
  return context
}

'use client'

import { useState, useEffect, useCallback } from 'react'
import { createClient } from '@/lib/supabase/client'
import { XP_REWARDS } from '@/lib/constants'

// 10-color palette for topics
export const TOPIC_COLORS = [
  { name: 'Cyan',   value: '#22d3ee' },
  { name: 'Amber',  value: '#f59e0b' },
  { name: 'Purple', value: '#a855f7' },
  { name: 'Green',  value: '#22c55e' },
  { name: 'Red',    value: '#ef4444' },
  { name: 'Sky',    value: '#38bdf8' },
  { name: 'Pink',   value: '#ec4899' },
  { name: 'Yellow', value: '#eab308' },
  { name: 'Slate',  value: '#94a3b8' },
  { name: 'Bronze', value: '#cd7f32' },
]

export const DEFAULT_TOPICS = [
  { name: 'General',       color: '#94a3b8' },
  { name: 'Startup Ideas', color: '#22d3ee' },
  { name: 'Business',      color: '#f59e0b' },
  { name: 'Health',        color: '#22c55e' },
  { name: 'Learning',      color: '#38bdf8' },
]

export function getTopicColor(topicName) {
  if (!topicName) return '#94a3b8'
  const match = DEFAULT_TOPICS.find(t => t.name.toLowerCase() === topicName.toLowerCase())
  if (match) return match.color

  let hash = 0
  for (let i = 0; i < topicName.length; i++) {
    hash = topicName.charCodeAt(i) + ((hash << 5) - hash)
  }
  const idx = Math.abs(hash) % TOPIC_COLORS.length
  return TOPIC_COLORS[idx].value
}

export function useBrainDumpInternal(user) {
  const [items, setItems]   = useState([])
  const [topics, setTopics] = useState(DEFAULT_TOPICS)
  const [loading, setLoading] = useState(true)
  const supabase = createClient()

  // ── Fetch items ──────────────────────────────────────────────────────────
  const fetchItems = useCallback(async () => {
    if (!user) { setItems([]); setLoading(false); return }
    try {
      setLoading(true)
      const { data, error } = await supabase
        .from('brain_dump')
        .select('*')
        .eq('user_id', user.id)
        .order('created_at', { ascending: false })
      if (error) throw error
      setItems(data || [])

      // Derive unique topics from existing data and merge with defaults
      const existingTopics = Array.from(
        new Set((data || []).map(i => i.topic || (i.type && !['note', 'thought', 'idea', 'task', 'goal', 'random'].includes(i.type) ? i.type : null) || 'General'))
      ).map(name => ({ name, color: getTopicColor(name) }))

      const merged = [...DEFAULT_TOPICS]
      existingTopics.forEach(et => {
        if (!merged.find(m => m.name === et.name)) merged.push(et)
      })
      setTopics(merged)
    } catch (err) {
      console.error('Error fetching brain dump:', err)
    } finally {
      setLoading(false)
    }
  }, [user])

  useEffect(() => { fetchItems() }, [fetchItems])

  // ── Add item ─────────────────────────────────────────────────────────────
  const addItem = useCallback(async (content, topic = 'General') => {
    if (!user) return { error: 'User not authenticated' }
    try {
      const topicName = topic || 'General'
      const payload = {
        user_id: user.id,
        content,
        topic: topicName,
        type: 'note',
        status: 'inbox'
      }

      let newItem = null
      let { data, error } = await supabase
        .from('brain_dump')
        .insert(payload)
        .select()
        .single()

      if (error) {
        // Fallback 1: If 'topic' column is not in DB yet
        if (error.code === '42703' || error.message?.includes('topic')) {
          delete payload.topic
          const retry = await supabase.from('brain_dump').insert(payload).select().single()
          if (retry.error) throw retry.error
          newItem = retry.data
        } 
        // Fallback 2: If type check constraint fails ('brain_dump_type_check')
        else if (error.code === '23514' || error.message?.includes('brain_dump_type_check')) {
          const fallbackTypes = ['thought', 'idea', 'task', 'goal', 'random']
          let success = false
          for (const ft of fallbackTypes) {
            payload.type = ft
            const retry = await supabase.from('brain_dump').insert(payload).select().single()
            if (!retry.error) {
              newItem = retry.data
              success = true
              break
            }
          }
          if (!success) {
            delete payload.type
            const retry = await supabase.from('brain_dump').insert(payload).select().single()
            if (retry.error) throw retry.error
            newItem = retry.data
          }
        } else {
          throw error
        }
      } else {
        newItem = data
      }

      if (newItem) {
        if (!newItem.topic) newItem.topic = topicName
        setItems(prev => [newItem, ...prev])
        setTopics(prev => prev.find(t => t.name === topicName) ? prev : [...prev, { name: topicName, color: getTopicColor(topicName) }])

        try {
          await supabase.rpc('award_xp', {
            p_user_id: user.id,
            p_amount: XP_REWARDS.brain_dump_capture || 5,
            p_source_type: 'brain_dump',
            p_source_id: newItem.id,
            p_description: `Intel Drop: ${topicName}`,
            p_stat_category: 'discipline',
          })
        } catch (xpErr) {
          console.warn('XP award warning:', xpErr)
        }
      }

      return { data: newItem }
    } catch (err) {
      console.error('Error adding brain dump item:', err)
      return { error: err }
    }
  }, [user])

  // ── Mark Done ────────────────────────────────────────────────────────────
  const doneItem = useCallback(async (id) => {
    if (!user) return { error: 'User not authenticated' }
    try {
      let updated = null
      let { data, error } = await supabase
        .from('brain_dump')
        .update({ status: 'done', done_at: new Date().toISOString() })
        .eq('id', id).eq('user_id', user.id)
        .select().single()

      if (error) {
        if (error.code === '23514' || error.message?.includes('brain_dump_status_check')) {
          const retry = await supabase
            .from('brain_dump')
            .update({ status: 'organized' })
            .eq('id', id).eq('user_id', user.id)
            .select().single()
          if (retry.error) throw retry.error
          updated = retry.data
        } else {
          throw error
        }
      } else {
        updated = data
      }

      if (updated) {
        setItems(prev => prev.map(i => i.id === id ? updated : i))
      }
      return { data: updated }
    } catch (err) {
      console.error('Error marking done:', err)
      return { error: err }
    }
  }, [user])

  // ── Discard (soft) ───────────────────────────────────────────────────────
  const discardItem = useCallback(async (id) => {
    if (!user) return false
    try {
      const { data: updated, error } = await supabase
        .from('brain_dump')
        .update({ status: 'discarded' })
        .eq('id', id).eq('user_id', user.id)
        .select().single()
      if (error) throw error
      setItems(prev => prev.map(i => i.id === id ? updated : i))
      return true
    } catch (err) {
      console.error('Error discarding item:', err)
      return false
    }
  }, [user])

  // ── Restore to inbox ─────────────────────────────────────────────────────
  const restoreItem = useCallback(async (id) => {
    if (!user) return false
    try {
      const { data: updated, error } = await supabase
        .from('brain_dump')
        .update({ status: 'inbox', done_at: null })
        .eq('id', id).eq('user_id', user.id)
        .select().single()
      if (error) throw error
      setItems(prev => prev.map(i => i.id === id ? updated : i))
      return true
    } catch (err) {
      console.error('Error restoring item:', err)
      return false
    }
  }, [user])

  // ── Delete Forever ───────────────────────────────────────────────────────
  const deleteItem = useCallback(async (id) => {
    if (!user) return false
    try {
      const { error } = await supabase
        .from('brain_dump').delete().eq('id', id).eq('user_id', user.id)
      if (error) throw error
      setItems(prev => prev.filter(i => i.id !== id))
      return true
    } catch (err) {
      console.error('Error deleting item:', err)
      return false
    }
  }, [user])

  // ── Convert to Mission (Goal) ────────────────────────────────────────────
  const convertToMission = useCallback(async (id) => {
    if (!user) return null
    try {
      const item = items.find(i => i.id === id)
      if (!item) return null
      const { data, error } = await supabase
        .from('goals')
        .insert({ user_id: user.id, title: item.content, type: 'side_quest' })
        .select().single()
      if (error) throw error

      await doneItem(id)
      return { data }
    } catch (err) {
      console.error('Error converting to mission:', err)
      return { error: err }
    }
  }, [user, items, doneItem])

  // ── Rename topic ─────────────────────────────────────────────────────────
  const renameTopic = useCallback(async (oldName, newName) => {
    if (!user || !newName.trim()) return
    try {
      const { error } = await supabase
        .from('brain_dump')
        .update({ topic: newName })
        .eq('user_id', user.id)
        .eq('topic', oldName)
      if (error) console.warn('Topic update warning:', error)
      setTopics(prev => prev.map(t => t.name === oldName ? { ...t, name: newName } : t))
      setItems(prev => prev.map(i => i.topic === oldName ? { ...i, topic: newName } : i))
    } catch (err) {
      console.error('Error renaming topic:', err)
    }
  }, [user])

  // ── Delete topic ─────────────────────────────────────────────────────────
  const deleteTopic = useCallback(async (topicName) => {
    if (!user) return
    try {
      const { error } = await supabase
        .from('brain_dump')
        .update({ topic: 'General' })
        .eq('user_id', user.id)
        .eq('topic', topicName)
      if (error) console.warn('Topic delete warning:', error)
      setTopics(prev => prev.filter(t => t.name !== topicName))
      setItems(prev => prev.map(i => i.topic === topicName ? { ...i, topic: 'General' } : i))
    } catch (err) {
      console.error('Error deleting topic:', err)
    }
  }, [user])

  return {
    items, topics, loading,
    addItem, doneItem, discardItem, restoreItem, deleteItem,
    convertToMission, renameTopic, deleteTopic,
    organizeItem: doneItem,
  }
}

'use client'

import { useState, useEffect, useCallback } from 'react'
import { createClient } from '@/lib/supabase/client'

export function useCalendarInternal(user, year = new Date().getFullYear(), month = new Date().getMonth()) {
  const [events, setEvents] = useState([])
  const [loading, setLoading] = useState(true)
  const [initialized, setInitialized] = useState(false)
  const supabase = createClient()

  const fetchEvents = useCallback(async () => {
    if (!user) {
      setEvents([])
      setLoading(false)
      return
    }

    try {
      if (!initialized) setLoading(true)

      // Build date range for the given month
      const startDate = new Date(year, month, 1).toISOString()
      const endDate = new Date(year, month + 1, 0, 23, 59, 59).toISOString()

      const { data, error } = await supabase
        .from('calendar_events')
        .select('*')
        .eq('user_id', user.id)
        .gte('start_time', startDate)
        .lte('start_time', endDate)
        .order('start_time', { ascending: true })

      if (error) throw error
      setEvents(data || [])
    } catch (error) {
      console.error('Error fetching calendar events:', error)
    } finally {
      setLoading(false)
      setInitialized(true)
    }
  }, [user, year, month, initialized])

  useEffect(() => {
    fetchEvents()
  }, [fetchEvents])

  const addEvent = useCallback(async (data) => {
    if (!user) return null

    try {
      const { data: newEvent, error } = await supabase
        .from('calendar_events')
        .insert({ ...data, user_id: user.id })
        .select()
        .single()

      if (error) throw error
      setEvents((prev) => [...prev, newEvent].sort(
        (a, b) => new Date(a.start_time) - new Date(b.start_time)
      ))
      return newEvent
    } catch (error) {
      console.error('Error adding calendar event:', error)
      return null
    }
  }, [user])

  const updateEvent = useCallback(async (id, data) => {
    if (!user) return null

    try {
      const { data: updated, error } = await supabase
        .from('calendar_events')
        .update(data)
        .eq('id', id)
        .eq('user_id', user.id)
        .select()
        .single()

      if (error) throw error
      setEvents((prev) =>
        prev
          .map((e) => (e.id === id ? updated : e))
          .sort((a, b) => new Date(a.start_time) - new Date(b.start_time))
      )
      return updated
    } catch (error) {
      console.error('Error updating calendar event:', error)
      return null
    }
  }, [user])

  const deleteEvent = useCallback(async (id) => {
    if (!user) return false

    try {
      const { error } = await supabase
        .from('calendar_events')
        .delete()
        .eq('id', id)
        .eq('user_id', user.id)

      if (error) throw error
      setEvents((prev) => prev.filter((e) => e.id !== id))
      return true
    } catch (error) {
      console.error('Error deleting calendar event:', error)
      return false
    }
  }, [user])

  return { events, loading, addEvent, updateEvent, deleteEvent }
}

'use client'

import { useState, useEffect, useRef, useCallback } from 'react'
import { createClient } from '@/lib/supabase/client'
import { getLocalDateStr } from '@/lib/utils/dates'

export const PRESETS = [
  { label: '15 MIN', mins: 15 },
  { label: '25 MIN', mins: 25 },
  { label: '45 MIN', mins: 45 },
  { label: '60 MIN', mins: 60 },
  { label: 'CUSTOM', mins: null },
]

export const CATEGORIES = [
  { id: 'beyond_tatva', label: 'Beyond Tatva', color: '#d4a843', stat: 'founder' },
  { id: 'learning', label: 'Learning', color: '#3498db', stat: 'learning' },
  { id: 'fitness', label: 'Fitness', color: '#2ecc71', stat: 'strength' },
  { id: 'personal', label: 'Personal', color: '#9b59b6', stat: 'discipline' },
  { id: 'communication', label: 'Communication', color: '#e67e22', stat: 'communication' },
  { id: 'creation', label: 'Creation', color: '#e74c3c', stat: 'creation' },
]

export function useFocusInternal(user, initialized) {
  // ── Setup State (before session) ──
  const [phase, setPhase] = useState('setup') // 'setup' | 'running' | 'done'
  const [selectedPreset, setSelectedPreset] = useState(1) // index into PRESETS (25 min default)
  const [customMins, setCustomMins] = useState(30)
  const [taskName, setTaskName] = useState('')
  const [category, setCategory] = useState(CATEGORIES[0])
  const [saving, setSaving] = useState(false)

  // ── Timer State ──
  const [totalSeconds, setTotalSeconds] = useState(25 * 60)
  const [timeLeft, setTimeLeft] = useState(25 * 60)
  const [isActive, setIsActive] = useState(false)
  const intervalRef = useRef(null)

  // ── Session Result ──
  const [sessionXp, setSessionXp] = useState(0)
  const [aborted, setAborted] = useState(false)

  // Sync timer when preset changes (only in setup phase)
  useEffect(() => {
    if (phase !== 'setup') return
    const preset = PRESETS[selectedPreset]
    if (preset.mins !== null) {
      const secs = preset.mins * 60
      setTotalSeconds(secs)
      setTimeLeft(secs)
    } else {
      const secs = Math.max(1, Math.min(180, customMins)) * 60
      setTotalSeconds(secs)
      setTimeLeft(secs)
    }
  }, [selectedPreset, customMins, phase])

  // Tick
  useEffect(() => {
    if (isActive && timeLeft > 0) {
      intervalRef.current = setInterval(() => setTimeLeft(t => t - 1), 1000)
    } else {
      clearInterval(intervalRef.current)
    }
    if (timeLeft === 0 && isActive) {
      setIsActive(false)
      handleComplete(false) // Timer ran out naturally — full completion
    }
    return () => clearInterval(intervalRef.current)
  }, [isActive, timeLeft])

  // ── Start Session ──
  const startSession = useCallback(() => {
    setPhase('running')
    setIsActive(true)
  }, [])

  // ── Complete Session (called when timer hits 0 OR user clicks "Complete") ──
  const handleComplete = useCallback(async (earlyComplete = false) => {
    if (saving || !user) return
    setSaving(true)
    setIsActive(false)
    clearInterval(intervalRef.current)

    try {
      const elapsed = totalSeconds - timeLeft // seconds actually worked
      const elapsedMins = Math.floor(elapsed / 60)
      const durationHours = elapsed / 3600

      // XP rule: +10 XP base per session, +1 XP per every 5 minutes of focus (min 10)
      const xpEarned = Math.max(10, 10 + Math.floor(elapsedMins / 5))

      const supabase = createClient()
      if (elapsed > 60) { // Only log if at least 1 minute worked
        await supabase.from('work_logs').insert([{
          user_id: user.id,
          title: taskName || 'FOCUS SESSION',
          type: 'project_work',
          description: `Deep Focus: ${category.label} — ${elapsedMins} min`,
          date: getLocalDateStr(),
          duration: durationHours.toFixed(2),
          duration_unit: 'hours',
        }])
        setSessionXp(xpEarned)
      }
      setAborted(false)
      setPhase('done')
    } catch (err) {
      console.error('Focus save error:', err)
    } finally {
      setSaving(false)
    }
  }, [saving, user, totalSeconds, timeLeft, taskName, category])

  // ── Abort Session (early quit with penalty) ──
  const handleAbort = useCallback(async () => {
    if (!confirm('Abort focus session? You will lose this session\'s progress.')) return
    setSaving(true)
    setIsActive(false)
    clearInterval(intervalRef.current)

    try {
      setAborted(true)
      setPhase('done')
    } catch (err) {
      console.error('Abort error:', err)
    } finally {
      setSaving(false)
    }
  }, [user])

  const resetTimer = useCallback(() => {
    setPhase('setup')
    const secs = PRESETS[selectedPreset].mins !== null ? PRESETS[selectedPreset].mins * 60 : customMins * 60
    setTotalSeconds(secs)
    setTimeLeft(secs)
    setSessionXp(0)
    setAborted(false)
  }, [selectedPreset, customMins])

  return {
    phase, setPhase,
    selectedPreset, setSelectedPreset,
    customMins, setCustomMins,
    taskName, setTaskName,
    category, setCategory,
    saving,
    totalSeconds,
    timeLeft, setTimeLeft,
    isActive, setIsActive,
    sessionXp,
    aborted,
    startSession,
    handleComplete,
    handleAbort,
    resetTimer
  }
}

'use client'

import { useState, useEffect, useCallback, useMemo } from 'react'
import { createClient } from '@/lib/supabase/client'
import { XP_REWARDS } from '@/lib/constants'
import { robustAwardXP, robustRemoveXP } from '@/lib/utils/xpFallback'
import { getLocalDateStr } from '@/lib/utils/dates'

// Map goal/mission category IDs to canonical stat_category keys for XP radar and charts
const GOAL_CATEGORY_TO_STAT = {
  beyond_tatva: 'founder',
  founder: 'founder',
  personal_mission: 'discipline',
  discipline: 'discipline',
  learning: 'learning',
  communication: 'communication',
  creation: 'creation',
  other: 'creation',
  personal_care: 'creation',
  fitness: 'strength',
  strength: 'strength',
  weekly_goal: 'discipline',
}
const toStatCat = (cat) => GOAL_CATEGORY_TO_STAT[(cat || '').toLowerCase()] || 'discipline'

export function useGoalsInternal(user) {
  const [goals, setGoals] = useState([])
  const [loading, setLoading] = useState(true)
  const [initialized, setInitialized] = useState(false)
  const [error, setError] = useState(null)
  const supabase = createClient()

  const fetchGoals = useCallback(async () => {
    if (!user) {
      setGoals([])
      setLoading(false)
      return
    }

    try {
      if (!initialized) setLoading(true)
      setError(null)
      const { data, error } = await supabase
        .from('goals')
        .select('*')
        .eq('user_id', user.id)
        .order('created_at', { ascending: false })

      if (error) throw error
      setGoals(data || [])
    } catch (err) {
      console.error('Error fetching goals:', err)
      setError('Failed to load data. Please refresh and try again.')
    } finally {
      setLoading(false)
      setInitialized(true)
    }
  }, [user, initialized])

  useEffect(() => {
    fetchGoals()
  }, [fetchGoals])

  // Grouped goal views
  const mainQuests = useMemo(
    () => goals.filter((g) => g.type === 'main_quest' && g.status !== 'completed' && g.status !== 'cancelled' && g.status !== 'failed'),
    [goals]
  )

  const mainQuest = useMemo(
    () => mainQuests[0] || null,
    [mainQuests]
  )

  const sideQuests = useMemo(
    () => goals.filter((g) => g.type === 'side_quest' && g.status !== 'completed' && g.status !== 'cancelled' && g.status !== 'failed'),
    [goals]
  )

  const longTermGoals = useMemo(
    () => goals.filter((g) => g.type === 'long_term' && g.status !== 'completed' && g.status !== 'cancelled' && g.status !== 'failed'),
    [goals]
  )

  const weeklyGoals = useMemo(
    () => goals.filter((g) => g.type === 'weekly' && g.status !== 'completed' && g.status !== 'cancelled' && g.status !== 'failed'),
    [goals]
  )

  const completedGoals = useMemo(
    () => goals.filter((g) => g.status === 'completed'),
    [goals]
  )

  const failedGoals = useMemo(
    () => goals.filter((g) => g.status === 'cancelled' || g.status === 'failed'),
    [goals]
  )

  const addGoal = useCallback(async (data) => {
    if (!user) return null

    try {
      const { data: newGoal, error } = await supabase
        .from('goals')
        .insert({ ...data, user_id: user.id })
        .select()
        .single()

      if (error) throw error
      setGoals((prev) => [newGoal, ...prev])
      return { data: newGoal }
    } catch (error) {
      console.error('Error adding goal:', error)
      return { error }
    }
  }, [user])

  const updateGoal = useCallback(async (id, data) => {
    if (!user) return null

    try {
      const { data: updated, error } = await supabase
        .from('goals')
        .update(data)
        .eq('id', id)
        .eq('user_id', user.id)
        .select()
        .single()

      if (error) throw error
      setGoals((prev) => prev.map((g) => (g.id === id ? updated : g)))
      return updated
    } catch (error) {
      console.error('Error updating goal:', error)
      return null
    }
  }, [user])

  const completeGoal = useCallback(async (id, proofUrl = null, skipXp = false, completionNote = null) => {
    if (!user) return null

    try {
      const goal = goals.find((g) => g.id === id)
      if (!goal) return null

      const updates = { completed_at: new Date().toISOString(), progress: 100, status: 'completed' }
      if (completionNote && completionNote.trim()) {
        const currDesc = goal.description || ''
        const cleanNote = completionNote.trim()
        if (!currDesc.includes('[Completion Note]')) {
          updates.description = `${currDesc}\n\n[Completion Note]\n${cleanNote}`.trim()
        }
      }

      const { data: updated, error } = await supabase
        .from('goals')
        .update(updates)
        .eq('id', id)
        .eq('user_id', user.id)
        .select()
        .single()

      if (error) throw error

      if (proofUrl || (completionNote && completionNote.trim())) {
        // Auto-create Portfolio Log
        await supabase.from('work_logs').insert([{
          user_id: user.id,
          title: `Mission Accomplished: ${goal.title}`,
          description: completionNote ? completionNote.trim() : (goal.description || 'Completed Mission.'),
          type: 'other', // safe enum fallback
          date: getLocalDateStr(),
          media_urls: proofUrl ? [proofUrl] : []
        }])
      }

      if (!skipXp) {
        // Determine XP based on goal type
        const xpMap = {
          main_quest: XP_REWARDS.goal_complete_main,
          side_quest: XP_REWARDS.goal_complete_side,
          weekly: XP_REWARDS.goal_complete_weekly,
          long_term: XP_REWARDS.goal_complete_long_term,
        }
        let xpAmount = xpMap[goal.type] || XP_REWARDS.goal_complete_side

        // Check if overdue: -5 XP per calendar day past deadline (target_date or due_date or deadline)
        const deadline = goal.target_date || goal.due_date || goal.deadline
        let overdueDays = 0
        let penaltyDeduction = 0

        if (deadline) {
          const todayStr = getLocalDateStr()
          const cleanDeadline = deadline.substring(0, 10)
          if (cleanDeadline < todayStr) {
            const [tY, tM, tD] = todayStr.split('-').map(Number)
            const [dY, dM, dD] = cleanDeadline.split('-').map(Number)
            const todayUtc = Date.UTC(tY, tM - 1, tD)
            const dueUtc = Date.UTC(dY, dM - 1, dD)
            overdueDays = Math.max(1, Math.round((todayUtc - dueUtc) / (1000 * 60 * 60 * 24)))
            penaltyDeduction = overdueDays * 5
            xpAmount = Math.max(0, xpAmount - penaltyDeduction)
          }
        }

        const descText = overdueDays > 0 
          ? `Completed ${goal.type}: ${goal.title} (+${xpAmount} XP, -${penaltyDeduction} Overdue Penalty)`
          : `Completed ${goal.type}: ${goal.title}`

        await robustAwardXP(
          user.id,
          xpAmount,
          'goal_complete',
          id,
          descText,
          toStatCat(goal.category)
        )
      }

      setGoals((prev) => prev.map((g) => (g.id === id ? updated : g)))
      return updated
    } catch (error) {
      console.error('Error completing goal:', error)
      return null
    }
  }, [user, goals])

  const undoCompleteGoal = useCallback(async (id) => {
    if (!user) return null

    try {
      // Fetch tasks to calculate true progress
      const { data: goalTasks } = await supabase.from('tasks').select('status').eq('goal_id', id).eq('user_id', user.id)
      let calculatedProgress = 0
      if (goalTasks && goalTasks.length > 0) {
        const completed = goalTasks.filter(t => t.status === 'completed').length
        calculatedProgress = Math.min(99, Math.round((completed / goalTasks.length) * 100))
      }

      const { data: updated, error } = await supabase
        .from('goals')
        .update({ completed_at: null, status: 'active', progress: calculatedProgress })
        .eq('id', id)
        .eq('user_id', user.id)
        .select()
        .single()

      if (error) throw error

      await robustRemoveXP(user.id, 'goal_complete', id)

      setGoals((prev) => prev.map((g) => (g.id === id ? updated : g)))
      return updated
    } catch (error) {
      console.error('Error undoing goal:', error)
      return null
    }
  }, [user])

  const failGoal = useCallback(async (id, failureReason = null) => {
    if (!user) return null

    const goal = goals.find((g) => g.id === id)
    if (!goal) return null

    try {
      const updates = { status: 'failed', completed_at: new Date().toISOString() }
      if (failureReason && failureReason.trim()) {
        const currDesc = goal.description || ''
        const cleanReason = failureReason.trim()
        if (!currDesc.includes('[Failure Note]')) {
          updates.description = `${currDesc}\n\n[Failure Note]\n${cleanReason}`.trim()
        }
      }

      const { data: updated, error } = await supabase
        .from('goals')
        .update(updates)
        .eq('id', id)
        .eq('user_id', user.id)
        .select()
        .single()

      if (error) throw error

      // Determine XP penalty based on goal type
      const xpMap = {
        main_quest: XP_REWARDS.goal_complete_main,
        side_quest: XP_REWARDS.goal_complete_side,
        weekly: XP_REWARDS.goal_complete_weekly,
        long_term: XP_REWARDS.goal_complete_long_term,
      }
      const xpAmount = xpMap[goal.type] || XP_REWARDS.goal_complete_side

      await robustAwardXP(
        user.id,
        -xpAmount,
        'goal_failed',
        id,
        `Failed ${goal.type}: ${goal.title}`,
        toStatCat(goal.category)
      )

      setGoals((prev) => prev.map((g) => (g.id === id ? updated : g)))
      return updated
    } catch (error) {
      console.error('Error failing goal:', error)
      alert('Error failing goal: ' + (error?.message || error))
      return null
    }
  }, [user, goals])

  const undoFailGoal = useCallback(async (id) => {
    if (!user) return null

    try {
      const { data: updated, error } = await supabase
        .from('goals')
        .update({ status: 'active' })
        .eq('id', id)
        .eq('user_id', user.id)
        .select()
        .single()

      if (error) throw error

      await robustRemoveXP(user.id, 'goal_failed', id)

      setGoals((prev) => prev.map((g) => (g.id === id ? updated : g)))
      return updated
    } catch (error) {
      console.error('Error undoing failed goal:', error)
      return null
    }
  }, [user])

  const deleteGoal = useCallback(async (id, revokeXp = true) => {
    if (!user) return false

    try {
      const goal = goals.find((g) => g.id === id)
      if (revokeXp) {
        if (goal?.status === 'completed') {
          await robustRemoveXP(user.id, 'goal_complete', id)
        } else if (goal?.status === 'cancelled') {
          await robustRemoveXP(user.id, 'goal_failed', id)
        }
      }

      const { error } = await supabase
        .from('goals')
        .delete()
        .eq('id', id)
        .eq('user_id', user.id)

      if (error) throw error
      setGoals((prev) => prev.filter((g) => g.id !== id))
      return true
    } catch (error) {
      console.error('Error deleting goal:', error)
      return false
    }
  }, [user, goals])

  const togglePauseGoal = useCallback(async (id, currentStatus) => {
    if (!user) return null

    const newStatus = currentStatus === 'paused' ? 'active' : 'paused'

    try {
      const { data: updated, error } = await supabase
        .from('goals')
        .update({ status: newStatus })
        .eq('id', id)
        .eq('user_id', user.id)
        .select()
        .single()

      if (error) throw error
      setGoals((prev) => prev.map((g) => (g.id === id ? updated : g)))
      return updated
    } catch (error) {
      console.error('Error pausing goal:', error)
      return null
    }
  }, [user])

  const updateProgress = useCallback(async (id, progress) => {
    if (!user) return null

    try {
      const { data: updated, error } = await supabase
        .from('goals')
        .update({ progress })
        .eq('id', id)
        .eq('user_id', user.id)
        .select()
        .single()

      if (error) throw error
      setGoals((prev) => prev.map((g) => (g.id === id ? updated : g)))
      return updated
    } catch (error) {
      console.error('Error updating progress:', error)
      return null
    }
  }, [user])

  return {
    goals,
    mainQuest,
    mainQuests,
    sideQuests,
    longTermGoals,
    weeklyGoals,
    completedGoals,
    failedGoals,
    loading,
    error,
    fetchGoals,
    addGoal,
    updateGoal,
    completeGoal,
    undoCompleteGoal,
    failGoal,
    undoFailGoal,
    deleteGoal,
    togglePauseGoal,
    updateProgress,
  }
}

'use client'

import { useState, useEffect, useCallback, useMemo, useRef } from 'react'
import { createClient } from '@/lib/supabase/client'
import { robustAwardXP, robustRemoveXP } from '@/lib/utils/xpFallback'
import { getLocalDateStr } from '@/lib/utils/dates'
import { calculateAndUpdateStreak } from '@/lib/utils/streakCalc'
import { syncWarRoomHabitChange } from '@/lib/utils/warRoomSync'

/**
 * Calculates prior consecutive missed/failed scheduled days before targetDateStr for a habit.
 * Returns count of prior consecutive missed days.
 */
function getConsecutiveMisses(habitId, targetDateStr, allLogs, habit) {
  if (!habit) return 0
  const freqDays = habit.frequency_days || [0, 1, 2, 3, 4, 5, 6]
  let consecutiveMisses = 0

  const cur = new Date(targetDateStr)
  for (let i = 1; i <= 30; i++) {
    cur.setDate(cur.getDate() - 1)
    const curStr = getLocalDateStr(cur)
    const dayOfWeek = cur.getDay()

    // Skip non-scheduled days for this habit
    if (!freqDays.includes(dayOfWeek)) continue

    const log = (allLogs || []).find(l => l.habit_id === habitId && l.date === curStr)
    const status = log ? log.status : null

    if (status === 'completed') {
      // Habit was completed on this scheduled day -> breaks consecutive miss chain
      break
    } else if (status === 'failed' || !status || status === 'none') {
      // Habit was missed or failed on a scheduled day
      consecutiveMisses++
    }
  }

  return consecutiveMisses
}

export function useHabitsInternal(user) {
  const [allHabits, setAllHabits] = useState([])
  const [monthLogs, setMonthLogs] = useState([])
  const [loading, setLoading] = useState(true)
  const [error, setError] = useState(null)
  const [initialized, setInitialized] = useState(false)
  const processingRef = useRef(new Set())
  const autoFailRanRef = useRef(false)
  const supabase = createClient()

  const todayStr = getLocalDateStr()

  const habits = useMemo(() => {
    return allHabits.filter((h) => h.is_active !== false)
  }, [allHabits])

  const stoppedHabits = useMemo(() => {
    return allHabits.filter((h) => h.is_active === false)
  }, [allHabits])

  // Derive todayLogs from monthLogs for backward compat
  const todayLogs = useMemo(() => {
    return monthLogs.filter((l) => l.date === todayStr)
  }, [monthLogs, todayStr])

  const fetchHabits = useCallback(async (year, month) => {
    if (!user) {
      setAllHabits([])
      setMonthLogs([])
      setLoading(false)
      return
    }

    try {
      if (!initialized) {
        setLoading(true)
      }
      setError(null)

      // Calculate month range
      const now = new Date()
      const y = year ?? now.getFullYear()
      const m = month ?? now.getMonth() // 0-indexed
      const firstDay = `${y}-${String(m + 1).padStart(2, '0')}-01`
      const lastDay = new Date(y, m + 1, 0) // last day of month
      const lastDayStr = `${y}-${String(m + 1).padStart(2, '0')}-${String(lastDay.getDate()).padStart(2, '0')}`

      const [habitsRes, logsRes] = await Promise.all([
        supabase
          .from('habits')
          .select('*')
          .eq('user_id', user.id)
          .order('created_at', { ascending: true }),
        supabase
          .from('habit_logs')
          .select('*')
          .eq('user_id', user.id)
          .gte('date', firstDay)
          .lte('date', lastDayStr)
      ])

      if (habitsRes.error) throw habitsRes.error
      if (logsRes.error) throw logsRes.error

      const realLogs = logsRes.data || []
      const fetchedHabits = habitsRes.data || []

      // Read local custom order map
      const savedOrderMap = new Map()
      if (typeof window !== 'undefined' && user?.id) {
        try {
          const rawOrder = localStorage.getItem(`lokios_habit_order_${user.id}`)
          if (rawOrder) {
            const parsed = JSON.parse(rawOrder)
            if (Array.isArray(parsed)) {
              parsed.forEach((id, idx) => savedOrderMap.set(id, idx + 1))
            } else if (parsed && typeof parsed === 'object') {
              Object.entries(parsed).forEach(([id, idx]) => savedOrderMap.set(id, Number(idx)))
            }
          }
        } catch (e) {
          console.warn('Failed to parse local habit order:', e)
        }
      }

      fetchedHabits.sort((a, b) => {
        const orderA = a.display_order ?? (typeof a.order === 'number' ? a.order : null) ?? (typeof a.sort_order === 'number' ? a.sort_order : null) ?? (typeof a.position === 'number' ? a.position : null) ?? savedOrderMap.get(a.id) ?? 99999
        const orderB = b.display_order ?? (typeof b.order === 'number' ? b.order : null) ?? (typeof b.sort_order === 'number' ? b.sort_order : null) ?? (typeof b.position === 'number' ? b.position : null) ?? savedOrderMap.get(b.id) ?? 99999
        return (orderA - orderB) || (new Date(a.created_at) - new Date(b.created_at))
      })

      setAllHabits(fetchedHabits)
      setMonthLogs(realLogs)
    } catch (err) {
      console.error('Error fetching habits:', err)
      setError(err.message || JSON.stringify(err) || 'Failed to load data. Please refresh and try again.')
    } finally {
      setLoading(false)
      setInitialized(true)
    }
  }, [user])

  useEffect(() => {
    fetchHabits()
  }, [fetchHabits])

  // Cycle habit state: none -> completed -> failed -> none
  const cycleHabitState = useCallback(async (habitId, dateStr, forceStatus = null) => {
    if (!user) return null
    const currentTodayStr = getLocalDateStr()
    const targetDate = dateStr || currentTodayStr

    const existingLog = monthLogs.find((l) => l.habit_id === habitId && l.date === targetDate)
    const currentStatus = existingLog ? (existingLog.status || 'completed') : 'none'
    
    let nextStatus = forceStatus
    if (!nextStatus) {
      nextStatus = 'completed'
      if (currentStatus === 'completed') nextStatus = 'failed'
      if (currentStatus === 'failed') nextStatus = 'none'
    }

    // Skip if we are trying to force a status that is already the current status
    if (forceStatus && currentStatus === forceStatus) return true;

    const procKey = `${habitId}_${targetDate}_cycle`
    if (processingRef.current.has(procKey)) return null
    processingRef.current.add(procKey)

    // Optimistic UI Update
    const optimisticId = `opt_${habitId}_${targetDate}`
    setMonthLogs(prev => {
      const filtered = prev.filter(l => !(l.habit_id === habitId && l.date === targetDate))
      if (nextStatus === 'completed' || nextStatus === 'failed' || nextStatus === 'rest' || nextStatus === 'blocked') {
        return [...filtered, { id: optimisticId, habit_id: habitId, date: targetDate, status: nextStatus }]
      }
      return filtered
    })

    try {
      const stableSourceId = `habit_${habitId}_${targetDate}`
      const habit = habits.find((h) => h.id === habitId)

      // 1. Remove previous XP for this specific habit on this target date cleanly
      await robustRemoveXP(user.id, null, stableSourceId)
      // Also clean up any legacy entries keyed by log ID if existingLog was from DB
      if (existingLog && existingLog.id && !existingLog.id.startsWith('opt_') && !existingLog.id.startsWith('virtual_fail_')) {
        await robustRemoveXP(user.id, null, existingLog.id)
      }

      let newLog = null;
      // 2. Database Sync in habit_logs
      if (nextStatus === 'none') {
        await supabase.from('habit_logs').delete().eq('user_id', user.id).eq('habit_id', habitId).eq('date', targetDate)
      } else {
        const { data: upsertedRows, error: upsertErr } = await supabase.from('habit_logs')
          .upsert({ user_id: user.id, habit_id: habitId, date: targetDate, status: nextStatus }, { onConflict: 'habit_id,date' })
          .select()
        if (upsertErr) throw upsertErr
        if (upsertedRows && upsertedRows.length > 0) newLog = upsertedRows[0]
      }

      // Update local state with real DB log
      setMonthLogs(prev => {
        const withoutOpt = prev.filter(l => l.id !== optimisticId)
        return newLog ? [...withoutOpt, newLog] : withoutOpt
      })

      // 3. Award/Penalize New XP anchored to targetDate
      if (nextStatus === 'completed' || nextStatus === 'failed') {
        const targetDayOfWeek = new Date(targetDate).getDay()
        const freqDays = habit?.frequency_days || [0, 1, 2, 3, 4, 5, 6]
        const isBlocked = !freqDays.includes(targetDayOfWeek)
        const baseXP = habit?.xp_per_completion ? Math.max(5, parseInt(habit.xp_per_completion, 10)) : 25
        const createdAt = targetDate === currentTodayStr ? new Date().toISOString() : `${targetDate}T12:00:00.000Z`

        if (nextStatus === 'completed') {
          await robustAwardXP(
            user.id,
            isBlocked ? 0 : baseXP,
            'habit_complete',
            stableSourceId,
            `Completed routine: ${habit?.title || 'Unknown'}`,
            habit?.stat_category || 'discipline',
            createdAt
          )
        } else if (nextStatus === 'failed') {
          const priorMisses = getConsecutiveMisses(habitId, targetDate, monthLogs, habit)
          const isDoublePenalty = priorMisses >= 1
          const penaltyMagnitude = isDoublePenalty ? baseXP : Math.max(5, Math.round(baseXP * 0.5))
          const penaltyXP = isBlocked ? 0 : -penaltyMagnitude
          const reason = isDoublePenalty 
            ? `🚨 DOUBLE PENALTY (2+ Consecutive Misses): ${habit?.title || 'Unknown'} (-${penaltyMagnitude} XP)` 
            : `Failed routine: ${habit?.title || 'Unknown'} (-${penaltyMagnitude} XP)`
          await robustAwardXP(
            user.id,
            penaltyXP,
            'habit_failed',
            stableSourceId,
            reason,
            habit?.stat_category || 'discipline',
            createdAt
          )
        }
      }

      // Persistently update War Room Battle HP in DB for ALL status transitions
      await syncWarRoomHabitChange(user.id, habitId, habit?.title || 'Habit', currentStatus, nextStatus)

      try { 
        await calculateAndUpdateStreak(user.id, habitId)

        // ── DAILY ALL-HABITS BONUS ──
        // Check if every active habit has a completed log for today
        if (nextStatus === 'completed' && targetDate === currentTodayStr && habits) {
          const dailyBonusKey = `daily_all_bonus_${currentTodayStr}`
          if (!localStorage.getItem(dailyBonusKey)) {
            // Get the latest monthLogs state to check completion
            const todayCompletedIds = new Set()
            todayCompletedIds.add(habitId)
            monthLogs.forEach(l => {
              if (l.date === currentTodayStr && (!l.status || l.status === 'completed')) {
                todayCompletedIds.add(l.habit_id)
              }
            })
            const allDone = habits.every(h => todayCompletedIds.has(h.id))
            if (allDone && habits.length > 0) {
              await robustAwardXP(user.id, XP_REWARDS.daily_all_habits || 25, 'daily_all_complete', `daily_all_${currentTodayStr}`, '🏆 100% OPERATIONAL — All daily ops completed!', 'discipline')
              localStorage.setItem(dailyBonusKey, 'true')
            }
          }
        }

        // ── STREAK MILESTONE REWARDS ──
        const { data: profileData } = await supabase.from('profiles').select('streak_days').eq('id', user.id).single()
        if (profileData?.streak_days) {
          const streak = profileData.streak_days
          const milestones = [
            { days: 7, xp: XP_REWARDS.streak_7_days || 50, label: '🔥 7-Day Streak!' },
            { days: 30, xp: XP_REWARDS.streak_30_days || 200, label: '🔥🔥 30-Day Streak!' },
            { days: 100, xp: XP_REWARDS.streak_100_days || 500, label: '🔥🔥🔥 100-Day Streak!' }
          ]
          for (const milestone of milestones) {
            if (streak >= milestone.days) {
              const streakKey = `streak_reward_${milestone.days}`
              if (!localStorage.getItem(streakKey)) {
                await robustAwardXP(user.id, milestone.xp, 'streak_milestone', `streak_${milestone.days}`, `${milestone.label} — ${milestone.xp} XP bonus unlocked!`, 'discipline')
                localStorage.setItem(streakKey, 'true')
              }
            }
          }
        }
      } catch (e) {
        console.error('Streak update failed:', e)
      }
      return true
    } catch (error) {
      console.error('Error cycling habit:', error)
      alert(`SYSTEM ERROR: ${error.message || JSON.stringify(error)}`)
      // DEBUG: Log error to xp_history so I can read it
      supabase.from('xp_history').insert({
        user_id: user.id,
        amount: 0,
        source_type: 'error_log',
        source_id: habitId,
        description: String(error.message || JSON.stringify(error))
      }).then()
      
      // Rollback optimistic update
      setMonthLogs(prev => {
        const filtered = prev.filter(l => l.id !== optimisticId)
        if (existingLog) {
          return [...filtered, existingLog]
        }
        return filtered
      })
      return null
    } finally {
      processingRef.current.delete(procKey)
    }
  }, [user, habits, monthLogs, todayStr])

  // Backward-compat wrapper
  const toggleHabitForDate = useCallback(async (habitId, dateStr, newStatus) => {
    return cycleHabitState(habitId, dateStr, newStatus)
  }, [cycleHabitState])

  // Simple toggle checking/unchecking for UI elements
  const toggleHabit = useCallback(async (habitId) => {
    const existingLog = monthLogs.find((l) => l.habit_id === habitId && l.date === todayStr)
    const currentStatus = existingLog ? (existingLog.status || 'completed') : 'none'
    const nextStatus = currentStatus === 'completed' ? 'none' : 'completed'
    return cycleHabitState(habitId, todayStr, nextStatus)
  }, [monthLogs, todayStr, cycleHabitState])

  const addHabit = useCallback(async (data) => {
    if (!user) return null

    try {
      const nextOrder = (habits?.length || 0) + 1
      const payload = { created_at: new Date().toISOString(), is_active: true, display_order: nextOrder, ...data, user_id: user.id }
      let newHabit = null
      const { data: inserted, error } = await supabase
        .from('habits')
        .insert(payload)
        .select()
        .single()

      if (error) {
        const fallbackPayload = { ...payload }
        delete fallbackPayload.display_order
        const { data: fallbackInserted, error: fallbackError } = await supabase
          .from('habits')
          .insert(fallbackPayload)
          .select()
          .single()
        if (fallbackError) throw fallbackError
        newHabit = fallbackInserted
      } else {
        newHabit = inserted
      }

      if (newHabit) {
        setAllHabits((prev) => [...prev, newHabit])
        if (typeof window !== 'undefined' && user?.id) {
          try {
            const raw = localStorage.getItem(`lokios_habit_order_${user.id}`)
            const currentOrder = raw ? JSON.parse(raw) : []
            if (Array.isArray(currentOrder) && !currentOrder.includes(newHabit.id)) {
              localStorage.setItem(`lokios_habit_order_${user.id}`, JSON.stringify([...currentOrder, newHabit.id]))
            }
          } catch (e) {}
        }
      }
      return newHabit
    } catch (error) {
      console.error('Error adding habit:', error)
      return null
    }
  }, [user, habits?.length])

  const deleteHabit = useCallback(async (habitId) => {
    if (!user) return null
    try {
      const { error } = await supabase
        .from('habits')
        .delete()
        .eq('id', habitId)
        .eq('user_id', user.id)
      if (error) throw error
      setAllHabits((prev) => prev.filter((h) => h.id !== habitId))
      if (typeof window !== 'undefined' && user?.id) {
        try {
          const raw = localStorage.getItem(`lokios_habit_order_${user.id}`)
          const currentOrder = raw ? JSON.parse(raw) : []
          if (Array.isArray(currentOrder)) {
            localStorage.setItem(`lokios_habit_order_${user.id}`, JSON.stringify(currentOrder.filter(id => id !== habitId)))
          }
        } catch (e) {}
      }
      return true
    } catch (error) {
      console.error('Error deleting habit:', error)
      return null
    }
  }, [user])

  const stopHabit = useCallback(async (habitId) => {
    if (!user) return null
    try {
      const stoppedAt = new Date().toISOString()
      const { error } = await supabase
        .from('habits')
        .update({ is_active: false, stopped_at: stoppedAt })
        .eq('id', habitId)
        .eq('user_id', user.id)

      if (error) {
        const { error: err2 } = await supabase
          .from('habits')
          .update({ is_active: false })
          .eq('id', habitId)
          .eq('user_id', user.id)
        if (err2) throw err2
      }

      setAllHabits((prev) => prev.map((h) => (h.id === habitId ? { ...h, is_active: false, stopped_at: stoppedAt } : h)))
      return true
    } catch (error) {
      console.error('Error stopping habit:', error)
      return null
    }
  }, [user])

  const resumeHabit = useCallback(async (habitId) => {
    if (!user) return null
    try {
      const { error } = await supabase
        .from('habits')
        .update({ is_active: true, stopped_at: null })
        .eq('id', habitId)
        .eq('user_id', user.id)

      if (error) {
        const { error: err2 } = await supabase
          .from('habits')
          .update({ is_active: true })
          .eq('id', habitId)
          .eq('user_id', user.id)
        if (err2) throw err2
      }

      setAllHabits((prev) => prev.map((h) => (h.id === habitId ? { ...h, is_active: true, stopped_at: null } : h)))
      return true
    } catch (error) {
      console.error('Error resuming habit:', error)
      return null
    }
  }, [user])

  const archiveHabit = useCallback(async (habitId) => {
    return stopHabit(habitId)
  }, [stopHabit])

  const updateHabit = useCallback(async (habitId, updates) => {
    if (!user) return null
    try {
      const { data, error } = await supabase.from('habits').update(updates).eq('id', habitId).eq('user_id', user.id).select().single()
      if (error) throw error
      setAllHabits((prev) => prev.map(h => h.id === habitId ? data : h))
      return data
    } catch (error) {
      console.error('Error updating habit:', error)
      if (typeof window !== 'undefined') {
        alert("DB Update Error: " + (error.message || JSON.stringify(error)))
      }
      return null
    }
  }, [user])

  const reorderHabits = useCallback(async (habitId, direction) => {
    if (!user) return
    const activeHabits = [...habits]
    const index = activeHabits.findIndex(h => h.id === habitId)
    if (index === -1) return
    
    let swapIndex = direction === 'up' ? index - 1 : index + 1
    if (swapIndex < 0 || swapIndex >= activeHabits.length) return
    
    const [moved] = activeHabits.splice(index, 1)
    activeHabits.splice(swapIndex, 0, moved)
    
    const updatedActive = activeHabits.map((h, i) => ({
      ...h,
      display_order: i + 1
    }))

    // Keep stopped habits intact in allHabits so they are not dropped
    const currentStopped = allHabits.filter(h => h.is_active === false)
    const updatedAll = [...updatedActive, ...currentStopped]
    setAllHabits(updatedAll)

    // Save exact order array in localStorage for 100% instant and unbreakable persistence
    const orderIds = updatedActive.map(h => h.id)
    if (typeof window !== 'undefined' && user?.id) {
      try {
        localStorage.setItem(`lokios_habit_order_${user.id}`, JSON.stringify(orderIds))
      } catch (e) {}
    }

    // Persist to Supabase with progressive fallbacks
    const supabase = createClient()
    for (const h of updatedActive) {
      try {
        const { error: err1 } = await supabase
          .from('habits')
          .update({ display_order: h.display_order })
          .eq('id', h.id)
          .eq('user_id', user.id)

        if (err1) {
          await supabase.from('habits').update({ order: h.display_order }).eq('id', h.id).eq('user_id', user.id)
        }
      } catch (e) {
        console.warn('Failed to sync habit order to DB (local storage preserved):', e)
      }
    }
  }, [habits, allHabits, user])

  const reorderHabitsByDrag = useCallback(async (draggedId, targetId) => {
    if (!draggedId || !targetId || draggedId === targetId || !user) return
    const activeHabits = [...habits]
    const dragIdx = activeHabits.findIndex(h => h.id === draggedId)
    const targetIdx = activeHabits.findIndex(h => h.id === targetId)
    if (dragIdx === -1 || targetIdx === -1) return

    const [moved] = activeHabits.splice(dragIdx, 1)
    activeHabits.splice(targetIdx, 0, moved)

    const updatedActive = activeHabits.map((h, i) => ({
      ...h,
      display_order: i + 1
    }))

    // Keep stopped habits intact in allHabits
    const currentStopped = allHabits.filter(h => h.is_active === false)
    const updatedAll = [...updatedActive, ...currentStopped]
    setAllHabits(updatedAll)

    // Save exact order array in localStorage
    const orderIds = updatedActive.map(h => h.id)
    if (typeof window !== 'undefined' && user?.id) {
      try {
        localStorage.setItem(`lokios_habit_order_${user.id}`, JSON.stringify(orderIds))
      } catch (e) {}
    }

    // Persist to Supabase with progressive fallbacks
    const supabase = createClient()
    for (const h of updatedActive) {
      try {
        const { error: err1 } = await supabase
          .from('habits')
          .update({ display_order: h.display_order })
          .eq('id', h.id)
          .eq('user_id', user.id)

        if (err1) {
          await supabase.from('habits').update({ order: h.display_order }).eq('id', h.id).eq('user_id', user.id)
        }
      } catch (e) {
        console.warn('Failed to sync habit order to DB (local storage preserved):', e)
      }
    }
  }, [habits, allHabits, user])

  // Auto-fail untouched habits
  useEffect(() => {
    if (!initialized || !user || habits.length === 0 || autoFailRanRef.current) return
    
    const runAutoFail = async () => {
      if (localStorage.getItem('daily_ops_autofail_ran_today') === todayStr) {
        autoFailRanRef.current = true
        return
      }
      
      const storedResetDate = localStorage.getItem('last_reset_date')
      // Default to June 29th, 2026 so users returning at the end of June aren't retroactively penalized for the whole month
      const RESET_DATE = storedResetDate ? new Date(storedResetDate) : new Date('2026-06-29T00:00:00Z')
      const now = new Date()
      const yesterday = new Date(now)
      yesterday.setDate(yesterday.getDate() - 1)
      
      const thirtyDaysAgo = new Date(now)
      thirtyDaysAgo.setDate(now.getDate() - 30)

      let globalStartDate = Math.max(RESET_DATE.getTime(), thirtyDaysAgo.getTime())
      for (const h of habits) {
        const hc = new Date(h.created_at).getTime()
        if (hc < globalStartDate) globalStartDate = hc // Wait, we actually want the oldest possible start date across all habits, bounded by 30 days ago.
      }
      globalStartDate = Math.max(globalStartDate, thirtyDaysAgo.getTime(), RESET_DATE.getTime())
      
      const { data: recentLogs } = await supabase
        .from('habit_logs')
        .select('habit_id, date')
        .eq('user_id', user.id)
        .gte('date', getLocalDateStr(new Date(globalStartDate)))

      const logMap = new Set((recentLogs || []).map(l => `${l.habit_id}_${l.date}`))
      
      let createdAny = false
      let newVirtualLogs = []
      let dbInsertPayloads = []
      
      for (const h of habits) {
        const habitCreatedDate = new Date(h.created_at)
        let startDate = new Date(Math.max(RESET_DATE.getTime(), habitCreatedDate.getTime(), thirtyDaysAgo.getTime()))
        
        for (let d = new Date(startDate); ; d.setDate(d.getDate() + 1)) {
          const dateStr = getLocalDateStr(d)
          if (dateStr >= todayStr) break // NEVER auto-fail today or future dates!
          
          const dayOfWeek = d.getDay()
          const freqDays = h.frequency_days || [0, 1, 2, 3, 4, 5, 6]
          
          // Skip auto-fail if today is not a scheduled day for this habit
          if (!freqDays.includes(dayOfWeek)) continue;

          if (!logMap.has(`${h.id}_${dateStr}`)) {
            const procKey = `${h.id}_${dateStr}_autofail`
            if (!processingRef.current.has(procKey)) {
              processingRef.current.add(procKey)
              
              const baseXP = h.xp_per_completion ? Math.max(5, parseInt(h.xp_per_completion, 10)) : 25
              const priorMisses = getConsecutiveMisses(h.id, dateStr, recentLogs, h)
              const isDoublePenalty = priorMisses >= 1
              const penaltyMagnitude = isDoublePenalty ? baseXP : Math.max(5, Math.round(baseXP * 0.5))
              const penaltyXP = -penaltyMagnitude
              const reason = isDoublePenalty 
                ? `🚨 DOUBLE PENALTY (2+ Consecutive Misses): ${h.title} (-${penaltyMagnitude} XP)` 
                : `Missed routine: ${h.title} (-${penaltyMagnitude} XP)`

              const stableSourceId = `habit_${h.id}_${dateStr}`
              const createdAt = `${dateStr}T12:00:00.000Z`
              await robustAwardXP(user.id, penaltyXP, 'habit_failed', stableSourceId, reason, h.stat_category || 'discipline', createdAt)
              
              newVirtualLogs.push({ id: stableSourceId, habit_id: h.id, date: dateStr, status: 'failed' })
              dbInsertPayloads.push({ user_id: user.id, habit_id: h.id, date: dateStr, status: 'failed' })
              createdAny = true
            }
          }
        }
      }
      
      if (dbInsertPayloads.length > 0) {
        await supabase.from('habit_logs').upsert(dbInsertPayloads, { onConflict: 'habit_id,date' })
      }
      
      if (newVirtualLogs.length > 0) {
        setMonthLogs(prev => {
          const newKeys = new Set(newVirtualLogs.map(l => `${l.habit_id}_${l.date}`))
          const filtered = prev.filter(l => !newKeys.has(`${l.habit_id}_${l.date}`))
          return [...filtered, ...newVirtualLogs]
        })
      }
      
      if (createdAny) {
        try { await calculateAndUpdateStreak(user.id) } catch (e) { console.error('Streak update failed:', e) }
      }
      localStorage.setItem('daily_ops_autofail_ran_today', todayStr)
      autoFailRanRef.current = true
    }
    
    runAutoFail()
  }, [initialized, user, habits, todayStr]) // Omitted monthLogs from deps to prevent loop

  return {
    habits,
    stoppedHabits,
    allHabits,
    monthLogs,
    todayLogs,
    loading,
    error,
    fetchHabits,
    cycleHabitState,
    toggleHabit,
    toggleHabitForDate,
    addHabit,
    deleteHabit,
    stopHabit,
    resumeHabit,
    archiveHabit: stopHabit,
    updateHabit,
    reorderHabits,
    reorderHabitsByDrag
  }
}

'use client'

import { useState, useEffect, useCallback, useMemo } from 'react'
import { createClient } from '@/lib/supabase/client'
import { getLocalDateStr } from '@/lib/utils/dates'


export function useJournalInternal(user) {
  const [entries, setEntries] = useState([])
  const [loading, setLoading] = useState(true)
  const supabase = createClient()

  const fetchEntries = useCallback(async () => {
    if (!user) {
      setEntries([])
      setLoading(false)
      return
    }

    try {
      setLoading(true)
      const { data, error } = await supabase
        .from('journal_entries')
        .select('*')
        .eq('user_id', user.id)
        .order('date', { ascending: false })

      if (error) throw error
      const normalized = (data || []).map(item => ({
        ...item,
        content: item.content || item.what_did_i_do || item.reflection || item.description || ''
      }))
      setEntries(normalized)
    } catch (error) {
      console.error('Error fetching journal entries:', error)
    } finally {
      setLoading(false)
    }
  }, [user])

  useEffect(() => {
    fetchEntries()
  }, [fetchEntries])

  // No longer locking to one entry per day

  const saveEntry = useCallback(async (data) => {
    if (!user) return null

    const todayStr = getLocalDateStr()
    const entryDate = data.date || todayStr

    try {
      // Always create a new entry
      let result;
        const dbPayload = {
          user_id: user.id,
          date: entryDate,
          mood: data.mood,
          what_did_i_do: data.content,
          word_count: data.content ? data.content.split(/\s+/).length : 0
        }

        const { data: newEntry, error } = await supabase
          .from('journal_entries')
          .insert(dbPayload)
          .select()
          .single()

        if (error) throw error
        result = newEntry
        const normalizedNew = {
          ...newEntry,
          content: newEntry.content || newEntry.what_did_i_do || newEntry.reflection || newEntry.description || data.content || ''
        }
        setEntries((prev) => [normalizedNew, ...prev])

      return result
    } catch (error) {
      console.error('Error saving journal entry:', error)
      if (typeof window !== 'undefined') {
        alert(`SYSTEM ERROR SAVING JOURNAL: ${error.message || JSON.stringify(error)}`)
      }
      return null
    }
  }, [user, entries])

  const clearJournal = useCallback(async () => {
    if (!user) return false
    try {
      setLoading(true)
      const { error } = await supabase
        .from('journal_entries')
        .delete()
        .eq('user_id', user.id)
      
      if (error) throw error
      setEntries([])
      return true
    } catch (error) {
      console.error('Error clearing journal:', error)
      return false
    } finally {
      setLoading(false)
    }
  }, [user])

  return { entries, loading, saveEntry, clearJournal }
}

